-- PuudDai: 13 travel units (auto-generated, QA-verified). Idempotent: re-run safe (IF NOT EXISTS on order_index).
-- Reorder existing units into the trip-journey sequence first:
UPDATE units SET order_index = 5  WHERE title_th = $q$ผ่านด่าน ตม.$q$;
UPDATE units SET order_index = 10 WHERE title_th = $q$ศัพท์ร้านกาแฟ$q$;

-- Unit 2: ตัวเลข เวลา ป้าย และขอความช่วยเหลือ
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 2) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 2, $q$ตัวเลข เวลา ป้าย และขอความช่วยเหลือ$q$, $q$ตัวเลข ราคา เวลา วันที่ สะกดชื่อ อ่านป้าย และวลีขอความช่วยเหลือ/ฉุกเฉิน$q$, 'A0', $q$🔢$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ตัวเลข 0–1000 และราคา/เงินทอน$q$, $q${"listen":{"audioText":"Cashier: That's fifteen dollars, please. (hear) You: Here's twenty. Cashier: Thank you. Your change is five dollars. (hear)","thaiExplain":"ตอนซื้อของ พนักงานจะบอกราคาเป็นตัวเลข ฟังให้ทันแล้วจ่ายเงิน ถ้าจ่ายเกินจะได้เงินทอน (change) กลับมา ถ้าฟังราคาไม่ทัน พูดว่า \"How much?\" เพื่อถามซ้ำได้"},"vocab":[{"word":"how much","ipa":"/haʊ ˈmʌtʃ/","thai":"ราคาเท่าไร","exampleEn":"How much is this?","exampleTh":"อันนี้ราคาเท่าไร","associationHintTh":"\"เฮา-มัช\" = ถามว่า มัช (มาก) เท่าไร คือถามราคา"},{"word":"change","ipa":"/tʃeɪndʒ/","thai":"เงินทอน","exampleEn":"Here is your change.","exampleTh":"นี่เงินทอนของคุณ","associationHintTh":"change = การเปลี่ยน จ่ายเกินแล้วเขา \"เปลี่ยน\" เป็นเงินทอนคืนให้"},{"word":"hundred","ipa":"/ˈhʌndrəd/","thai":"ร้อย (100)","exampleEn":"That's one hundred baht.","exampleTh":"รวมหนึ่งร้อยบาท","associationHintTh":"\"ฮัน-เดรด\" นึกถึงเลข 100 เต็มร้อย"},{"word":"thousand","ipa":"/ˈθaʊzənd/","thai":"พัน (1000)","exampleEn":"It costs one thousand baht.","exampleTh":"ราคาหนึ่งพันบาท","associationHintTh":"\"เธา-เซินด์\" เสียงคล้าย \"เท่า\" เยอะ = หลักพัน"},{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"I will pay cash.","exampleTh":"ฉันจะจ่ายเงินสด","associationHintTh":"\"แคช\" = แคชเชียร์รับเงินสด"}],"examples":[{"en":"How much is it?","th":"ราคาเท่าไร"},{"en":"It's fifty baht.","th":"ราคาห้าสิบบาท"},{"en":"That's one hundred and twenty baht.","th":"รวมหนึ่งร้อยยี่สิบบาท"},{"en":"Can I pay by card?","th":"จ่ายด้วยบัตรได้ไหม"},{"en":"Here's your change, thirty baht.","th":"นี่เงินทอนของคุณ สามสิบบาท"},{"en":"Do you have smaller change?","th":"มีเงินย่อยไหม"}],"quiz":[{"questionTh":"\"How much is it?\" แปลว่าอะไร","choices":["ราคาเท่าไร","ตอนนี้กี่โมง","ห้องน้ำอยู่ไหน","คุณชื่ออะไร"],"answerIndex":0,"explainTh":"How much ใช้ถามราคาว่าเท่าไร ส่วนถามเวลาใช้ What time, ถามทางใช้ Where"},{"questionTh":"พนักงานพูดว่า \"Your change is 20 baht.\" หมายความว่าอะไร","choices":["ราคา 20 บาท","เงินทอน 20 บาท","ลดราคา 20 บาท","เหลือของ 20 ชิ้น"],"answerIndex":1,"explainTh":"change ในบริบทจ่ายเงินคือ \"เงินทอน\" ที่ได้คืนหลังจ่ายเกิน"},{"questionTh":"\"หนึ่งร้อย\" ภาษาอังกฤษพูดว่าอะไร","choices":["one thousand","one million","one hundred","one dozen"],"answerIndex":2,"explainTh":"หนึ่งร้อย = one hundred; thousand คือพัน, million คือล้าน, dozen คือโหล (12)"},{"questionTh":"\"เงินสด\" ภาษาอังกฤษคือคำไหน","choices":["change","card","coin","cash"],"answerIndex":3,"explainTh":"cash = เงินสด; change คือเงินทอน, card คือบัตร, coin คือเหรียญ"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$เวลา วัน เดือน วันที่ และเลขลำดับ/ชั้น$q$, $q${"listen":{"audioText":"You: Excuse me, what time is check-out? Receptionist: Check-out is at eleven o'clock. (hear) You: And where is breakfast? Receptionist: On the second floor, from seven to ten. (hear)","thaiExplain":"ถามเวลาใช้ \"What time...?\" บอกเวลาเป็นชั่วโมงเช่น eleven o'clock (11 โมง) ชั้นของตึกใช้เลขลำดับเช่น second floor (ชั้น 2) ฟังเวลาเปิด-ปิดให้ดี"},"vocab":[{"word":"what time","ipa":"/wɒt taɪm/","thai":"กี่โมง","exampleEn":"What time is it?","exampleTh":"ตอนนี้กี่โมง","associationHintTh":"\"วอท ไทม์\" = ถามหา time (เวลา) ว่าเท่าไร"},{"word":"o'clock","ipa":"/əˈklɒk/","thai":"โมง (ตรง)","exampleEn":"It's nine o'clock.","exampleTh":"ตอนนี้เก้าโมง","associationHintTh":"o'clock มาจาก of the clock บอกชั่วโมงตรงบนหน้าปัดนาฬิกา"},{"word":"floor","ipa":"/flɔː(r)/","thai":"ชั้น (ของตึก)","exampleEn":"My room is on the third floor.","exampleTh":"ห้องฉันอยู่ชั้นสาม","associationHintTh":"\"ฟลอร์\" = พื้น แต่ละพื้นคือแต่ละชั้น"},{"word":"today","ipa":"/təˈdeɪ/","thai":"วันนี้","exampleEn":"What is today's date?","exampleTh":"วันนี้วันที่เท่าไร","associationHintTh":"to-day = วัน (day) นี้"},{"word":"second","ipa":"/ˈsekənd/","thai":"ที่สอง / ชั้นสอง","exampleEn":"Take the second door.","exampleTh":"ไปที่ประตูที่สอง","associationHintTh":"second มาจาก two ลำดับที่ 2 (first-second-third)"}],"examples":[{"en":"What time is it?","th":"ตอนนี้กี่โมง"},{"en":"It's half past six.","th":"ตอนนี้หกโมงครึ่ง"},{"en":"What time do you open?","th":"เปิดกี่โมง"},{"en":"We open at nine a.m.","th":"เราเปิดเก้าโมงเช้า"},{"en":"My flight is on Monday.","th":"เที่ยวบินของฉันวันจันทร์"},{"en":"The room is on the fifth floor.","th":"ห้องอยู่ชั้นห้า"},{"en":"See you tomorrow.","th":"เจอกันพรุ่งนี้"}],"quiz":[{"questionTh":"\"What time is it?\" ใช้ถามเรื่องอะไร","choices":["ถามราคา","ถามเวลา","ถามทาง","ถามชื่อ"],"answerIndex":1,"explainTh":"What time ใช้ถามเวลาว่าตอนนี้กี่โมง"},{"questionTh":"\"second floor\" หมายถึงชั้นไหน","choices":["ชั้น 2","ชั้น 1","ชั้น 12","ชั้นล่างสุด"],"answerIndex":0,"explainTh":"second = ที่สอง ดังนั้น second floor คือชั้น 2"},{"questionTh":"\"It's seven o'clock.\" แปลว่าอะไร","choices":["วันที่เจ็ด","เจ็ดนาที","เจ็ดโมง","เจ็ดวัน"],"answerIndex":2,"explainTh":"o'clock บอกชั่วโมงตรง seven o'clock = เจ็ดโมง"},{"questionTh":"อยากถามว่าโรงแรมเช็คเอาท์กี่โมง พูดว่าอะไร","choices":["Where is check-out?","How much is check-out?","Who is check-out?","What time is check-out?"],"answerIndex":3,"explainTh":"ถามเวลาต้องใช้ What time; Where ถามที่, How much ถามราคา, Who ถามคน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$สะกดชื่อ บอกเบอร์/เลขห้อง และอ่านป้ายที่พบบ่อย$q$, $q${"listen":{"audioText":"Receptionist: Can you spell your name, please? (hear) You: Yes. S-U-D-A, Suda. Receptionist: Thank you. Your room number is 305. (hear) You: Sorry, is that three-oh-five? Receptionist: Yes, that's correct. (hear)","thaiExplain":"เวลาเช็คอิน พนักงานอาจให้สะกดชื่อทีละตัวอักษร (spell) เลขห้องมักอ่านทีละตัว เช่น 305 = three-oh-five (เลข 0 อ่านว่า \"oh\") ป้ายทั่วไปเช่น Exit, Push, Pull ควรจำไว้"},"vocab":[{"word":"spell","ipa":"/spel/","thai":"สะกด (ทีละตัวอักษร)","exampleEn":"How do you spell it?","exampleTh":"สะกดยังไง","associationHintTh":"\"สเปล\" = สะกดชื่อทีละตัวอักษร A-B-C"},{"word":"exit","ipa":"/ˈeksɪt/","thai":"ทางออก","exampleEn":"Where is the exit?","exampleTh":"ทางออกอยู่ไหน","associationHintTh":"ป้าย EXIT สีเขียวคือทางออก ตรงข้ามกับ entrance (ทางเข้า)"},{"word":"push","ipa":"/pʊʃ/","thai":"ผลัก / ดัน (ป้ายที่ประตู)","exampleEn":"The sign says push.","exampleTh":"ป้ายบอกว่าให้ผลัก","associationHintTh":"\"พุช\" = ดันประตูออกไปข้างหน้า"},{"word":"pull","ipa":"/pʊl/","thai":"ดึง (ป้ายที่ประตู)","exampleEn":"You need to pull the door.","exampleTh":"ต้องดึงประตูเข้าหาตัว","associationHintTh":"\"พูล\" = ดึงเข้าหาตัว ตรงข้ามกับ push"},{"word":"room number","ipa":"/ruːm ˈnʌmbə(r)/","thai":"หมายเลขห้อง","exampleEn":"My room number is 512.","exampleTh":"เลขห้องฉันคือ 512","associationHintTh":"room (ห้อง) + number (หมายเลข) = เลขห้อง"}],"examples":[{"en":"Can you spell your name?","th":"สะกดชื่อของคุณได้ไหม"},{"en":"My name is Nok. N-O-K.","th":"ฉันชื่อนก N-O-K"},{"en":"What is your phone number?","th":"เบอร์โทรของคุณอะไร"},{"en":"My room is 408.","th":"ห้องของฉันคือ 408"},{"en":"Where is the exit?","th":"ทางออกอยู่ที่ไหน"},{"en":"The sign says 'No entry'.","th":"ป้ายบอกว่า \"ห้ามเข้า\""},{"en":"Please push the door.","th":"กรุณาผลักประตู"}],"quiz":[{"questionTh":"พนักงานพูดว่า \"Can you spell your name?\" ต้องการให้เราทำอะไร","choices":["บอกราคา","สะกดชื่อทีละตัวอักษร","บอกเวลา","บอกที่อยู่"],"answerIndex":1,"explainTh":"spell = สะกด พนักงานอยากให้อ่านชื่อทีละตัวอักษร"},{"questionTh":"ป้ายที่ประตูเขียนว่า \"PUSH\" ต้องทำอย่างไร","choices":["ผลัก/ดันประตู","ดึงประตูเข้าหาตัว","ห้ามเข้า","รอสักครู่"],"answerIndex":0,"explainTh":"push = ผลัก/ดันออกไป; ถ้าเขียน pull ถึงจะดึงเข้าหาตัว"},{"questionTh":"\"Exit\" คือป้ายบอกอะไร","choices":["ทางเข้า","ห้องน้ำ","ทางออก","ห้ามสูบบุหรี่"],"answerIndex":2,"explainTh":"exit = ทางออก; ทางเข้าคือ entrance, ห้องน้ำคือ toilet/restroom"},{"questionTh":"เลขห้อง 305 พนักงานมักอ่านว่าอย่างไร","choices":["three hundred and five","thirty-oh-five","three five","three-oh-five"],"answerIndex":3,"explainTh":"เลขห้องมักอ่านทีละตัว และเลข 0 อ่านว่า \"oh\" จึงเป็น three-oh-five"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$ขอพูดซ้ำ/พูดช้าลง บอกว่าไม่เข้าใจ และวลีฉุกเฉิน (Help!)$q$, $q${"listen":{"audioText":"You: Sorry, I don't understand. Could you speak more slowly, please? Staff: Sure. Do you need help? (hear) You: Yes. I am lost. Can you help me? Staff: Don't worry, I can help you. (hear)","thaiExplain":"ถ้าฟังไม่ทันหรือไม่เข้าใจ พูดว่า \"Sorry, I don't understand.\" แล้วขอให้พูดช้าลง \"Could you speak more slowly?\" ถ้ามีเหตุฉุกเฉิน ให้ท่องวลีสั้นๆ ไว้ใช้ทันที เช่น \"Help!\" และ \"Call the police!\" ท่องให้ขึ้นใจเลย"},"vocab":[{"word":"help","ipa":"/help/","thai":"ช่วย / ความช่วยเหลือ","exampleEn":"Help! Please help me!","exampleTh":"ช่วยด้วย! ช่วยฉันหน่อย!","associationHintTh":"\"เฮลป์\" ตะโกนสั้นๆ คำเดียวเมื่อต้องการความช่วยเหลือด่วน"},{"word":"slowly","ipa":"/ˈsləʊli/","thai":"ช้าๆ","exampleEn":"Please speak slowly.","exampleTh":"กรุณาพูดช้าๆ","associationHintTh":"slow (ช้า) + ly = อย่างช้าๆ"},{"word":"understand","ipa":"/ˌʌndəˈstænd/","thai":"เข้าใจ","exampleEn":"I don't understand.","exampleTh":"ฉันไม่เข้าใจ","associationHintTh":"ถ้าไม่เข้าใจ ใส่ don't ข้างหน้า: I don't understand"},{"word":"repeat","ipa":"/rɪˈpiːt/","thai":"พูดซ้ำ","exampleEn":"Can you repeat that, please?","exampleTh":"พูดซ้ำอีกทีได้ไหม","associationHintTh":"\"รีพีท\" ปุ่ม repeat บนเครื่องเล่นเพลง = เล่นซ้ำ"},{"word":"doctor","ipa":"/ˈdɒktə(r)/","thai":"หมอ / แพทย์","exampleEn":"I need a doctor.","exampleTh":"ฉันต้องการหมอ","associationHintTh":"\"ด็อกเตอร์\" คำที่คนไทยคุ้นอยู่แล้ว = หมอ"},{"word":"police","ipa":"/pəˈliːs/","thai":"ตำรวจ","exampleEn":"Call the police!","exampleTh":"เรียกตำรวจ!","associationHintTh":"\"โพลีส\" = ตำรวจ ป้าย POLICE ที่โรงพัก"}],"examples":[{"en":"Sorry, I don't understand.","th":"ขอโทษ ฉันไม่เข้าใจ"},{"en":"Could you speak more slowly, please?","th":"ช่วยพูดช้าลงหน่อยได้ไหม"},{"en":"Can you repeat that, please?","th":"พูดซ้ำอีกทีได้ไหม"},{"en":"Help!","th":"ช่วยด้วย!"},{"en":"Call the police!","th":"เรียกตำรวจ!"},{"en":"I need a doctor.","th":"ฉันต้องการหมอ"},{"en":"I am lost. Can you help me?","th":"ฉันหลงทาง ช่วยฉันหน่อยได้ไหม"}],"quiz":[{"questionTh":"อยากบอกว่า \"ฉันไม่เข้าใจ\" พูดว่าอะไร","choices":["I am lost.","I need a doctor.","I don't understand.","Call the police!"],"answerIndex":2,"explainTh":"I don't understand = ฉันไม่เข้าใจ; I am lost คือหลงทาง, I need a doctor คือต้องการหมอ"},{"questionTh":"เกิดเหตุฉุกเฉิน อยากให้คนมาช่วยด่วน ตะโกนว่าอะไร","choices":["Slowly, please.","Thank you.","Good morning.","Help!"],"answerIndex":3,"explainTh":"Help! เป็นคำตะโกนขอความช่วยเหลือฉุกเฉิน จำให้ขึ้นใจ"},{"questionTh":"\"Could you speak more slowly?\" ใช้ตอนไหน","choices":["เมื่ออยากให้อีกฝ่ายพูดช้าลง","เมื่ออยากได้เงินทอน","เมื่อถามราคา","เมื่อสั่งอาหาร"],"answerIndex":0,"explainTh":"speak slowly = พูดช้าๆ ใช้ขอให้อีกฝ่ายพูดช้าลงเมื่อฟังไม่ทัน"},{"questionTh":"ถ้าเจ็บป่วยหนักและต้องการหมอ พูดว่าอะไร","choices":["I am lost.","I need a doctor.","Where is the exit?","Can you repeat that?"],"answerIndex":1,"explainTh":"I need a doctor = ฉันต้องการหมอ เป็นวลีฉุกเฉินที่ต้องจำ"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$หลงทางที่สถานีรถไฟ — ขอความช่วยเหลือและถามเวลา/ชานชาลา$q$, $q$You are a friendly information desk officer at a busy train station in an English-speaking country. A Thai traveler comes to your desk looking a little lost and needs help finding the right platform and understanding the departure time. Speak clearly, and slow down or repeat the numbers whenever the traveler asks you to.$q$, $q$Train station information officer$q$, $q$ขอความช่วยเหลือเพื่อหาชานชาลาที่ถูกต้อง ถามเวลารถออก และเข้าใจตัวเลขที่เจ้าหน้าที่บอก โดยกล้าขอให้พูดช้าลงหรือพูดซ้ำเมื่อฟังไม่ทัน$q$, $q$["บอกเจ้าหน้าที่ได้ว่าไม่เข้าใจ และขอให้พูดช้าลงหรือพูดซ้ำ (เช่น I don't understand. / Could you speak more slowly?)","ถามและเข้าใจเวลารถออกกับหมายเลขชานชาลา แล้วทวนตัวเลขกลับให้ถูกต้อง","ใช้วลีขอความช่วยเหลือได้เหมาะกับสถานการณ์ (เช่น Can you help me? / I am lost.)"]$q$::jsonb);
END IF;
END $do$;

-- Unit 3: ทักทาย แนะนำตัว และมารยาท
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 3) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 3, $q$ทักทาย แนะนำตัว และมารยาท$q$, $q$ทักทาย แนะนำตัว คำสุภาพ และการถาม-ขอร้องอย่างสุภาพ$q$, 'A1', $q$👋$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ทักทายและกล่าวลา$q$, $q${"listen":{"audioText":"Receptionist: Good morning! Welcome to the hotel. (hear)\nYou: Good morning. Thank you.\nReceptionist: How are you today? (hear)\nYou: I'm fine, thank you. And you?\nReceptionist: I'm very well. Have a nice day! (hear)\nYou: You too. Goodbye.","thaiExplain":"สถานการณ์นี้คือการทักทายพนักงานเมื่อไปถึงโรงแรมหรือพบใครสักคน ให้ทักทายกลับด้วยคำเดียวกันตามช่วงเวลา (เช้าใช้ Good morning) เมื่อถูกถามว่า How are you? ให้ตอบว่า I'm fine, thank you แล้วถามกลับด้วย And you? ก่อนจากกันพูดคำลา เช่น Goodbye หรือ Have a nice day"},"vocab":[{"word":"hello","ipa":"/həˈloʊ/","thai":"สวัสดี (ใช้ได้ทุกเวลา)","exampleEn":"Hello! Nice to see you.","exampleTh":"สวัสดี! ดีใจที่ได้เจอกัน","associationHintTh":"เสียงเหมือนตอนรับโทรศัพท์ 'ฮัลโหล' นึกถึงการยกหูทักทาย"},{"word":"good morning","ipa":"/ˌɡʊd ˈmɔːrnɪŋ/","thai":"สวัสดีตอนเช้า","exampleEn":"Good morning, everyone!","exampleTh":"สวัสดีตอนเช้าครับทุกคน","associationHintTh":"good (ดี) + morning (เช้า) = อวยพรให้เช้าที่ดี"},{"word":"how are you","ipa":"/ˌhaʊ ɑːr ˈjuː/","thai":"คุณสบายดีไหม / เป็นอย่างไรบ้าง","exampleEn":"Hi Anna, how are you?","exampleTh":"สวัสดีแอนนา สบายดีไหม","associationHintTh":"How (อย่างไร) + are you (คุณเป็น) = ถามว่าคุณเป็นยังไง"},{"word":"goodbye","ipa":"/ˌɡʊdˈbaɪ/","thai":"ลาก่อน","exampleEn":"Goodbye! See you soon.","exampleTh":"ลาก่อน! เดี๋ยวเจอกันเร็ว ๆ นี้","associationHintTh":"'บ๊ายบาย' ในภาษาไทยมาจาก bye ในคำนี้"},{"word":"see you later","ipa":"/ˌsiː juː ˈleɪtər/","thai":"แล้วเจอกันนะ / ไว้เจอกันทีหลัง","exampleEn":"I have to go now. See you later!","exampleTh":"ฉันต้องไปแล้ว แล้วเจอกันนะ!","associationHintTh":"see (เห็น/เจอ) + you (คุณ) + later (ทีหลัง) = ไว้เจอกันทีหลัง"}],"examples":[{"en":"Hi, nice to meet you.","th":"สวัสดี ยินดีที่ได้รู้จัก"},{"en":"Good afternoon.","th":"สวัสดีตอนบ่าย"},{"en":"Good evening.","th":"สวัสดีตอนเย็น / ตอนค่ำ"},{"en":"I'm fine, thank you. And you?","th":"ฉันสบายดี ขอบคุณ แล้วคุณล่ะ"},{"en":"Goodbye. Have a nice day.","th":"ลาก่อน ขอให้เป็นวันที่ดี"},{"en":"See you tomorrow.","th":"แล้วเจอกันพรุ่งนี้"}],"quiz":[{"questionTh":"พนักงานโรงแรมทักว่า \"Good morning!\" ตอนเช้า คุณควรตอบว่าอย่างไร","choices":["Good night.","Good morning!","Goodbye.","Good afternoon."],"answerIndex":1,"explainTh":"ทักทายกลับด้วยคำเดียวกันตามช่วงเวลา ตอนเช้าใช้ Good morning ส่วน Good night ใช้ก่อนนอนตอนกลางคืน"},{"questionTh":"คำว่า \"Goodbye\" แปลว่าอะไร","choices":["สวัสดีตอนเช้า","ขอบคุณ","ลาก่อน","ยินดีที่ได้รู้จัก"],"answerIndex":2,"explainTh":"Goodbye แปลว่า ลาก่อน ใช้พูดตอนกำลังจะแยกจากกัน"},{"questionTh":"มีคนถามว่า \"How are you?\" คำตอบที่สุภาพและถูกต้องคือข้อใด","choices":["I'm fine, thank you. And you?","Goodbye.","My name is John.","You're welcome."],"answerIndex":0,"explainTh":"How are you? เป็นการถามสารทุกข์สุขดิบ ตอบว่า I'm fine, thank you แล้วถามกลับด้วย And you? เพื่อความสุภาพ"},{"questionTh":"จะบอกว่า \"แล้วเจอกันพรุ่งนี้\" ต้องพูดว่าอย่างไร","choices":["Nice to meet you.","Good evening.","Thank you very much.","See you tomorrow."],"answerIndex":3,"explainTh":"See you tomorrow แปลว่า แล้วเจอกันพรุ่งนี้ ใช้เป็นคำลาเมื่อรู้ว่าจะได้เจอกันอีกวันรุ่งขึ้น"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$แนะนำตัว มาจากไหน ทำงานอะไร$q$, $q${"listen":{"audioText":"New friend: Hi, I'm Anna. What's your name? (hear)\nYou: Hello, my name is Somchai.\nNew friend: Nice to meet you. Where are you from? (hear)\nYou: I'm from Thailand.\nNew friend: What do you do? (hear)\nYou: I'm a chef. I work in a hotel.","thaiExplain":"สถานการณ์นี้คือการแนะนำตัวเมื่อเจอคนใหม่ ให้บอกชื่อด้วย My name is... หรือ I'm... บอกที่มาด้วย I'm from + ชื่อประเทศ และบอกอาชีพด้วย I'm a + อาชีพ เมื่อถูกถาม What's your name? / Where are you from? / What do you do? ให้ตอบทีละคำถาม"},"vocab":[{"word":"name","ipa":"/neɪm/","thai":"ชื่อ","exampleEn":"My name is Malee.","exampleTh":"ฉันชื่อมาลี","associationHintTh":"เสียง 'เนม' ตรงกับชื่อเล่นภาษาไทยที่หลายคนใช้ นึกถึงคำว่า 'ชื่อ'"},{"word":"from","ipa":"/frʌm/","thai":"จาก, มาจาก","exampleEn":"I'm from Thailand.","exampleTh":"ฉันมาจากประเทศไทย","associationHintTh":"จำคู่กับ I'm from... = 'ฉันมาจาก...' บอกประเทศหรือเมืองที่มา"},{"word":"country","ipa":"/ˈkʌntri/","thai":"ประเทศ","exampleEn":"Thailand is a beautiful country.","exampleTh":"ประเทศไทยเป็นประเทศที่สวยงาม","associationHintTh":"'คันทรี' เสียงคล้ายเพลงแนวคันทรี นึกถึงชนบทของประเทศหนึ่ง = ประเทศ"},{"word":"job","ipa":"/dʒɑːb/","thai":"งาน, อาชีพ","exampleEn":"What is your job?","exampleTh":"งาน/อาชีพของคุณคืออะไร","associationHintTh":"'จ๊อบ' คนไทยใช้ทับศัพท์บ่อย เช่น 'รับจ๊อบ' = รับงาน"},{"word":"meet","ipa":"/miːt/","thai":"พบ, เจอ","exampleEn":"Nice to meet you.","exampleTh":"ยินดีที่ได้รู้จัก (ได้พบกัน)","associationHintTh":"เสียง 'มีท' คล้าย meeting (มีตติ้ง = การประชุมที่คนมาพบกัน)"}],"examples":[{"en":"Hello, my name is Malee.","th":"สวัสดีค่ะ ฉันชื่อมาลี"},{"en":"What's your name?","th":"คุณชื่ออะไร"},{"en":"Where are you from?","th":"คุณมาจากไหน"},{"en":"I'm from Thailand.","th":"ฉันมาจากประเทศไทย"},{"en":"What do you do?","th":"คุณทำงานอะไร"},{"en":"I'm a chef. I work in a hotel.","th":"ฉันเป็นเชฟ ฉันทำงานในโรงแรม"},{"en":"Nice to meet you.","th":"ยินดีที่ได้รู้จัก"}],"quiz":[{"questionTh":"มีคนถามว่า \"Where are you from?\" ควรตอบว่าอย่างไร","choices":["I'm a doctor.","I'm from Thailand.","My name is Nan.","Nice to meet you."],"answerIndex":1,"explainTh":"Where are you from? ถามว่ามาจากไหน ตอบด้วย I'm from + ชื่อประเทศหรือเมือง เช่น I'm from Thailand"},{"questionTh":"จะถามว่า \"คุณทำงานอะไร\" ต้องพูดว่าอย่างไร","choices":["What do you do?","Where are you from?","How are you?","What's your name?"],"answerIndex":0,"explainTh":"What do you do? เป็นคำถามมาตรฐานที่ใช้ถามอาชีพหรืองานที่ทำ"},{"questionTh":"\"What's your name?\" หมายความว่าอะไร","choices":["คุณมาจากไหน","คุณสบายดีไหม","คุณอายุเท่าไหร่","คุณชื่ออะไร"],"answerIndex":3,"explainTh":"What's your name? คือการถามชื่อ ตอบได้ว่า My name is... หรือ I'm..."},{"questionTh":"จะแนะนำชื่อตัวเองว่า \"ผมชื่อสมชาย\" ต้องพูดว่าอย่างไร","choices":["I'm from Somchai.","You are Somchai.","My name is Somchai.","His name is Somchai."],"answerIndex":2,"explainTh":"แนะนำชื่อตัวเองใช้ My name is... หรือ I'm... ส่วน I'm from ใช้กับสถานที่ และ His name ใช้กับผู้ชายคนอื่น ไม่ใช่ตัวเอง"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$คำสุภาพ ถาม-ขอร้องสุภาพ และตอบรับ-ปฏิเสธ-ยืนยัน$q$, $q${"listen":{"audioText":"Waiter: Can I help you? (hear)\nYou: Yes, please. Could I have a glass of water?\nWaiter: Sure, here you are. (hear)\nYou: Thank you very much.\nWaiter: You're welcome. (hear)","thaiExplain":"สถานการณ์นี้คือการขอความช่วยเหลือหรือขอสิ่งของอย่างสุภาพ เช่น ในร้านอาหารหรือโรงแรม ให้ใช้ Excuse me เพื่อเรียกความสนใจ ใช้ Could I have...? / Could you...? เป็นคำขอสุภาพ ตอบรับด้วย Yes, please ปฏิเสธด้วย No, thank you และเมื่อมีคนขอบคุณให้ตอบว่า You're welcome"},"vocab":[{"word":"please","ipa":"/pliːz/","thai":"ได้โปรด, กรุณา (ทำให้คำขอสุภาพขึ้น)","exampleEn":"Two coffees, please.","exampleTh":"ขอกาแฟสองแก้วครับ","associationHintTh":"'พลีซ' เสียงเหมือนอ้อนขอร้อง เติมท้ายประโยคแล้วสุภาพขึ้นทันที"},{"word":"sorry","ipa":"/ˈsɒri/","thai":"ขอโทษ, เสียใจ","exampleEn":"I'm sorry, I'm late.","exampleTh":"ขอโทษครับ ผมมาสาย","associationHintTh":"'ซอรี่' คนไทยใช้ทับศัพท์เวลาขอโทษกันบ่อย ๆ"},{"word":"excuse me","ipa":"/ɪkˈskjuːz miː/","thai":"ขอโทษนะ (ใช้เรียกความสนใจ ขอทาง หรือเรียกพนักงาน)","exampleEn":"Excuse me, where is the toilet?","exampleTh":"ขอโทษนะครับ ห้องน้ำอยู่ที่ไหน","associationHintTh":"ใช้ก่อนจะรบกวนใคร เหมือนเคาะประตูด้วยคำพูดก่อนพูดต่อ"},{"word":"could","ipa":"/kʊd/","thai":"...ได้ไหม (คำขอที่สุภาพกว่า can)","exampleEn":"Could you help me, please?","exampleTh":"ช่วยฉันหน่อยได้ไหมคะ","associationHintTh":"Could สุภาพกว่า Can จำว่า 'ขอสุภาพใช้ Could'"},{"word":"welcome","ipa":"/ˈwelkəm/","thai":"ยินดีต้อนรับ; you're welcome = ด้วยความยินดี / ไม่เป็นไร","exampleEn":"Thank you. — You're welcome.","exampleTh":"ขอบคุณครับ — ด้วยความยินดีครับ","associationHintTh":"'เวลคัม' ป้ายต้อนรับตามที่ต่าง ๆ ใช้ตอบเวลามีคนขอบคุณ"}],"examples":[{"en":"Excuse me, can you help me?","th":"ขอโทษนะครับ ช่วยผมหน่อยได้ไหม"},{"en":"Could I have a glass of water, please?","th":"ขอน้ำเปล่าแก้วหนึ่งได้ไหมครับ"},{"en":"Yes, please.","th":"ครับ/ค่ะ เอาครับ (ตอบรับ)"},{"en":"No, thank you.","th":"ไม่ครับ ขอบคุณ (ปฏิเสธอย่างสุภาพ)"},{"en":"Yes, that's right.","th":"ใช่ครับ ถูกต้องแล้ว (ยืนยัน)"},{"en":"I'm sorry.","th":"ขอโทษครับ"},{"en":"You're welcome.","th":"ด้วยความยินดีครับ"}],"quiz":[{"questionTh":"จะเรียกพนักงานหรือขอทางอย่างสุภาพ ควรใช้คำว่าอะไร","choices":["Excuse me.","Goodbye.","Good night.","See you."],"answerIndex":0,"explainTh":"Excuse me ใช้เรียกความสนใจ ขอทาง หรือเรียกพนักงานอย่างสุภาพ ส่วนคำอื่นเป็นคำลา"},{"questionTh":"มีคนพูดว่า \"Thank you very much.\" ควรตอบว่าอย่างไร","choices":["Sorry.","You're welcome.","Excuse me.","Goodbye."],"answerIndex":1,"explainTh":"เมื่อมีคนขอบคุณ ให้ตอบว่า You're welcome ซึ่งแปลว่า ด้วยความยินดี / ไม่เป็นไร"},{"questionTh":"จะขอสิ่งของอย่างสุภาพ เช่น \"ขอเมนูหน่อยได้ไหม\" ควรพูดว่าอย่างไร","choices":["Give me the menu.","I want menu.","Menu now.","Could I have the menu, please?"],"answerIndex":3,"explainTh":"ใช้ Could I have ... , please? เป็นคำขอที่สุภาพ ส่วน Give me / I want / Menu now ฟังดูห้วนและไม่สุภาพ"},{"questionTh":"พนักงานถามว่า \"Would you like some coffee?\" ถ้าจะปฏิเสธอย่างสุภาพ ควรพูดว่าอย่างไร","choices":["No.","I don't know.","No, thank you.","Yes, please."],"answerIndex":2,"explainTh":"ปฏิเสธอย่างสุภาพใช้ No, thank you ; ถ้าจะรับใช้ Yes, please ; การพูดแค่ No เฉย ๆ ฟังดูห้วนเกินไป"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$เช็คอินที่โรงแรมและทักทายพนักงาน$q$, $q$You are a friendly receptionist at a small hotel in London. A Thai guest has just arrived and walks up to your front desk. Greet them warmly, ask for their name and where they are from, make a little polite small talk, and help them politely with a simple request such as getting their room key or a glass of water.$q$, $q$Hotel receptionist$q$, $q$ทักทายพนักงานให้ถูกช่วงเวลา แนะนำตัว (บอกชื่อและมาจากไหน) พูดคุยเล็กน้อยอย่างสุภาพ แล้วขอสิ่งของ เช่น กุญแจห้องหรือน้ำ ด้วยคำขอสุภาพ ก่อนกล่าวขอบคุณและลา$q$, $q$["ทักทายและตอบรับการทักทายได้ถูกช่วงเวลา เช่น Good morning และตอบ How are you? ได้","แนะนำชื่อตัวเองและบอกได้ว่ามาจากไหน เช่น My name is... / I'm from Thailand","ใช้คำขอสุภาพและคำขอบคุณ พร้อมกล่าวลา เช่น Could I..., please / Thank you / Goodbye"]$q$::jsonb);
END IF;
END $do$;

-- Unit 4: ออกเดินทาง: เช็คอินถึงบนเครื่อง
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 4) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 4, $q$ออกเดินทาง: เช็คอินถึงบนเครื่อง$q$, $q$เช็คอิน โหลดกระเป๋า ตรวจค้น หาประตู ขึ้นเครื่อง และบริการบนเครื่อง$q$, 'A1', $q$🛫$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$เช็คอิน โหลดกระเป๋า และตรวจค้นความปลอดภัย$q$, $q${"listen":{"audioText":"(hear) Good morning. May I see your passport, please? — Here you are. I'd like a window seat. (hear) Sure. Do you have any bags to check in? — Yes, one suitcase. (hear) Please put it on the scale. Here is your boarding pass, and your gate is number 12.","thaiExplain":"ที่เคาน์เตอร์เช็คอิน ให้ยื่นหนังสือเดินทาง บอกปลายทางและที่นั่งที่อยากได้ แล้ววางกระเป๋าบนเครื่องชั่งเพื่อโหลด จากนั้นรับบัตรขึ้นเครื่อง แล้วเดินไปจุดตรวจความปลอดภัยเพื่อถอดเข็มขัด/รองเท้าและสแกนสัมภาระ"},"vocab":[{"word":"passport","ipa":"/ˈpæspɔːrt/","thai":"หนังสือเดินทาง","exampleEn":"Here is my passport.","exampleTh":"นี่หนังสือเดินทางของฉันค่ะ","associationHintTh":"pass (ผ่าน) + port (ท่า/ประตู) → เอกสารที่พาเราผ่านด่านออกนอกประเทศ"},{"word":"boarding pass","ipa":"/ˈbɔːrdɪŋ pæs/","thai":"บัตรผ่านขึ้นเครื่อง","exampleEn":"Please keep your boarding pass with you.","exampleTh":"กรุณาเก็บบัตรขึ้นเครื่องไว้กับตัวค่ะ","associationHintTh":"board = ขึ้น(เครื่อง) + pass = บัตรผ่าน → บัตรผ่านขึ้นเครื่อง"},{"word":"suitcase","ipa":"/ˈsuːtkeɪs/","thai":"กระเป๋าเดินทาง","exampleEn":"I have one suitcase to check in.","exampleTh":"ฉันมีกระเป๋าเดินทาง 1 ใบที่จะโหลดค่ะ","associationHintTh":"suit (ชุดสูท) + case (กล่อง) → กล่องใส่เสื้อผ้า = กระเป๋าเดินทาง"},{"word":"check-in counter","ipa":"/ˈtʃekɪn ˈkaʊntər/","thai":"เคาน์เตอร์เช็คอิน","exampleEn":"Where is the check-in counter for Thai Airways?","exampleTh":"เคาน์เตอร์เช็คอินของการบินไทยอยู่ที่ไหนคะ","associationHintTh":"เช็ก-อิน = เหมือนเช็กอินโรงแรมหรือในแอป คือมาแจ้งตัวว่ามาถึงแล้ว"},{"word":"security check","ipa":"/sɪˈkjʊərəti tʃek/","thai":"จุดตรวจค้นความปลอดภัย","exampleEn":"Take off your belt at the security check.","exampleTh":"ถอดเข็มขัดที่จุดตรวจความปลอดภัยค่ะ","associationHintTh":"security = รปภ./ความปลอดภัย → จุดที่ รปภ. ตรวจค้นก่อนเข้าเขตขึ้นเครื่อง"}],"examples":[{"en":"I'd like to check in for my flight to Tokyo.","th":"ฉันขอเช็คอินเที่ยวบินไปโตเกียวค่ะ"},{"en":"Here is my passport.","th":"นี่หนังสือเดินทางของฉันค่ะ"},{"en":"Can I have a window seat, please?","th":"ขอที่นั่งริมหน้าต่างได้ไหมคะ"},{"en":"I have one bag to check in.","th":"ฉันมีกระเป๋าโหลด 1 ใบค่ะ"},{"en":"(hear) Please put your bag on the scale.","th":"(ได้ยิน) กรุณาวางกระเป๋าบนเครื่องชั่งค่ะ"},{"en":"(hear) Please take off your belt and shoes.","th":"(ได้ยิน) กรุณาถอดเข็มขัดและรองเท้าค่ะ"},{"en":"Is my bag too heavy?","th":"กระเป๋าฉันหนักเกินไปไหมคะ"}],"quiz":[{"questionTh":"'passport' แปลว่าอะไร?","choices":["ตั๋วเครื่องบิน","บัตรขึ้นเครื่อง","หนังสือเดินทาง","กระเป๋าเดินทาง"],"answerIndex":2,"explainTh":"passport = หนังสือเดินทาง เป็นเอกสารสำคัญที่สุดตอนเดินทางต่างประเทศ"},{"questionTh":"อยากได้ที่นั่งริมทางเดิน (ลุกเข้าห้องน้ำง่าย) พูดว่าอะไร?","choices":["An aisle seat, please.","A window seat, please.","A middle seat, please.","A back seat, please."],"answerIndex":0,"explainTh":"aisle seat = ที่นั่งริมทางเดิน ส่วน window seat = ริมหน้าต่าง"},{"questionTh":"เจ้าหน้าที่พูดว่า 'Put your bag on the scale.' ให้เราทำอะไร?","choices":["เปิดกระเป๋าให้ตรวจ","ถือกระเป๋าติดตัวไว้","หิ้วกระเป๋าไปที่ประตู","วางกระเป๋าบนเครื่องชั่งน้ำหนัก"],"answerIndex":3,"explainTh":"scale = เครื่องชั่ง เขาให้วางกระเป๋าเพื่อชั่งน้ำหนักก่อนโหลดใต้ท้องเครื่อง"},{"questionTh":"ที่จุดตรวจความปลอดภัย (security check) เจ้าหน้าที่มักให้ทำอะไร?","choices":["โชว์บัตรเครดิต","ถอดเข็มขัดและรองเท้า","สั่งอาหาร","เลือกที่นั่ง"],"answerIndex":1,"explainTh":"ที่ security check มักต้องถอดเข็มขัด รองเท้า และเอาของโลหะออกก่อนเดินผ่านเครื่องสแกน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$หาประตู ฟังประกาศ และขึ้นเครื่อง$q$, $q${"listen":{"audioText":"(hear) Attention passengers. Flight TG 675 to Bangkok is now boarding at gate 12. (hear) Please have your boarding pass and passport ready. — Excuse me, is this gate 12? (hear) Yes, please join the line on your right. (hear) This is the final call for passenger Somchai.","thaiExplain":"หลังผ่านตรวจแล้ว ให้ดูจอหรือฟังประกาศเพื่อหาประตู (gate) ของเที่ยวบิน ฟังคำสำคัญ เช่น boarding (เปิดให้ขึ้นเครื่อง), delayed (ล่าช้า) และ final call (เรียกครั้งสุดท้าย) แล้วเตรียมบัตรขึ้นเครื่องกับหนังสือเดินทางให้พร้อม"},"vocab":[{"word":"gate","ipa":"/ɡeɪt/","thai":"ประตูขึ้นเครื่อง","exampleEn":"Your flight leaves from gate 20.","exampleTh":"เที่ยวบินของคุณออกจากประตู 20 ค่ะ","associationHintTh":"gate = ประตู (เหมือนประตูบ้าน) แต่ที่นี่คือประตูที่เดินออกไปขึ้นเครื่อง"},{"word":"boarding","ipa":"/ˈbɔːrdɪŋ/","thai":"การขึ้นเครื่อง / กำลังให้ขึ้นเครื่อง","exampleEn":"The flight is now boarding.","exampleTh":"เที่ยวบินกำลังเปิดให้ขึ้นเครื่องแล้วค่ะ","associationHintTh":"board = ก้าวขึ้นเรือ/ขึ้นเครื่อง → boarding = ช่วงที่เขาให้เดินขึ้นเครื่อง"},{"word":"announcement","ipa":"/əˈnaʊnsmənt/","thai":"ประกาศ","exampleEn":"Listen to the announcement about your flight.","exampleTh":"ฟังประกาศเกี่ยวกับเที่ยวบินของคุณด้วยนะคะ","associationHintTh":"นึกถึงเสียงประกาศตามสายในสนามบิน 'อะ-นาวนซ์-เมนต์'"},{"word":"delayed","ipa":"/dɪˈleɪd/","thai":"ล่าช้า","exampleEn":"Our flight is delayed by one hour.","exampleTh":"เที่ยวบินของเราล่าช้าไป 1 ชั่วโมงค่ะ","associationHintTh":"ดีเลย์ = คนไทยใช้ทับศัพท์อยู่แล้ว แปลว่าล่าช้า"},{"word":"departure","ipa":"/dɪˈpɑːrtʃər/","thai":"ขาออก / เวลาออกเดินทาง","exampleEn":"Check the departure board for your gate.","exampleTh":"ดูจอขาออกเพื่อหาประตูของคุณค่ะ","associationHintTh":"departure = ขาออก (ตรงข้ามกับ arrival = ขาเข้า)"}],"examples":[{"en":"Excuse me, where is gate 12?","th":"ขอโทษค่ะ ประตู 12 อยู่ที่ไหนคะ"},{"en":"(hear) Flight TG 675 is now boarding at gate 12.","th":"(ได้ยิน) เที่ยวบิน TG 675 กำลังเปิดให้ขึ้นเครื่องที่ประตู 12"},{"en":"(hear) Your flight is delayed by 30 minutes.","th":"(ได้ยิน) เที่ยวบินของท่านล่าช้า 30 นาที"},{"en":"Is this the gate for the Bangkok flight?","th":"นี่ประตูสำหรับเที่ยวบินไปกรุงเทพใช่ไหมคะ"},{"en":"What time do we board?","th":"เราขึ้นเครื่องกี่โมงคะ"},{"en":"(hear) This is the final call for passenger Somchai.","th":"(ได้ยิน) นี่เป็นการเรียกครั้งสุดท้ายสำหรับผู้โดยสารสมชาย"}],"quiz":[{"questionTh":"'gate' หมายถึงอะไรในสนามบิน?","choices":["ห้องน้ำ","ประตูทางออกไปขึ้นเครื่อง","ร้านอาหาร","เคาน์เตอร์เช็คอิน"],"answerIndex":1,"explainTh":"gate = ประตูขึ้นเครื่อง จุดที่เรารอและเดินออกไปขึ้นเครื่องบิน"},{"questionTh":"ได้ยินประกาศว่า 'Your flight is delayed.' แปลว่าอะไร?","choices":["เที่ยวบินถูกยกเลิก","เที่ยวบินออกเร็วขึ้น","เปลี่ยนประตูขึ้นเครื่อง","เที่ยวบินล่าช้า"],"answerIndex":3,"explainTh":"delayed = ล่าช้า หมายถึงเครื่องออกช้ากว่ากำหนด ไม่ใช่ยกเลิก"},{"questionTh":"อยากถามทางไปประตู 12 ควรพูดว่าอะไร?","choices":["Where is gate 12?","What time is it?","How much is it?","Is it far?"],"answerIndex":0,"explainTh":"Where is gate 12? = ประตู 12 อยู่ที่ไหน เป็นประโยคถามทางที่ตรงที่สุด"},{"questionTh":"ได้ยินคำว่า 'now boarding' สำหรับเที่ยวบินเรา ควรทำอะไร?","choices":["ไปเช็คอินใหม่","นั่งรอต่ออีกนาน","ไปเข้าแถวขึ้นเครื่อง","ไปรับกระเป๋า"],"answerIndex":2,"explainTh":"boarding = กำลังให้ขึ้นเครื่อง ควรเตรียมบัตรและไปต่อแถวขึ้นเครื่องได้เลย"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$หาที่นั่งและบริการบนเครื่อง (อาหาร/น้ำ/ผ้าห่ม)$q$, $q${"listen":{"audioText":"Excuse me, where is seat 24A? (hear) It's on the left, near the window. — Thank you. (hear) Would you like chicken or fish? — Chicken, please. And some water. (hear) Sure. Can I bring you a blanket too?","thaiExplain":"เมื่อขึ้นเครื่องแล้ว หาที่นั่งตามหมายเลข เช่น 24A (แถว 24 ที่นั่ง A) แล้วคาดเข็มขัดนิรภัย เมื่อพนักงานต้อนรับมาบริการ เราสามารถเลือกอาหาร ขอน้ำ หรือขอผ้าห่มได้"},"vocab":[{"word":"seat","ipa":"/siːt/","thai":"ที่นั่ง","exampleEn":"Excuse me, this is my seat.","exampleTh":"ขอโทษค่ะ นี่ที่นั่งของฉัน","associationHintTh":"seat = ที่นั่ง (เบาะรถก็เรียก seat) 'ซีท' ออกเสียงยาว"},{"word":"seatbelt","ipa":"/ˈsiːtbelt/","thai":"เข็มขัดนิรภัย","exampleEn":"Please fasten your seatbelt.","exampleTh":"กรุณาคาดเข็มขัดนิรภัยค่ะ","associationHintTh":"seat (ที่นั่ง) + belt (เข็มขัด) → เข็มขัดนิรภัยประจำที่นั่ง"},{"word":"blanket","ipa":"/ˈblæŋkɪt/","thai":"ผ้าห่ม","exampleEn":"Could I have a blanket, please?","exampleTh":"ขอผ้าห่มหน่อยได้ไหมคะ","associationHintTh":"'แบลง-เก็ต' นึกถึงผ้าห่มนุ่มๆ ที่คลุมตัวตอนหนาวบนเครื่อง"},{"word":"tray table","ipa":"/ˌtreɪ ˈteɪbl/","thai":"โต๊ะพับ (หน้าที่นั่ง)","exampleEn":"Please put your tray table down.","exampleTh":"กรุณากางโต๊ะพับลงค่ะ","associationHintTh":"tray = ถาด + table = โต๊ะ → โต๊ะถาดพับหลังเบาะข้างหน้า"},{"word":"flight attendant","ipa":"/ˌflaɪt əˈtendənt/","thai":"พนักงานต้อนรับบนเครื่องบิน","exampleEn":"Ask the flight attendant for help.","exampleTh":"ขอความช่วยเหลือจากพนักงานต้อนรับได้ค่ะ","associationHintTh":"flight = เที่ยวบิน + attendant = ผู้ดูแล → คนดูแลผู้โดยสารบนเครื่อง"}],"examples":[{"en":"Excuse me, where is seat 24A?","th":"ขอโทษค่ะ ที่นั่ง 24A อยู่ตรงไหนคะ"},{"en":"Can I have some water, please?","th":"ขอน้ำหน่อยได้ไหมคะ"},{"en":"(hear) Would you like chicken or fish?","th":"(ได้ยิน) รับไก่หรือปลาดีคะ"},{"en":"Chicken, please.","th":"เอาไก่ค่ะ"},{"en":"Could I have a blanket, please?","th":"ขอผ้าห่มหน่อยได้ไหมคะ"},{"en":"(hear) Please fasten your seatbelt.","th":"(ได้ยิน) กรุณาคาดเข็มขัดนิรภัยค่ะ"},{"en":"May I have a cup of coffee?","th":"ขอกาแฟสักแก้วได้ไหมคะ"}],"quiz":[{"questionTh":"'blanket' คืออะไร?","choices":["หมอน","เข็มขัด","แก้วน้ำ","ผ้าห่ม"],"answerIndex":3,"explainTh":"blanket = ผ้าห่ม ถ้าหนาวบนเครื่องขอได้ว่า 'Could I have a blanket?'"},{"questionTh":"พนักงานถามว่า 'Chicken or fish?' หมายความว่าอะไร?","choices":["ถามชื่อเรา","ให้เลือกอาหาร ไก่หรือปลา","ถามหมายเลขที่นั่ง","ขอดูหนังสือเดินทาง"],"answerIndex":1,"explainTh":"เป็นการให้เลือกเมนูอาหาร ตอบสั้นๆ ได้ว่า 'Chicken, please.' หรือ 'Fish, please.'"},{"questionTh":"อยากขอน้ำดื่ม ควรพูดว่าอะไร?","choices":["Where is my seat?","Please fasten your seatbelt.","Can I have some water, please?","Chicken, please."],"answerIndex":2,"explainTh":"Can I have some water, please? = ขอน้ำหน่อยได้ไหม เป็นประโยคขอของสุภาพ"},{"questionTh":"ได้ยินว่า 'Please fasten your seatbelt.' ต้องทำอะไร?","choices":["คาดเข็มขัดนิรภัย","ปลดเข็มขัด","ลุกขึ้นยืน","เปิดหน้าต่าง"],"answerIndex":0,"explainTh":"fasten your seatbelt = คาด/รัดเข็มขัดนิรภัย มักได้ยินตอนเครื่องขึ้น-ลง"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'vocab', $q$กรอกใบ ตม./ใบศุลกากรบนเครื่อง$q$, $q${"listen":{"audioText":"(hear) Please fill in your arrival card before we land. — Excuse me, what does 'surname' mean? (hear) It means your family name. Write your given name here, and your date of birth below. (hear) And don't forget to sign your name at the bottom.","thaiExplain":"บนเครื่องมักได้รับใบ ตม. (arrival card) หรือใบศุลกากรให้กรอกก่อนเครื่องลง บทนี้ฝึกอ่านชื่อช่องในฟอร์มภาษาอังกฤษ เช่น surname (นามสกุล), given name (ชื่อจริง), signature (ลายเซ็น) เพื่อกรอกให้ถูกช่อง เรื่องนี้สำคัญมาก เพราะกรอกผิดช่องอาจมีปัญหาที่ด่านตรวจคนเข้าเมือง"},"vocab":[{"word":"surname (family name)","ipa":"/ˈsɜːrneɪm/","thai":"นามสกุล","exampleEn":"Write your surname in capital letters.","exampleTh":"เขียนนามสกุลด้วยตัวพิมพ์ใหญ่ค่ะ","associationHintTh":"surname = family name = นามสกุล (ชื่อวงศ์ตระกูล) กรอกให้ตรงกับในพาสปอร์ต"},{"word":"given name (first name)","ipa":"/ˈɡɪvən neɪm/","thai":"ชื่อจริง (ชื่อต้น)","exampleEn":"Your given name is your first name.","exampleTh":"given name ก็คือชื่อจริงหรือชื่อต้นของคุณ","associationHintTh":"given = ที่ถูกตั้งให้ → ชื่อที่พ่อแม่ตั้งให้ = ชื่อจริง (first name)"},{"word":"date of birth","ipa":"/ˌdeɪt əv ˈbɜːrθ/","thai":"วันเดือนปีเกิด","exampleEn":"Please write your date of birth as day/month/year.","exampleTh":"กรุณาเขียนวันเดือนปีเกิดแบบ วัน/เดือน/ปี","associationHintTh":"date = วันที่ + birth = เกิด → วันเกิด ในฟอร์มมักย่อว่า DOB"},{"word":"nationality","ipa":"/ˌnæʃəˈnæləti/","thai":"สัญชาติ","exampleEn":"My nationality is Thai.","exampleTh":"สัญชาติของฉันคือไทย","associationHintTh":"nation = ชาติ → nationality = สัญชาติ คนไทยกรอกว่า 'Thai'"},{"word":"purpose of visit","ipa":"/ˈpɜːrpəs əv ˈvɪzɪt/","thai":"วัตถุประสงค์การมาเยือน","exampleEn":"Purpose of visit: tourism.","exampleTh":"วัตถุประสงค์การมาเยือน: ท่องเที่ยว","associationHintTh":"purpose = จุดประสงค์ + visit = มาเยือน → มาทำไม (tourism = เที่ยว, business = ธุรกิจ)"},{"word":"signature","ipa":"/ˈsɪɡnətʃər/","thai":"ลายเซ็น","exampleEn":"Please put your signature here.","exampleTh":"กรุณาเซ็นชื่อตรงนี้ค่ะ","associationHintTh":"sign = เซ็น → signature = ช่องเซ็นชื่อ ต้องเซ็นด้วยลายมือ ห้ามพิมพ์"}],"examples":[{"en":"Excuse me, what does 'surname' mean?","th":"ขอโทษค่ะ 'surname' แปลว่าอะไรคะ"},{"en":"Surname means your family name.","th":"surname คือนามสกุลค่ะ"},{"en":"Where do I write my passport number?","th":"ฉันต้องกรอกหมายเลขหนังสือเดินทางตรงไหนคะ"},{"en":"My purpose of visit is tourism.","th":"วัตถุประสงค์การมาเยือนของฉันคือท่องเที่ยวค่ะ"},{"en":"(hear) Please write your date of birth here.","th":"(ได้ยิน) กรุณาเขียนวันเดือนปีเกิดตรงนี้ค่ะ"},{"en":"What is your address in Japan?","th":"ที่อยู่ของคุณในญี่ปุ่นคืออะไรคะ"},{"en":"(hear) Please sign your name at the bottom.","th":"(ได้ยิน) กรุณาเซ็นชื่อด้านล่างค่ะ"}],"quiz":[{"questionTh":"ในใบ ตม. คำว่า 'Surname' ตรงกับความหมายภาษาไทยข้อใด?","choices":["ชื่อจริง","นามสกุล","ลายเซ็น","สัญชาติ"],"answerIndex":1,"explainTh":"Surname = family name = นามสกุล กรอกให้ตรงกับที่ปรากฏในหนังสือเดินทาง"},{"questionTh":"คำว่า 'Nationality' ตรงกับความหมายภาษาไทยข้อใด?","choices":["สัญชาติ","วันเดือนปีเกิด","ที่อยู่","วัตถุประสงค์การมาเยือน"],"answerIndex":0,"explainTh":"Nationality = สัญชาติ คนไทยกรอกว่า 'Thai'"},{"questionTh":"คำว่า 'Signature' ตรงกับความหมายภาษาไทยข้อใด?","choices":["หมายเลขหนังสือเดินทาง","ชื่อจริง","วัตถุประสงค์การมาเยือน","ลายเซ็น"],"answerIndex":3,"explainTh":"Signature = ลายเซ็น ต้องเซ็นด้วยลายมือของตัวเอง ห้ามพิมพ์หรือให้คนอื่นเซ็นแทน"},{"questionTh":"คำว่า 'Purpose of visit' ตรงกับความหมายภาษาไทยข้อใด?","choices":["วันเดือนปีเกิด","นามสกุล","วัตถุประสงค์การมาเยือน","ลายเซ็น"],"answerIndex":2,"explainTh":"Purpose of visit = วัตถุประสงค์การมาเยือน เช่น tourism (ท่องเที่ยว) หรือ business (ธุรกิจ)"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$เช็คอินที่เคาน์เตอร์สายการบิน$q$, $q$You are a friendly airline check-in agent at the international departures counter. A Thai traveler comes to your counter to check in for a flight to Tokyo. Greet them, ask for their passport, ask about checked bags and seat preference, then give them a boarding pass and tell them their gate number. Speak slowly and use simple English, and gently help if they get stuck.$q$, $q$Airline check-in agent$q$, $q$เช็คอินเที่ยวบินไปโตเกียว โหลดกระเป๋า 1 ใบ ขอที่นั่งริมหน้าต่าง และรับบัตรขึ้นเครื่องพร้อมรู้ว่าไปประตูไหน$q$, $q$["ยื่นหนังสือเดินทางและบอกปลายทาง (Tokyo) เป็นภาษาอังกฤษได้","ขอที่นั่งริมหน้าต่างและแจ้งว่ามีกระเป๋าโหลด 1 ใบได้","ฟังและจดจำหมายเลขประตูขึ้นเครื่อง (gate) ที่พนักงานบอกได้ถูกต้อง"]$q$::jsonb);
END IF;
END $do$;

-- Unit 6: ถึงปลายทาง: กระเป๋า ซิม และเงิน
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 6) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 6, $q$ถึงปลายทาง: กระเป๋า ซิม และเงิน$q$, $q$รับกระเป๋า แจ้งกระเป๋าหาย ต่อเครื่อง ซื้อซิม แลกเงิน และกด ATM$q$, 'A2', $q$🛄$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$รับกระเป๋าที่สายพาน และแจ้งกระเป๋าหาย$q$, $q${"listen":{"audioText":"Excuse me, which carousel is for flight TG 465? (hear) Flight TG 465 is at carousel number 5. I'm waiting at carousel 5, but my suitcase hasn't come out. I think my bag is missing. (hear) Please go to the baggage service counter and show me your baggage tag.","thaiExplain":"เมื่อลงเครื่องแล้ว ไปดูจอว่าเที่ยวบินของเราออกที่สายพาน (carousel) ไหน แล้วไปรอรับกระเป๋า ถ้ากระเป๋าไม่ออกมาหรือหาย ให้ไปที่เคาน์เตอร์ baggage service แล้วแจ้งเจ้าหน้าที่ พร้อมโชว์ป้ายติดกระเป๋า (baggage tag) ที่ได้ตอนเช็คอิน"},"vocab":[{"word":"baggage claim","ipa":"/ˈbæɡɪdʒ kleɪm/","thai":"จุดรับกระเป๋า","exampleEn":"The baggage claim is on the first floor.","exampleTh":"จุดรับกระเป๋าอยู่ชั้นหนึ่งค่ะ","associationHintTh":"baggage = กระเป๋า + claim = ขอรับสิทธิ์ → จุดที่ไป 'ขอรับ' กระเป๋าคืน"},{"word":"carousel","ipa":"/ˌkærəˈsɛl/","thai":"สายพานรับกระเป๋า","exampleEn":"Your bags will come out on carousel 5.","exampleTh":"กระเป๋าของคุณจะออกที่สายพานหมายเลข 5 ค่ะ","associationHintTh":"อ่านคล้าย 'แคร์-รู-เซล' ม้าหมุน → สายพานที่หมุนวนเอากระเป๋ามาให้เรา"},{"word":"suitcase","ipa":"/ˈsuːtkeɪs/","thai":"กระเป๋าเดินทาง","exampleEn":"My suitcase is large and black.","exampleTh":"กระเป๋าเดินทางของฉันสีดำใบใหญ่ค่ะ","associationHintTh":"suit (ชุดสูท) + case (กล่อง) → กล่องใส่เสื้อผ้า = กระเป๋าเดินทาง"},{"word":"baggage tag","ipa":"/ˈbæɡɪdʒ tæɡ/","thai":"ป้ายติดกระเป๋า","exampleEn":"Here is my baggage tag.","exampleTh":"นี่ป้ายติดกระเป๋าของฉันค่ะ","associationHintTh":"tag = ป้าย → ป้ายที่พนักงานติดกับกระเป๋าตอนเช็คอิน ใช้ตามหากระเป๋า"},{"word":"missing","ipa":"/ˈmɪsɪŋ/","thai":"หายไป","exampleEn":"I think my bag is missing.","exampleTh":"ฉันคิดว่ากระเป๋าของฉันหายค่ะ","associationHintTh":"มิสซิ่ง คิดถึง 'miss' = พลาด/คลาดกัน → ของหายไป"}],"examples":[{"en":"Which carousel is for flight TG 465?","th":"สายพานไหนของเที่ยวบิน TG 465 คะ"},{"en":"My suitcase hasn't come out yet.","th":"กระเป๋าของฉันยังไม่ออกมาเลยค่ะ"},{"en":"I think my bag is missing.","th":"ฉันคิดว่ากระเป๋าของฉันหายค่ะ"},{"en":"It's a large black suitcase.","th":"เป็นกระเป๋าเดินทางสีดำใบใหญ่ค่ะ"},{"en":"Here is my baggage tag.","th":"นี่ป้ายติดกระเป๋าของฉันค่ะ"},{"en":"Where can I report a lost bag?","th":"ฉันจะแจ้งกระเป๋าหายได้ที่ไหนคะ"}],"quiz":[{"questionTh":"'สายพานรับกระเป๋า' ภาษาอังกฤษว่าอะไร","choices":["carousel","counter","gate","runway"],"answerIndex":0,"explainTh":"carousel คือสายพานหมุนที่กระเป๋าค่อยๆ ออกมาให้เรารับ"},{"questionTh":"ถ้ากระเป๋าไม่ออกมาสักที ควรบอกเจ้าหน้าที่ว่าอะไร","choices":["My flight is delayed.","My suitcase is missing.","I want a window seat.","Where is the toilet?"],"answerIndex":1,"explainTh":"missing = หาย ประโยคนี้บอกว่ากระเป๋าเดินทางของเราหาย"},{"questionTh":"เจ้าหน้าที่ขอดูอะไรเพื่อยืนยันว่าเป็นกระเป๋าของคุณ","choices":["boarding pass","passport photo","baggage tag","credit card"],"answerIndex":2,"explainTh":"baggage tag คือป้ายติดกระเป๋าที่ได้ตอนเช็คอิน ใช้ยืนยันและตามหากระเป๋า"},{"questionTh":"'นี่ป้ายติดกระเป๋าของฉัน' พูดว่าอะไร","choices":["Here is my ticket.","Here is my passport.","Here is my boarding pass.","Here is my baggage tag."],"answerIndex":3,"explainTh":"baggage tag = ป้ายติดกระเป๋า จึงตรงกับข้อสุดท้าย"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ต่อเครื่อง (ทรานสิท)$q$, $q${"listen":{"audioText":"Excuse me, I have a connecting flight to Tokyo. Where do I go? (hear) Please follow the signs for 'Transfer' and go to gate 22. Do I need to collect my baggage here? (hear) No, your bags are checked through to Tokyo. Thank you.","thaiExplain":"ถ้าต้องต่อเครื่อง (transit) ไม่ต้องออกไปด้านนอก ให้เดินตามป้าย 'Transfer' หรือ 'Transit' ไปยังเกต (gate) ของเที่ยวบินต่อไป ถ้ากระเป๋าถูกเช็คต่อ (checked through) ถึงปลายทางแล้ว เราไม่ต้องรับกระเป๋าเอง"},"vocab":[{"word":"connecting flight","ipa":"/kəˈnɛktɪŋ flaɪt/","thai":"เที่ยวบินต่อเครื่อง","exampleEn":"I have a connecting flight to Tokyo.","exampleTh":"ฉันมีเที่ยวบินต่อเครื่องไปโตเกียวค่ะ","associationHintTh":"connect = เชื่อมต่อ → เที่ยวบินที่เชื่อมต่อไปสนามบินถัดไป"},{"word":"transfer","ipa":"/ˈtrænsfɜːr/","thai":"การต่อเครื่อง / เปลี่ยนเครื่อง","exampleEn":"Follow the signs for transfer.","exampleTh":"เดินตามป้ายต่อเครื่องได้เลยค่ะ","associationHintTh":"ทรานส์เฟอร์ = โอน/ย้าย → ย้ายจากเครื่องหนึ่งไปอีกเครื่องหนึ่ง"},{"word":"gate","ipa":"/ɡeɪt/","thai":"ประตูขึ้นเครื่อง","exampleEn":"My next flight is at gate 22.","exampleTh":"เที่ยวบินต่อไปของฉันอยู่ที่เกต 22 ค่ะ","associationHintTh":"เกต = ประตูรั้ว → ประตูที่เดินออกไปขึ้นเครื่อง"},{"word":"boarding pass","ipa":"/ˈbɔːrdɪŋ pæs/","thai":"บัตรขึ้นเครื่อง","exampleEn":"Please show your boarding pass at the gate.","exampleTh":"กรุณาแสดงบัตรขึ้นเครื่องที่เกตค่ะ","associationHintTh":"board = ขึ้นเครื่อง → บัตรผ่านสำหรับขึ้นเครื่อง"},{"word":"layover","ipa":"/ˈleɪoʊvər/","thai":"เวลาพักรอต่อเครื่อง","exampleEn":"I have a three-hour layover in Singapore.","exampleTh":"ฉันมีเวลาพักรอต่อเครื่องสามชั่วโมงที่สิงคโปร์ค่ะ","associationHintTh":"lay (นอนพัก) + over → ช่วงพักรอระหว่างต่อเครื่อง"}],"examples":[{"en":"I have a connecting flight to Tokyo.","th":"ฉันมีเที่ยวบินต่อเครื่องไปโตเกียวค่ะ"},{"en":"Where is the transfer desk?","th":"เคาน์เตอร์ต่อเครื่องอยู่ที่ไหนคะ"},{"en":"Which gate is my next flight?","th":"เที่ยวบินต่อไปของฉันอยู่เกตไหนคะ"},{"en":"Do I need to collect my baggage here?","th":"ฉันต้องรับกระเป๋าที่นี่ไหมคะ"},{"en":"How long is my layover?","th":"ฉันต้องรอต่อเครื่องนานแค่ไหนคะ"},{"en":"Is my luggage checked through to Tokyo?","th":"กระเป๋าฉันถูกเช็คต่อไปถึงโตเกียวเลยไหมคะ"}],"quiz":[{"questionTh":"ในสนามบิน ป้ายบอกทาง 'ต่อเครื่อง' มักเขียนว่าอะไร","choices":["Arrivals","Transfer","Baggage Claim","Check-in"],"answerIndex":1,"explainTh":"ป้าย Transfer (หรือ Transit) ใช้บอกทางไปยังเที่ยวบินต่อเครื่อง"},{"questionTh":"'ประตูขึ้นเครื่อง' ภาษาอังกฤษคือคำใด","choices":["gate","door","window","carousel"],"answerIndex":0,"explainTh":"gate = ประตูทางออกสำหรับขึ้นเครื่อง เช่น gate 22"},{"questionTh":"ถ้าอยากรู้ว่าต้องรับกระเป๋าเองไหม ควรถามว่าอะไร","choices":["What time is it?","Where is the toilet?","Do I need to collect my baggage here?","Can I have a coffee?"],"answerIndex":2,"explainTh":"เป็นการถามว่าต้องไปรับ (collect) กระเป๋าที่นี่หรือไม่"},{"questionTh":"'เวลาพักรอระหว่างต่อเครื่อง' เรียกว่าอะไร","choices":["takeoff","landing","boarding","layover"],"answerIndex":3,"explainTh":"layover คือช่วงเวลาที่เราต้องรอเปลี่ยน/ต่อเครื่อง"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$ซื้อซิม/เน็ตมือถือ$q$, $q${"listen":{"audioText":"Hi, I'd like to buy a SIM card for tourists. (hear) How many days will you stay? I'll stay for ten days, and I need a lot of data. (hear) This one has 20 gigabytes for two weeks. Can you help me set it up? (hear) Sure. May I see your passport, please?","thaiExplain":"เวลาซื้อซิมนักท่องเที่ยว ให้บอกจำนวนวันที่จะอยู่และปริมาณเน็ต (data) ที่ต้องการ หลายประเทศต้องใช้พาสปอร์ตลงทะเบียนซิม และเราขอให้พนักงานช่วยติดตั้ง (set up) ให้ได้"},"vocab":[{"word":"SIM card","ipa":"/sɪm kɑːrd/","thai":"ซิมการ์ด","exampleEn":"I need a SIM card with lots of data.","exampleTh":"ฉันต้องการซิมที่มีเน็ตเยอะๆ ค่ะ","associationHintTh":"'ซิมการ์ด' ทับศัพท์ตรงกับภาษาไทย จำง่ายมาก"},{"word":"data","ipa":"/ˈdeɪtə/","thai":"เน็ต / ปริมาณอินเทอร์เน็ต","exampleEn":"How much data do I get?","exampleTh":"ฉันได้เน็ตเท่าไรคะ","associationHintTh":"เดต้า = ข้อมูล → ในมือถือคือ 'เน็ต' ที่ใช้รับส่งข้อมูล"},{"word":"tourist SIM","ipa":"/ˈtʊərɪst sɪm/","thai":"ซิมสำหรับนักท่องเที่ยว","exampleEn":"Do you have a tourist SIM?","exampleTh":"มีซิมสำหรับนักท่องเที่ยวไหมคะ","associationHintTh":"tourist = นักท่องเที่ยว → ซิมที่ทำมาเพื่อคนมาเที่ยวโดยเฉพาะ"},{"word":"top up","ipa":"/ˈtɒp ʌp/","thai":"เติมเงิน / เติมเน็ต","exampleEn":"How can I top up my SIM?","exampleTh":"ฉันจะเติมเงินซิมยังไงคะ","associationHintTh":"top = ด้านบน/เติมให้เต็ม → เติมเงินหรือเติมเน็ตเข้าไป"},{"word":"coverage","ipa":"/ˈkʌvərɪdʒ/","thai":"พื้นที่สัญญาณครอบคลุม","exampleEn":"Does this SIM have good coverage?","exampleTh":"ซิมนี้สัญญาณครอบคลุมดีไหมคะ","associationHintTh":"cover = ครอบคลุม → พื้นที่ที่สัญญาณครอบคลุมไปถึง"}],"examples":[{"en":"I'd like a SIM card for tourists.","th":"ฉันขอซิมสำหรับนักท่องเที่ยวค่ะ"},{"en":"How much data do I get?","th":"ฉันได้เน็ตเท่าไรคะ"},{"en":"I'll stay for ten days.","th":"ฉันจะอยู่สิบวันค่ะ"},{"en":"Can you help me set it up?","th":"ช่วยติดตั้งให้หน่อยได้ไหมคะ"},{"en":"How can I top up?","th":"ฉันจะเติมเงินยังไงคะ"},{"en":"Does it have good coverage everywhere?","th":"สัญญาณครอบคลุมดีทุกที่ไหมคะ"}],"quiz":[{"questionTh":"ในเรื่องซิมมือถือ คำว่า 'data' หมายถึงอะไร","choices":["เงินสด","กระเป๋าเดินทาง","เน็ต / อินเทอร์เน็ต","ที่นั่งริมหน้าต่าง"],"answerIndex":2,"explainTh":"data ในบริบทมือถือคือปริมาณอินเทอร์เน็ตหรือ 'เน็ต' ที่ใช้ได้"},{"questionTh":"'ฉันขอซิมสำหรับนักท่องเที่ยว' พูดว่าอะไร","choices":["I'd like a SIM card for tourists.","I'd like a coffee, please.","Where is my gate?","I lost my bag."],"answerIndex":0,"explainTh":"เป็นประโยคขอซิมสำหรับนักท่องเที่ยวโดยตรง"},{"questionTh":"'เติมเงิน / เติมเน็ต' ภาษาอังกฤษคือคำใด","choices":["check in","set up","log out","top up"],"answerIndex":3,"explainTh":"top up = การเติมเงินหรือเติมเน็ตเข้าซิม"},{"questionTh":"พนักงานมักขอเอกสารอะไรตอนซื้อซิมในต่างประเทศ","choices":["boarding pass","passport","baggage tag","credit card only"],"answerIndex":1,"explainTh":"หลายประเทศกำหนดให้ใช้ passport ลงทะเบียนซิมก่อนเปิดใช้งาน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$แลกเงินและกดเงินตู้ ATM$q$, $q${"listen":{"audioText":"Hi, I'd like to exchange US dollars for Japanese yen. (hear) How much would you like to change? Three hundred dollars, please. What's the exchange rate today? (hear) The rate is on the screen, and there is a small fee. My ATM card doesn't work in this machine. (hear) Please try another machine over there.","thaiExplain":"ที่เคาน์เตอร์แลกเงิน ให้บอกว่าจะแลกจากสกุลไหนเป็นสกุลไหนและจำนวนเท่าไร อย่าลืมถามอัตราแลกเปลี่ยน (exchange rate) และค่าธรรมเนียม (fee) ส่วนการกด ATM ถ้าบัตรใช้ไม่ได้ ให้ลองตู้อื่นหรือแจ้งพนักงาน"},"vocab":[{"word":"exchange rate","ipa":"/ɪksˈtʃeɪndʒ reɪt/","thai":"อัตราแลกเปลี่ยน","exampleEn":"What's the exchange rate today?","exampleTh":"วันนี้อัตราแลกเปลี่ยนเท่าไรคะ","associationHintTh":"exchange = แลก + rate = อัตรา → อัตราการแลกเงิน"},{"word":"currency","ipa":"/ˈkʌrənsi/","thai":"สกุลเงิน","exampleEn":"Which currency would you like?","exampleTh":"คุณต้องการสกุลเงินอะไรคะ","associationHintTh":"คิดถึง 'current' เงินที่หมุนเวียนใช้ในประเทศ = สกุลเงิน"},{"word":"withdraw","ipa":"/wɪðˈdrɔː/","thai":"ถอนเงิน","exampleEn":"I want to withdraw some cash.","exampleTh":"ฉันอยากถอนเงินสดค่ะ","associationHintTh":"with + draw (ดึงออก) → ดึงเงินออกจากบัญชี = ถอนเงิน"},{"word":"fee","ipa":"/fiː/","thai":"ค่าธรรมเนียม","exampleEn":"Is there a fee for this?","exampleTh":"อันนี้มีค่าธรรมเนียมไหมคะ","associationHintTh":"'ฟี' สั้นๆ = เงินค่าธรรมเนียมที่ต้องจ่ายเพิ่ม"},{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"Can I pay in cash?","exampleTh":"จ่ายเงินสดได้ไหมคะ","associationHintTh":"'แคช' = เงินสด (จับต้องได้ ไม่ใช่บัตร)"}],"examples":[{"en":"I'd like to exchange dollars for yen.","th":"ฉันขอแลกดอลลาร์เป็นเยนค่ะ"},{"en":"What's the exchange rate today?","th":"วันนี้อัตราแลกเปลี่ยนเท่าไรคะ"},{"en":"Is there a fee?","th":"มีค่าธรรมเนียมไหมคะ"},{"en":"I want to withdraw some cash.","th":"ฉันอยากถอนเงินสดค่ะ"},{"en":"My card doesn't work in this ATM.","th":"บัตรของฉันใช้กับตู้เอทีเอ็มนี้ไม่ได้ค่ะ"},{"en":"Can I have smaller bills, please?","th":"ขอเป็นแบงก์ย่อยได้ไหมคะ"}],"quiz":[{"questionTh":"'ถอนเงิน' จากตู้ ATM ใช้คำว่าอะไร","choices":["deposit","transfer","withdraw","exchange"],"answerIndex":2,"explainTh":"withdraw = ถอนเงินออกมา ส่วน deposit คือฝากเงิน"},{"questionTh":"'อัตราแลกเปลี่ยน' ภาษาอังกฤษคือคำใด","choices":["exchange rate","boarding pass","baggage tag","top up"],"answerIndex":0,"explainTh":"exchange rate = อัตราแลกเปลี่ยนเงินระหว่างสองสกุล"},{"questionTh":"'ค่าธรรมเนียม' ภาษาอังกฤษคือคำใด","choices":["cash","rate","currency","fee"],"answerIndex":3,"explainTh":"fee = ค่าธรรมเนียม เงินที่ต้องจ่ายเพิ่มจากยอดหลัก"},{"questionTh":"ถ้าบัตร ATM ใช้กับตู้นี้ไม่ได้ ควรพูดว่าอะไร","choices":["I'd like a window seat.","My card doesn't work in this ATM.","My flight is delayed.","I have a connecting flight."],"answerIndex":1,"explainTh":"ประโยคนี้บอกว่าบัตรใช้กับตู้เอทีเอ็มนี้ไม่ได้ ตรงกับสถานการณ์"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$ที่เคาน์เตอร์บริการสนามบินขาเข้า$q$, $q$You are a friendly airport service agent at the arrivals hall of an international airport. A traveler has just landed and comes to your counter for help. Respond naturally to their questions about baggage claim, a missing suitcase, connecting flights, buying a SIM card, and exchanging money, and ask simple follow-up questions to keep the conversation going.$q$, $q$Airport Service Agent$q$, $q$ขอความช่วยเหลือเรื่องรับกระเป๋าและแจ้งกระเป๋าหาย ถามทางไปต่อเครื่อง และถามว่าจะซื้อซิมกับแลกเงินได้ที่ไหนในสนามบิน$q$, $q$["แจ้งเจ้าหน้าที่ได้ว่ากระเป๋าหาย พร้อมบอกลักษณะกระเป๋าและเสนอโชว์ป้ายติดกระเป๋า (baggage tag)","ถามทางไปต่อเครื่อง โดยระบุคำว่า transfer หรือ gate ได้ถูกต้อง","ถามเป็นภาษาอังกฤษได้ว่าจะซื้อซิมและแลกเงินได้ที่ไหน"]$q$::jsonb);
END IF;
END $do$;

-- Unit 7: แท็กซี่และเรียกรถ (Grab/Uber)
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 7) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 7, $q$แท็กซี่และเรียกรถ (Grab/Uber)$q$, $q$ขึ้นแท็กซี่ บอกจุดหมาย จ่ายเงิน และปฏิเสธแท็กซี่เถื่อน/คนตื๊ออย่างปลอดภัย$q$, 'A1', $q$🚕$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ขึ้นแท็กซี่และบอกจุดหมาย$q$, $q${"listen":{"audioText":"Hello, are you free? Can you take me to the Grand Hotel, please? (hear) Sure, get in. How much is it to the hotel? (hear) About fifteen dollars, with the meter.","thaiExplain":"สถานการณ์คือเรากำลังจะขึ้นแท็กซี่ที่สนามบินหรือริมถนน ขั้นแรกถามว่าคันนี้ว่างไหม จากนั้นบอกจุดหมายให้ชัด และถามราคาก่อนออกรถทุกครั้ง ถ้าโชว์ที่อยู่ในมือถือให้คนขับดูจะยิ่งชัวร์"},"vocab":[{"word":"taxi","ipa":"/ˈtæksi/","thai":"แท็กซี่","exampleEn":"I need a taxi to the hotel.","exampleTh":"ผม/ฉันต้องการแท็กซี่ไปโรงแรม","associationHintTh":"ทับศัพท์ตรงตัวว่า 'แท็กซี่' จำง่ายมาก"},{"word":"free","ipa":"/friː/","thai":"ว่าง (รับผู้โดยสารได้)","exampleEn":"Excuse me, are you free?","exampleTh":"ขอโทษครับ/คะ คันนี้ว่างไหม","associationHintTh":"free = ฟรี/ว่าง คิดว่า 'คันนี้ว่างให้ขึ้นไหม'"},{"word":"hotel","ipa":"/hoʊˈtel/","thai":"โรงแรม","exampleEn":"Please take me to my hotel.","exampleTh":"ช่วยพาไปโรงแรมของผม/ฉันด้วย","associationHintTh":"อ่านว่า 'โฮ-เท็ล' เน้นเสียงพยางค์หลัง"},{"word":"airport","ipa":"/ˈeərpɔːrt/","thai":"สนามบิน","exampleEn":"How much is it to the airport?","exampleTh":"ไปสนามบินราคาเท่าไหร่","associationHintTh":"air (อากาศ) + port (ท่า) = ท่าอากาศยาน = สนามบิน"},{"word":"address","ipa":"/əˈdres/","thai":"ที่อยู่","exampleEn":"Here is the address on my phone.","exampleTh":"นี่คือที่อยู่ในมือถือของผม/ฉัน","associationHintTh":"อ่าน 'อะ-เดรส' เน้นเสียงพยางค์หลัง 'เดรส'"}],"examples":[{"en":"Hello, are you free?","th":"สวัสดีครับ/คะ คันนี้ว่างไหม"},{"en":"Can you take me to this address?","th":"พาไปที่อยู่นี้ได้ไหมครับ/คะ"},{"en":"I want to go to the airport, please.","th":"ผม/ฉันอยากไปสนามบินครับ/คะ"},{"en":"How much is it to the Grand Hotel?","th":"ไปแกรนด์โฮเทลราคาเท่าไหร่"},{"en":"Please use the meter.","th":"ช่วยเปิดมิเตอร์ด้วยครับ/คะ"},{"en":"Do you go to the train station?","th":"ไปสถานีรถไฟไหมครับ/คะ"},{"en":"Here is the address.","th":"นี่คือที่อยู่ครับ/คะ"}],"quiz":[{"questionTh":"คนขับถามว่า \"Where to?\" ควรตอบว่าอย่างไร?","choices":["The airport, please.","Yes, I am fine.","You're welcome.","See you later."],"answerIndex":0,"explainTh":"\"Where to?\" แปลว่า 'จะไปไหน' ต้องตอบด้วยจุดหมาย เช่น สนามบิน ตัวเลือกอื่นไม่เกี่ยวกับจุดหมาย"},{"questionTh":"อยากถามราคาไปโรงแรม พูดว่าอย่างไร?","choices":["What time is it?","How much is it to the hotel?","How are you?","Where is the hotel?"],"answerIndex":1,"explainTh":"\"How much is it to the hotel?\" = ไปโรงแรมราคาเท่าไหร่ ควรถามราคาก่อนออกรถเสมอ"},{"questionTh":"จะบอกให้คนขับเปิดมิเตอร์ พูดว่าอย่างไร?","choices":["Turn left, please.","Stop here, please.","Please use the meter.","Open the door, please."],"answerIndex":2,"explainTh":"\"Please use the meter.\" = ขอให้เปิดมิเตอร์ ช่วยกันโดนโก่งราคา ตัวเลือกอื่นเป็นการสั่งทางหรือเปิดประตู"},{"questionTh":"ต้องการให้คนขับพาไปตาม 'ที่อยู่' ที่โชว์ในมือถือ พูดว่าอย่างไร?","choices":["What is your name?","How old are you?","Are you hungry?","Can you take me to this address?"],"answerIndex":3,"explainTh":"\"Can you take me to this address?\" = พาไปที่อยู่นี้ได้ไหม เหมาะกับตอนโชว์ที่อยู่ในมือถือให้คนขับดู"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$สั่งทางระหว่างนั่ง จอดตรงนี้ จ่ายเงิน/ขอใบเสร็จ$q$, $q${"listen":{"audioText":"Turn right at the traffic light, please. You can stop here. (hear) Okay, that's twelve dollars. Can I pay by card? (hear) Sorry, cash only. Can I have a receipt, please?","thaiExplain":"ระหว่างนั่งเราสั่งทางได้ เช่น เลี้ยวซ้าย/ขวา ตรงไป และบอก 'จอดตรงนี้' เมื่อถึงที่หมาย พอจ่ายเงินให้ถามวิธีจ่าย (เงินสดหรือบัตร) และขอใบเสร็จไว้เป็นหลักฐานเสมอ"},"vocab":[{"word":"left","ipa":"/left/","thai":"ซ้าย","exampleEn":"Turn left at the corner.","exampleTh":"เลี้ยวซ้ายตรงหัวมุม","associationHintTh":"left = เลฟท์ = ซ้าย นึกถึงมือซ้ายถือคำว่า 'เลฟ'"},{"word":"right","ipa":"/raɪt/","thai":"ขวา","exampleEn":"Please turn right here.","exampleTh":"ช่วยเลี้ยวขวาตรงนี้","associationHintTh":"right = ไรท์ = ขวา (แปลว่า 'ถูกต้อง' ด้วย) นึกถึงมือขวาคือมือที่ 'ถูก'"},{"word":"stop","ipa":"/stɑːp/","thai":"หยุด / จอด","exampleEn":"Stop here, please.","exampleTh":"จอดตรงนี้ครับ/คะ","associationHintTh":"สตอป = หยุด นึกถึงป้าย STOP สีแดงที่เห็นบ่อย"},{"word":"receipt","ipa":"/rɪˈsiːt/","thai":"ใบเสร็จ","exampleEn":"Can I have a receipt, please?","exampleTh":"ขอใบเสร็จหน่อยได้ไหมครับ/คะ","associationHintTh":"อ่านว่า 'รี-ซีท' ตัว p เงียบ ไม่ต้องออกเสียง"},{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"I will pay in cash.","exampleTh":"ผม/ฉันจะจ่ายเป็นเงินสด","associationHintTh":"แคช = เงินสด นึกถึง 'แคชเชียร์' ที่รับเงินสด"}],"examples":[{"en":"Turn left here, please.","th":"เลี้ยวซ้ายตรงนี้ครับ/คะ"},{"en":"Turn right at the corner.","th":"เลี้ยวขวาตรงหัวมุมครับ/คะ"},{"en":"Go straight, please.","th":"ตรงไปครับ/คะ"},{"en":"Stop here, please.","th":"จอดตรงนี้ครับ/คะ"},{"en":"Can I pay by card?","th":"จ่ายด้วยบัตรได้ไหมครับ/คะ"},{"en":"Can I have a receipt, please?","th":"ขอใบเสร็จหน่อยได้ไหมครับ/คะ"},{"en":"Keep the change.","th":"ไม่ต้องทอนครับ/คะ"}],"quiz":[{"questionTh":"จะบอกให้คนขับ 'จอดตรงนี้' พูดว่าอย่างไร?","choices":["Go straight, please.","Stop here, please.","Turn left, please.","Speed up, please."],"answerIndex":1,"explainTh":"\"Stop here, please.\" = จอดตรงนี้ ส่วนตัวเลือกอื่นคือ 'ตรงไป', 'เลี้ยวซ้าย', 'เร่งความเร็ว'"},{"questionTh":"อยากได้ใบเสร็จหลังจ่ายเงิน พูดว่าอย่างไร?","choices":["Can I have a receipt, please?","Can I have a menu, please?","Can I have a ticket, please?","Can I have a room, please?"],"answerIndex":0,"explainTh":"receipt = ใบเสร็จ ส่วน menu = เมนู, ticket = ตั๋ว, room = ห้อง จำคำว่า receipt ให้ได้"},{"questionTh":"ประโยค \"Keep the change.\" ใช้พูดตอนไหน?","choices":["ตอนเรียกแท็กซี่","ตอนบอกทาง","ตอนจ่ายเงินแล้วไม่รับเงินทอน","ตอนขอใบเสร็จ"],"answerIndex":2,"explainTh":"\"Keep the change.\" = เก็บเงินทอนไว้เลย (ไม่ต้องทอน) ใช้ตอนจ่ายเงินเมื่อไม่อยากรับเงินทอนคืน"},{"questionTh":"ประโยค \"Turn right at the corner.\" แปลว่าอะไร?","choices":["ตรงไปเรื่อยๆ","เลี้ยวซ้ายตรงหัวมุม","จอดที่หัวมุม","เลี้ยวขวาตรงหัวมุม"],"answerIndex":3,"explainTh":"turn right = เลี้ยวขวา, at the corner = ตรงหัวมุม รวมกันเป็น 'เลี้ยวขวาตรงหัวมุม'"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$เจอคนขับ Grab/Uber ตอนมารับ$q$, $q${"listen":{"audioText":"Hi, are you Somchai? (hear) Yes, that's me. Is your car the white Toyota? What is the plate number? (hear) It's 1234. Great, I booked the ride on the app. I'm going to the airport.","thaiExplain":"เมื่อจองรถผ่านแอป Grab/Uber ก่อนขึ้นรถให้เช็กให้ตรงกับในแอปเสมอ ยืนยันชื่อคนขับ รุ่นและสีรถ และเลขทะเบียน เพื่อความปลอดภัยว่าเราขึ้นถูกคัน"},"vocab":[{"word":"driver","ipa":"/ˈdraɪvər/","thai":"คนขับ","exampleEn":"Are you my driver?","exampleTh":"คุณคือคนขับของผม/ฉันใช่ไหม","associationHintTh":"drive (ขับ) + er (คน) = คนขับ"},{"word":"car","ipa":"/kɑːr/","thai":"รถยนต์","exampleEn":"Is this your car?","exampleTh":"นี่รถของคุณใช่ไหม","associationHintTh":"คาร์ = รถยนต์ ทับศัพท์ที่คุ้นหู"},{"word":"plate number","ipa":"/pleɪt ˈnʌmbər/","thai":"เลขทะเบียนรถ","exampleEn":"What is the plate number?","exampleTh":"เลขทะเบียนรถอะไรครับ/คะ","associationHintTh":"plate = แผ่นป้าย, number = เลข รวมกันคือเลขป้ายทะเบียน"},{"word":"book","ipa":"/bʊk/","thai":"จอง","exampleEn":"I booked a ride on the app.","exampleTh":"ผม/ฉันจองรถผ่านแอป","associationHintTh":"book ไม่ได้แปลว่า 'หนังสือ' อย่างเดียว แต่แปลว่า 'จอง' ก็ได้"},{"word":"app","ipa":"/æp/","thai":"แอป (แอปพลิเคชัน)","exampleEn":"I called the car on the app.","exampleTh":"ผม/ฉันเรียกรถผ่านแอป","associationHintTh":"แอป = แอปพลิเคชันในมือถือ เช่น Grab / Uber"}],"examples":[{"en":"Hi, are you my driver?","th":"สวัสดีครับ/คะ คุณคือคนขับของผม/ฉันใช่ไหม"},{"en":"Are you Somchai? That's my name in the app.","th":"คุณสมชายใช่ไหม นี่คือชื่อผม/ฉันในแอป"},{"en":"What is the plate number?","th":"เลขทะเบียนรถอะไรครับ/คะ"},{"en":"Is your car the white Toyota?","th":"รถคุณคือโตโยต้าสีขาวใช่ไหม"},{"en":"I booked a ride on the app.","th":"ผม/ฉันจองรถผ่านแอป"},{"en":"I'm going to the airport.","th":"ผม/ฉันจะไปสนามบิน"},{"en":"Can you open the trunk, please?","th":"ช่วยเปิดฝากระโปรงท้ายให้หน่อยได้ไหม"}],"quiz":[{"questionTh":"ก่อนขึ้นรถ Grab/Uber ควรเช็กอะไรเพื่อความปลอดภัย?","choices":["สีเสื้อของคนขับ","ชื่อคนขับ รุ่น/สีรถ และเลขทะเบียนให้ตรงกับในแอป","คนขับหิวหรือยัง","คนขับชอบเพลงอะไร"],"answerIndex":1,"explainTh":"ต้องเช็กชื่อคนขับ รุ่น/สีรถ และเลขทะเบียนให้ตรงกับในแอป จะได้ชัวร์ว่าขึ้นถูกคันและปลอดภัย"},{"questionTh":"จะถามเลขทะเบียนรถ พูดว่าอย่างไร?","choices":["What is the plate number?","What is your phone number?","What time is it?","What is your name?"],"answerIndex":0,"explainTh":"plate number = เลขทะเบียนรถ ส่วนตัวเลือกอื่นถามเบอร์โทร เวลา และชื่อ"},{"questionTh":"ประโยค \"I booked a ride on the app.\" แปลว่าอะไร?","choices":["ผมทำมือถือหาย","ผมอยากซื้อรถ","ผมจองรถผ่านแอป","ผมเป็นคนขับ"],"answerIndex":2,"explainTh":"book = จอง, ride = การเดินทาง/รถที่นั่ง, on the app = ผ่านแอป รวมเป็น 'จองรถผ่านแอป'"},{"questionTh":"คนขับถามว่า \"Are you Somchai?\" ถ้าคุณชื่อสมชาย ควรตอบว่าอย่างไร?","choices":["No, thank you.","Goodbye.","I don't know.","Yes, that's me."],"answerIndex":3,"explainTh":"\"Yes, that's me.\" = ใช่ ผม/ฉันเองครับ/คะ ใช้ยืนยันว่าเราคือคนที่คนขับมารับ"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$ปฏิเสธแท็กซี่เถื่อน/คนตื๊อ อย่างปลอดภัย$q$, $q${"listen":{"audioText":"Taxi? Taxi, my friend? Cheap, cheap! (hear) No, thank you. I am not interested. Very good price, come with me! (hear) No, thank you. I already have a ride. Please leave me alone.","thaiExplain":"ที่สนามบินหรือสถานีมักมีคนตื๊อและแท็กซี่เถื่อนเข้ามาชวน ซึ่งอาจโก่งราคาหรือไม่ปลอดภัย ให้ปฏิเสธหนักแน่นแต่สุภาพ ไม่ต้องเกรงใจ แล้วเดินไปที่จุดแท็กซี่ทางการ/มิเตอร์ หรือเรียกผ่านแอปเท่านั้น การปฏิเสธชัดเจนช่วยกันโดนหลอกและโดนโก่งราคา"},"vocab":[{"word":"no, thank you","ipa":"/noʊ ˈθæŋk juː/","thai":"ไม่ ขอบคุณ (ปฏิเสธสุภาพ)","exampleEn":"No, thank you. I don't need a taxi.","exampleTh":"ไม่ครับ/ค่ะ ขอบคุณ ผม/ฉันไม่ต้องการแท็กซี่","associationHintTh":"ปฏิเสธสุภาพ 'ไม่ ขอบคุณ' พูดสั้นแต่หนักแน่น ไม่ต้องเกรงใจ"},{"word":"interested","ipa":"/ˈɪntrəstɪd/","thai":"สนใจ (not interested = ไม่สนใจ)","exampleEn":"I am not interested.","exampleTh":"ผม/ฉันไม่สนใจ","associationHintTh":"interest = ความสนใจ, 'not interested' = ไม่สนใจ"},{"word":"official","ipa":"/əˈfɪʃl/","thai":"ทางการ / ถูกกฎหมาย","exampleEn":"I will use the official taxi.","exampleTh":"ผม/ฉันจะใช้แท็กซี่ทางการ","associationHintTh":"ออฟฟิเชียล = ทางการ นึกถึง 'ออฟฟิศ' ที่เป็นเรื่องเป็นทางการ"},{"word":"alone","ipa":"/əˈloʊn/","thai":"ตามลำพัง (leave me alone = อย่ามายุ่ง)","exampleEn":"Please leave me alone.","exampleTh":"อย่ามายุ่งกับผม/ฉันครับ/คะ","associationHintTh":"a + lone (โดดเดี่ยว) = ตามลำพัง; 'leave me alone' = ปล่อยฉันไว้คนเดียว"},{"word":"scam","ipa":"/skæm/","thai":"การหลอกลวง / การโกง","exampleEn":"Illegal taxis are often a scam.","exampleTh":"แท็กซี่เถื่อนมักเป็นการหลอกลวง","associationHintTh":"สแกม = การโกง เสียงคล้าย 'สแปม' ที่น่ารำคาญและน่าระวัง"}],"examples":[{"en":"No, thank you. I am not interested.","th":"ไม่ครับ/ค่ะ ขอบคุณ ผม/ฉันไม่สนใจ"},{"en":"Please leave me alone.","th":"อย่ามายุ่งกับผม/ฉันครับ/คะ"},{"en":"I will use the official taxi.","th":"ผม/ฉันจะใช้แท็กซี่ทางการ"},{"en":"I already have a ride.","th":"ผม/ฉันมีรถมารับแล้ว"},{"en":"No, I will use the meter.","th":"ไม่ครับ/คะ ผม/ฉันจะใช้แท็กซี่มิเตอร์"},{"en":"I'm not going with you.","th":"ผม/ฉันจะไม่ไปกับคุณ"},{"en":"Where is the official taxi stand?","th":"จุดจอดแท็กซี่ทางการอยู่ที่ไหนครับ/คะ"}],"quiz":[{"questionTh":"มีคนตื๊อชวนขึ้นแท็กซี่เถื่อน อยากปฏิเสธแบบสุภาพแต่หนักแน่น ควรพูดว่าอย่างไร?","choices":["Yes, please.","No, thank you. I am not interested.","Maybe later.","How much?"],"answerIndex":1,"explainTh":"\"No, thank you. I am not interested.\" ปฏิเสธชัดเจนและสุภาพ ไม่เปิดช่องให้ตื๊อต่อ; การถามราคา (How much?) จะยิ่งทำให้เขาตื๊อหนักขึ้น"},{"questionTh":"อยากบอกว่า 'มีรถมารับแล้ว' (เช่น จอง Grab ไว้) ควรพูดว่าอย่างไร?","choices":["I already have a ride.","I am lost.","I need a taxi.","I have no money."],"answerIndex":0,"explainTh":"\"I already have a ride.\" = มีรถมารับแล้ว คนตื๊อจะเลิกชวน; อย่าพูดว่าหลงทางหรือไม่มีเงิน เพราะอาจตกเป็นเป้าหมาย"},{"questionTh":"ทำไมควรใช้แท็กซี่ทางการหรือเรียกผ่านแอป แทนแท็กซี่เถื่อน/คนตื๊อ?","choices":["เพราะแพงกว่า","เพราะช้ากว่า","เพราะปลอดภัยกว่าและราคายุติธรรม ไม่โดนโก่งราคา/หลอก","เพราะคนขับพูดไทยได้"],"answerIndex":2,"explainTh":"แท็กซี่ทางการ/แอปมีการบันทึกคนขับและคิดราคาตามจริง ปลอดภัยกว่าและไม่โดนโก่งราคา ส่วนแท็กซี่เถื่อนเสี่ยงถูกหลอก"},{"questionTh":"ปฏิเสธไปแล้วแต่คนตื๊อยังตามตื๊อไม่หยุด ควรพูดว่าอย่างไร?","choices":["Thank you so much.","You are very kind.","Let's go together.","Please leave me alone."],"answerIndex":3,"explainTh":"\"Please leave me alone.\" = อย่ามายุ่ง ใช้เมื่อปฏิเสธแล้วยังโดนตื๊อ ถ้ายังไม่หยุดให้เดินไปหาเจ้าหน้าที่หรือจุดแท็กซี่ทางการ"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$นั่งแท็กซี่จากสนามบินไปโรงแรมให้จบทริปด้วยตัวเอง$q$, $q$You are a friendly taxi driver waiting at the official taxi stand of a busy international airport. A traveler gets into your taxi and needs to reach the Grand Hotel downtown. Greet them, ask where they want to go, use the meter, follow their directions during the ride, and take the payment at the end. Speak slowly with simple English, and gently prompt the traveler if they get stuck.$q$, $q$Airport Taxi Driver$q$, $q$ฝึกนั่งแท็กซี่ตั้งแต่ต้นจนจบทริป เป็นภาษาอังกฤษด้วยตัวเอง: ทักทาย บอกจุดหมาย ขอให้เปิดมิเตอร์ สั่งทางระหว่างนั่ง บอกจอด แล้วจ่ายเงินพร้อมขอใบเสร็จ$q$, $q$["บอกจุดหมาย (โรงแรม) และขอให้เปิดมิเตอร์หรือถามราคาก่อนออกรถได้","สั่งทางระหว่างนั่ง (เลี้ยวซ้าย/ขวา ตรงไป) และบอก 'Stop here, please.' ได้","จ่ายเงินและขอใบเสร็จด้วยประโยค 'Can I have a receipt, please?' ได้"]$q$::jsonb);
END IF;
END $do$;

-- Unit 8: ขนส่งสาธารณะและถามทาง
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 8) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 8, $q$ขนส่งสาธารณะและถามทาง$q$, $q$ซื้อตั๋วรถไฟ/รถไฟฟ้า หาชานชาลา ขึ้นรถเมล์ และถามทาง$q$, 'A2', $q$🚇$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ซื้อตั๋วรถไฟ/รถไฟฟ้า และเติมบัตร$q$, $q${"listen":{"audioText":"Traveler: Hi, I'd like a round trip ticket to Central Station, please. Staff (hear): Sure. Single or return? Traveler: Round trip, please. Can I also top up this card? Staff (hear): Of course. How much would you like to add? The fare is three dollars. Traveler: Please add twenty dollars. Thank you!","thaiExplain":"ที่ช่องขายตั๋วหรือเครื่องขายตั๋วอัตโนมัติ ให้บอกสถานีปลายทางและเลือกว่าจะเอาตั๋วเที่ยวเดียวหรือไป-กลับ ถ้ามีบัตรโดยสารก็บอกว่าอยากเติมเงินเท่าไหร่ และฟังพนักงานบอกราคาค่าโดยสาร"},"vocab":[{"word":"ticket","ipa":"/ˈtɪkɪt/","thai":"ตั๋ว","exampleEn":"I need one ticket to the airport.","exampleTh":"ผมต้องการตั๋วไปสนามบินหนึ่งใบ","associationHintTh":"ทิค-เก็ต เสียงคล้าย 'ติ๊ก' ตั๋วที่ต้องเอาไปติ๊ก/แตะตอนผ่านประตู"},{"word":"one-way","ipa":"/ˌwʌnˈweɪ/","thai":"เที่ยวเดียว (ไปอย่างเดียว)","exampleEn":"I'd like a one-way ticket, please.","exampleTh":"ขอตั๋วเที่ยวเดียวหนึ่งใบครับ","associationHintTh":"one = หนึ่ง, way = ทาง → ทางเดียว = ไปอย่างเดียวไม่กลับ"},{"word":"round trip","ipa":"/ˌraʊnd ˈtrɪp/","thai":"ไป-กลับ","exampleEn":"Is a round trip ticket cheaper?","exampleTh":"ตั๋วไป-กลับถูกกว่าไหมคะ","associationHintTh":"round = วนรอบ, trip = ทริป → ทริปที่วนกลับมา = ไป-กลับ"},{"word":"top up","ipa":"/ˈtɒp ʌp/","thai":"เติมเงินเข้าบัตร","exampleEn":"I want to top up my travel card.","exampleTh":"ผมอยากเติมเงินบัตรโดยสาร","associationHintTh":"top = ด้านบน/เต็ม, up = ขึ้น → เติมให้เต็มขึ้น = เติมเงินบัตร"},{"word":"fare","ipa":"/feə(r)/","thai":"ค่าโดยสาร","exampleEn":"How much is the fare to the city?","exampleTh":"ค่าโดยสารไปในเมืองเท่าไหร่คะ","associationHintTh":"แฟร์ เสียงเหมือน 'fair' (ยุติธรรม) → ค่าโดยสารที่ต้องจ่ายให้แฟร์ๆ"}],"examples":[{"en":"One ticket to the airport, please.","th":"ขอตั๋วไปสนามบินหนึ่งใบครับ"},{"en":"How much is a ticket to downtown?","th":"ตั๋วไปตัวเมืองราคาเท่าไหร่คะ"},{"en":"I'd like a round trip ticket, please.","th":"ขอตั๋วไป-กลับหนึ่งใบครับ"},{"en":"Can I top up my card here?","th":"เติมเงินบัตรที่นี่ได้ไหมคะ"},{"en":"Do you take credit cards?","th":"รับบัตรเครดิตไหมครับ"},{"en":"Single or return?","th":"(ได้ยินจากพนักงาน) เที่ยวเดียวหรือไป-กลับคะ"},{"en":"That's fifteen dollars, please.","th":"(ได้ยินจากพนักงาน) ทั้งหมดสิบห้าดอลลาร์ครับ"}],"quiz":[{"questionTh":"พนักงานถามว่า \"Single or return?\" หมายความว่าอะไร?","choices":["ถามว่าจะจ่ายเงินสดหรือบัตร","ถามว่าเอาตั๋วเที่ยวเดียวหรือไป-กลับ","ถามว่าจะไปสถานีไหน","ถามว่ามากันกี่คน"],"answerIndex":1,"explainTh":"single = เที่ยวเดียว, return = ไป-กลับ พนักงานกำลังถามว่าคุณต้องการตั๋วแบบไหน"},{"questionTh":"อยากเติมเงินเข้าบัตรโดยสาร ควรพูดว่าอะไร?","choices":["Can I top up my card?","Can I return my card?","Can I sell my card?","Can I open my card?"],"answerIndex":0,"explainTh":"top up = เติมเงินเข้าบัตร ส่วน return/sell/open ไม่ได้แปลว่าเติมเงิน"},{"questionTh":"คำว่า \"fare\" แปลว่าอะไร?","choices":["ชานชาลา","ตั๋ว","ค่าโดยสาร","ทางออก"],"answerIndex":2,"explainTh":"fare = ค่าโดยสาร (จำนวนเงินที่ต้องจ่ายเพื่อเดินทาง)"},{"questionTh":"ประโยคไหนใช้ถามราคาตั๋ว?","choices":["Where is the platform?","Single or return?","Can I top up here?","How much is a ticket to downtown?"],"answerIndex":3,"explainTh":"How much...? = ราคาเท่าไหร่ ใช้ถามราคาตั๋วได้ตรงที่สุด"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$หาชานชาลา สาย และขึ้นรถเมล์ให้ลงถูกป้าย$q$, $q${"listen":{"audioText":"Traveler: Excuse me, which platform is the train to Riverside? Staff (hear): Platform 4. It leaves in ten minutes. Traveler: Thanks! And does this bus go to the museum? Driver (hear): Yes, it does. I'll tell you when it's your stop. Traveler: Great, thank you!","thaiExplain":"เมื่อขึ้นรถไฟหรือรถเมล์ ให้ถามว่าต้องขึ้นชานชาลาไหนหรือสายไหน และถามคนขับ/พนักงานได้ว่ารถคันนี้ไปที่ที่เราจะไปไหม แล้วขอให้ช่วยบอกตอนถึงป้ายที่เราจะลง"},"vocab":[{"word":"platform","ipa":"/ˈplætfɔːm/","thai":"ชานชาลา","exampleEn":"The train leaves from platform 3.","exampleTh":"รถไฟออกจากชานชาลา 3","associationHintTh":"platform = เวที/ที่ยกพื้น → ชานชาลาที่เรายืนรอรถไฟ"},{"word":"line","ipa":"/laɪn/","thai":"สาย (รถไฟฟ้า/รถเมล์)","exampleEn":"Take the red line to the center.","exampleTh":"นั่งสายสีแดงไปใจกลางเมือง","associationHintTh":"line = เส้น → สายรถไฟที่เป็นเส้นๆ บนแผนที่ (สายสีแดง สีน้ำเงิน)"},{"word":"stop","ipa":"/stɒp/","thai":"ป้าย/สถานีที่จอด","exampleEn":"The museum is three stops from here.","exampleTh":"พิพิธภัณฑ์อยู่ห่างจากที่นี่สามป้าย","associationHintTh":"stop = หยุด → จุดที่รถหยุดจอด = ป้าย"},{"word":"get off","ipa":"/ˌɡet ˈɒf/","thai":"ลงจากรถ","exampleEn":"Where should I get off?","exampleTh":"ผมควรลงป้ายไหนครับ","associationHintTh":"off = ออก/ลง → get off = ก้าวออกจากรถ = ลงรถ (ตรงข้ามกับ get on)"},{"word":"transfer","ipa":"/trænsˈfɜː(r)/","thai":"เปลี่ยนสาย/ต่อรถ","exampleEn":"You need to transfer at the next station.","exampleTh":"คุณต้องเปลี่ยนสายที่สถานีหน้า","associationHintTh":"transfer = โอน/ย้าย (เหมือนโอนเงิน) → ย้ายไปขึ้นอีกสาย"}],"examples":[{"en":"Which platform is the train to Riverside?","th":"รถไฟไปริเวอร์ไซด์อยู่ชานชาลาไหนคะ"},{"en":"Does this bus go to the museum?","th":"รถเมล์คันนี้ไปพิพิธภัณฑ์ไหมครับ"},{"en":"Which line goes to the city center?","th":"สายไหนไปใจกลางเมืองคะ"},{"en":"Can you tell me when to get off?","th":"ช่วยบอกด้วยได้ไหมว่าต้องลงตรงไหน"},{"en":"Where do I transfer to the blue line?","th":"ต้องเปลี่ยนไปสายสีน้ำเงินที่ไหนครับ"},{"en":"Platform 4. It leaves in ten minutes.","th":"(ได้ยินจากพนักงาน) ชานชาลา 4 ค่ะ รถออกในอีกสิบนาที"},{"en":"This is your stop.","th":"(ได้ยินจากคนขับ) ป้ายนี้ที่คุณจะลงครับ"}],"quiz":[{"questionTh":"คำว่า \"platform\" แปลว่าอะไร?","choices":["ป้ายรถเมล์","ตั๋ว","ชานชาลา","ทางออก"],"answerIndex":2,"explainTh":"platform = ชานชาลา คือที่ที่เรายืนรอขึ้นรถไฟ"},{"questionTh":"อยากรู้ว่ารถเมล์คันนี้ไปพิพิธภัณฑ์ไหม ควรถามว่าอะไร?","choices":["Does this bus go to the museum?","Where is the museum bus?","How much is the museum?","When is the museum?"],"answerIndex":0,"explainTh":"Does this bus go to...? = รถคันนี้ไป...ไหม เป็นวิธีถามปลายทางของรถที่ถูกต้อง"},{"questionTh":"คำว่า \"get off\" หมายความว่าอะไร?","choices":["ขึ้นรถ","ซื้อตั๋ว","รอรถ","ลงจากรถ"],"answerIndex":3,"explainTh":"get off = ลงจากรถ ตรงข้ามกับ get on (ขึ้นรถ)"},{"questionTh":"คนขับพูดว่า \"This is your stop.\" หมายความว่าอะไร?","choices":["รถเสีย","ถึงป้ายที่คุณจะลงแล้ว","คุณขึ้นผิดคัน","ต้องจ่ายเงินเพิ่ม"],"answerIndex":1,"explainTh":"your stop = ป้ายของคุณ ประโยคนี้แปลว่าถึงป้ายที่คุณต้องลงแล้ว"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$ถามทางจากคนแปลกหน้าและฟังคำบอกทาง$q$, $q${"listen":{"audioText":"Traveler: Excuse me, how do I get to the train station? Local (hear): Go straight for two blocks, then turn left. Traveler: Is it far? Local (hear): No, it's about a five-minute walk. It's next to the bank. Traveler: Thank you so much!","thaiExplain":"เวลาหลงทาง ให้เริ่มด้วย \"Excuse me\" แล้วถามทาง ฟังคำสำคัญ เช่น straight (ตรงไป), turn left/right (เลี้ยวซ้าย/ขวา), next to (ข้างๆ) ถ้าไม่แน่ใจ ขอให้เขาชี้บนแผนที่ให้ได้"},"vocab":[{"word":"straight","ipa":"/streɪt/","thai":"ตรงไป","exampleEn":"Go straight to the end of the road.","exampleTh":"เดินตรงไปจนสุดถนน","associationHintTh":"straight = ตรง (ผมตรงเรียก straight hair) → เดินตรงไป"},{"word":"turn left","ipa":"/ˌtɜːn ˈleft/","thai":"เลี้ยวซ้าย","exampleEn":"Turn left at the traffic light.","exampleTh":"เลี้ยวซ้ายตรงไฟแดง","associationHintTh":"turn = เลี้ยว, left = ซ้าย → เลี้ยวซ้าย"},{"word":"turn right","ipa":"/ˌtɜːn ˈraɪt/","thai":"เลี้ยวขวา","exampleEn":"Turn right after the bank.","exampleTh":"เลี้ยวขวาหลังจากผ่านธนาคาร","associationHintTh":"right = ขวา (และแปลว่า 'ถูกต้อง') → เลี้ยวขวา"},{"word":"next to","ipa":"/ˈnekst tuː/","thai":"ข้างๆ / ติดกับ","exampleEn":"The hotel is next to the station.","exampleTh":"โรงแรมอยู่ข้างๆ สถานี","associationHintTh":"next = ถัดไป, to = ถึง → ถัดไปติดๆ กัน = ข้างๆ"},{"word":"corner","ipa":"/ˈkɔːnə(r)/","thai":"หัวมุม (ถนน)","exampleEn":"The shop is on the corner.","exampleTh":"ร้านอยู่ตรงหัวมุม","associationHintTh":"corner = มุม (เตะมุมในฟุตบอลเรียก corner) → หัวมุมถนน"}],"examples":[{"en":"Excuse me, how do I get to the station?","th":"ขอโทษครับ ไปสถานีรถไฟยังไงครับ"},{"en":"Where is the nearest bus stop?","th":"ป้ายรถเมล์ที่ใกล้ที่สุดอยู่ที่ไหนคะ"},{"en":"Is it far from here?","th":"อยู่ไกลจากที่นี่ไหมครับ"},{"en":"Can you show me on the map?","th":"ช่วยชี้บนแผนที่ให้หน่อยได้ไหมคะ"},{"en":"Go straight and turn right at the corner.","th":"(ได้ยินจากคนบอกทาง) ตรงไปแล้วเลี้ยวขวาตรงหัวมุม"},{"en":"It's next to the bank.","th":"(ได้ยินจากคนบอกทาง) อยู่ข้างๆ ธนาคารครับ"},{"en":"It's about a five-minute walk.","th":"(ได้ยินจากคนบอกทาง) เดินประมาณห้านาทีครับ"}],"quiz":[{"questionTh":"อยากถามทางไปสถานี ควรพูดว่าอะไร?","choices":["How much is the station?","When is the station?","Who is the station?","How do I get to the station?"],"answerIndex":3,"explainTh":"How do I get to...? = ไป...ยังไง เป็นประโยคถามทางที่ถูกต้อง"},{"questionTh":"คำว่า \"Turn left\" หมายความว่าอะไร?","choices":["เลี้ยวขวา","เลี้ยวซ้าย","ตรงไป","กลับรถ"],"answerIndex":1,"explainTh":"left = ซ้าย ดังนั้น turn left = เลี้ยวซ้าย"},{"questionTh":"เขาบอกว่า \"It's next to the bank.\" หมายความว่าอะไร?","choices":["อยู่ตรงข้ามธนาคาร","อยู่ในธนาคาร","อยู่ข้างๆ ธนาคาร","อยู่ไกลจากธนาคาร"],"answerIndex":2,"explainTh":"next to = ข้างๆ/ติดกับ ดังนั้นสถานที่นั้นอยู่ติดกับธนาคาร"},{"questionTh":"อยากรู้ว่าที่นั่นไกลไหม ควรถามว่าอะไร?","choices":["Is it far from here?","Is it open?","Is it cheap?","Is it big?"],"answerIndex":0,"explainTh":"far = ไกล ดังนั้น Is it far from here? = ไกลจากที่นี่ไหม"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$ซื้อตั๋วรถไฟฟ้า เติมบัตร และถามชานชาลา$q$, $q$You are a friendly ticket clerk at a busy metro station in London. A Thai traveler comes to your counter to buy a ticket, top up a travel card, and find out which platform to use. Answer clearly, ask normal follow-up questions like "Single or return?", tell them the fare, and give simple directions to the right platform.$q$, $q$Metro station ticket clerk$q$, $q$ซื้อตั๋วรถไฟฟ้าไปสถานีปลายทางให้ได้ เติมเงินบัตรโดยสาร และถามให้รู้ว่าต้องขึ้นชานชาลาไหน$q$, $q$["บอกสถานีปลายทางและซื้อตั๋วได้ถูกประเภท (เที่ยวเดียวหรือไป-กลับ)","ขอเติมเงินเข้าบัตรโดยสารและถามราคาค่าโดยสารได้","ถามและเข้าใจว่าต้องขึ้นชานชาลาไหน แล้วกล่าวขอบคุณอย่างสุภาพ"]$q$::jsonb);
END IF;
END $do$;

-- Unit 9: ที่พัก: เช็คอินถึงเช็คเอาท์
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 9) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 9, $q$ที่พัก: เช็คอินถึงเช็คเอาท์$q$, $q$ยืนยันการจอง เช็คอิน ขอของใช้เพิ่ม แจ้งปัญหาห้อง และเช็คเอาท์$q$, 'A2', $q$🏨$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ยืนยันการจอง เช็คอิน และถามข้อมูล (อาหารเช้า/ไวไฟ/เช็คเอาท์)$q$, $q${"listen":{"audioText":"Hi, I have a reservation under the name Somchai. (hear) Welcome, Mr. Somchai. May I see your passport, please? Sure, here you are. Is breakfast included? (hear) Yes, breakfast is from seven to ten on the second floor. Here's your key card, and checkout is at noon.","thaiExplain":"ตอนถึงโรงแรม บอกชื่อที่จองไว้แล้วยื่นหนังสือเดินทางให้พนักงาน จากนั้นถามข้อมูลที่จำเป็น เช่น เวลาอาหารเช้า รหัสไวไฟ และเวลาเช็คเอาท์ ประโยคที่มี (hear) คือประโยคที่พนักงานพูดกับเรา"},"vocab":[{"word":"reservation","ipa":"/ˌrezərˈveɪʃən/","thai":"การจอง","exampleEn":"I have a reservation for two nights.","exampleTh":"ผมมีการจองไว้สองคืนครับ","associationHintTh":"มาจาก reserve = สำรอง/จองไว้ นึกถึงคำว่า 'รีเซิร์ฟ' ที่นั่งไว้ล่วงหน้า"},{"word":"check in","ipa":"/ˌtʃek ˈɪn/","thai":"เช็คอิน (ลงทะเบียนเข้าพัก)","exampleEn":"What time can I check in?","exampleTh":"ผมเช็คอินได้กี่โมงครับ","associationHintTh":"check = ตรวจ + in = เข้า → ตรวจชื่อเพื่อเข้าพัก"},{"word":"passport","ipa":"/ˈpæspɔːrt/","thai":"หนังสือเดินทาง","exampleEn":"May I see your passport, please?","exampleTh":"ขอดูหนังสือเดินทางหน่อยได้ไหมครับ","associationHintTh":"pass (ผ่าน) + port (ท่า/ด่าน) → เอกสารสำหรับผ่านด่านตรวจ"},{"word":"breakfast","ipa":"/ˈbrekfəst/","thai":"อาหารเช้า","exampleEn":"Breakfast is served on the second floor.","exampleTh":"อาหารเช้าเสิร์ฟที่ชั้นสองครับ","associationHintTh":"break (หยุด) + fast (อดอาหาร) → มื้อแรกที่เลิกอดข้ามคืน"},{"word":"included","ipa":"/ɪnˈkluːdɪd/","thai":"รวมอยู่แล้ว (ในราคา)","exampleEn":"Is Wi-Fi included in the price?","exampleTh":"ราคานี้รวมค่าไวไฟด้วยไหมครับ","associationHintTh":"in (เข้า) + clude → รวมเข้าไปในราคาแล้ว ไม่ต้องจ่ายเพิ่ม"}],"examples":[{"en":"Hi, I have a reservation under the name Somchai.","th":"สวัสดีครับ ผมมีการจองในชื่อสมชายครับ"},{"en":"Here is my passport.","th":"นี่หนังสือเดินทางของผมครับ"},{"en":"What time is breakfast?","th":"อาหารเช้าเริ่มกี่โมงครับ"},{"en":"Is breakfast included in the price?","th":"ราคานี้รวมอาหารเช้าด้วยไหมครับ"},{"en":"What is the Wi-Fi password?","th":"รหัสไวไฟคืออะไรครับ"},{"en":"What time is checkout?","th":"เช็คเอาท์กี่โมงครับ"},{"en":"Could I check in early?","th":"ขอเช็คอินก่อนเวลาได้ไหมครับ"}],"quiz":[{"questionTh":"จะบอกพนักงานว่าคุณมีการจองในชื่อ 'สมชาย' ควรพูดว่าอย่างไร?","choices":["I have a reservation under the name Somchai.","I want to buy a room now.","Where is my passport?","Breakfast is very good."],"answerIndex":0,"explainTh":"ใช้ 'I have a reservation under the name ...' เพื่อแจ้งว่ามีการจองไว้ในชื่อนี้ ข้ออื่นไม่เกี่ยวกับการยืนยันการจอง"},{"questionTh":"อยากถามว่าราคานี้รวมอาหารเช้าหรือเปล่า ควรพูดว่าอย่างไร?","choices":["Is the room noisy?","Is breakfast included?","Can I have a towel?","What time is checkout?"],"answerIndex":1,"explainTh":"'Is breakfast included?' แปลว่า 'รวมอาหารเช้าไหม' ตรงกับสิ่งที่ต้องการถาม"},{"questionTh":"พนักงานพูดว่า 'Checkout is at noon.' หมายความว่าอะไร?","choices":["เช็คเอาท์ตอนเที่ยงคืน","อาหารเช้าเสิร์ฟตอนเที่ยง","เช็คเอาท์ตอนเที่ยงวัน","ต้องออกจากห้องตอนหกโมงเช้า"],"answerIndex":2,"explainTh":"noon = เที่ยงวัน ดังนั้น 'Checkout is at noon' คือต้องคืนห้องตอนเที่ยงวัน (ไม่ใช่เที่ยงคืน = midnight)"},{"questionTh":"อยากถามรหัสไวไฟของโรงแรม ควรพูดว่าอย่างไร?","choices":["The room is too noisy.","I need an extra blanket.","Where is the swimming pool?","What is the Wi-Fi password?"],"answerIndex":3,"explainTh":"'What is the Wi-Fi password?' คือการถามรหัสไวไฟ ข้ออื่นเป็นการบ่นเรื่องเสียง ขอผ้าห่ม หรือถามหาสระว่ายน้ำ"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ขอของใช้เพิ่มและฝากกระเป๋า$q$, $q${"listen":{"audioText":"Excuse me, could I have two extra towels, please? (hear) Of course, I'll send them to your room right away. Thank you. Also, can I leave my luggage here after I check out? (hear) Yes, we can store your bags until this evening. Just keep this tag.","thaiExplain":"ถ้าต้องการของใช้เพิ่ม เช่น ผ้าเช็ดตัวหรือผ้าห่ม ให้ขึ้นต้นอย่างสุภาพด้วย 'Could I have...' และถ้าเช็คเอาท์แล้วแต่ยังไม่ถึงเวลาเดินทาง สามารถขอฝากกระเป๋าไว้ที่โรงแรมได้ พนักงานจะให้ป้าย(tag)ไว้รับของคืน"},"vocab":[{"word":"towel","ipa":"/ˈtaʊəl/","thai":"ผ้าเช็ดตัว","exampleEn":"Could I have an extra towel, please?","exampleTh":"ขอผ้าเช็ดตัวเพิ่มอีกผืนได้ไหมครับ","associationHintTh":"อ่านว่า 'ทาว-เอิล' นึกถึงผ้าขนหนูผืนใหญ่ในห้องน้ำ"},{"word":"blanket","ipa":"/ˈblæŋkɪt/","thai":"ผ้าห่ม","exampleEn":"The room is cold. Can I get a blanket?","exampleTh":"ห้องหนาว ขอผ้าห่มได้ไหมครับ","associationHintTh":"อ่านว่า 'แบลง-เก็ต' ผ้าผืนหนาไว้ห่มกันหนาว"},{"word":"extra","ipa":"/ˈekstrə/","thai":"เพิ่ม / พิเศษ","exampleEn":"I need an extra pillow.","exampleTh":"ผมขอหมอนเพิ่มอีกใบครับ","associationHintTh":"'เอ็กซ์ตร้า' = ของพิเศษที่เพิ่มมา เหมือนไซส์ extra ที่ใหญ่กว่าปกติ"},{"word":"luggage","ipa":"/ˈlʌɡɪdʒ/","thai":"กระเป๋าเดินทาง (สัมภาระ)","exampleEn":"Where can I leave my luggage?","exampleTh":"ผมฝากกระเป๋าเดินทางได้ที่ไหนครับ","associationHintTh":"อ่านว่า 'ลัก-กิจ' นึกถึงกระเป๋าใบใหญ่ที่ต้องยกหนักๆ"},{"word":"store","ipa":"/stɔːr/","thai":"เก็บ / ฝาก (เก็บของไว้ให้)","exampleEn":"Can you store my bags until 5 p.m.?","exampleTh":"เก็บกระเป๋าให้ถึงห้าโมงเย็นได้ไหมครับ","associationHintTh":"store = ร้าน/โกดังเก็บของ → ในที่นี้แปลว่า 'เก็บของไว้ให้'"}],"examples":[{"en":"Could I have an extra towel, please?","th":"ขอผ้าเช็ดตัวเพิ่มอีกผืนได้ไหมครับ"},{"en":"Can I get another blanket?","th":"ขอผ้าห่มเพิ่มอีกผืนได้ไหมครับ"},{"en":"Do you have a hair dryer I can use?","th":"มีไดร์เป่าผมให้ใช้ไหมครับ"},{"en":"Can I leave my luggage here after checkout?","th":"ขอฝากกระเป๋าไว้หลังเช็คเอาท์ได้ไหมครับ"},{"en":"What time can I pick up my bags?","th":"ผมมารับกระเป๋าได้กี่โมงครับ"},{"en":"Could you send some drinking water to my room?","th":"ขอน้ำดื่มส่งมาที่ห้องหน่อยได้ไหมครับ"}],"quiz":[{"questionTh":"อยากขอผ้าเช็ดตัวเพิ่มอย่างสุภาพ ควรพูดว่าอย่างไร?","choices":["The Wi-Fi is not working.","Could I have an extra towel, please?","Checkout is at noon.","I have a reservation."],"answerIndex":1,"explainTh":"'Could I have an extra towel, please?' เป็นการขอของเพิ่มอย่างสุภาพ extra = เพิ่ม, towel = ผ้าเช็ดตัว"},{"questionTh":"เช็คเอาท์แล้วแต่ยังไม่ถึงเวลาเดินทาง อยากฝากกระเป๋า ควรพูดว่าอย่างไร?","choices":["Can I pay by card?","The key card doesn't work.","Is breakfast included?","Can I leave my luggage here until 3 p.m.?"],"answerIndex":3,"explainTh":"'Can I leave my luggage here until 3 p.m.?' คือการขอฝากกระเป๋าไว้จนถึงบ่ายสามโมง ข้ออื่นเป็นเรื่องจ่ายเงิน คีย์การ์ด และอาหารเช้า"},{"questionTh":"พนักงานพูดว่า 'We can store your bags until this evening.' แปลว่าอะไร?","choices":["เก็บกระเป๋าให้ไม่ได้","กระเป๋าของคุณหาย","เราเก็บกระเป๋าให้ได้จนถึงเย็นนี้","ต้องจ่ายค่าเก็บกระเป๋าเพิ่ม"],"answerIndex":2,"explainTh":"store your bags = เก็บกระเป๋าให้, until this evening = จนถึงเย็นนี้ จึงแปลว่าเก็บให้ได้จนถึงเย็น"},{"questionTh":"วลี 'an extra pillow' หมายถึงอะไร?","choices":["หมอนเพิ่มอีกใบ","หมอนใบเดิม","ไม่มีหมอน","หมอนราคาแพง"],"answerIndex":0,"explainTh":"extra = เพิ่ม/อีก, pillow = หมอน จึงแปลว่า 'หมอนเพิ่มอีกใบ'"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$แจ้งปัญหาห้อง (แอร์/เสียงดัง/คีย์การ์ด)$q$, $q${"listen":{"audioText":"Hello, front desk? The air conditioner in room 305 isn't working. (hear) I'm so sorry about that. I'll send someone to check it right now. Thank you. Also, the room next door is very noisy. (hear) I understand. If you like, we can move you to another room.","thaiExplain":"เมื่อห้องมีปัญหา เช่น แอร์เสีย เสียงดัง หรือคีย์การ์ดใช้ไม่ได้ ให้โทรหรือแจ้งพนักงานที่เคาน์เตอร์ บอกหมายเลขห้องและปัญหาให้ชัดเจน แล้วขอให้ส่งคนมาซ่อมหรือขอย้ายห้อง"},"vocab":[{"word":"air conditioner","ipa":"/ˈer kənˌdɪʃənər/","thai":"เครื่องปรับอากาศ (แอร์)","exampleEn":"The air conditioner is too cold.","exampleTh":"แอร์เย็นเกินไปครับ","associationHintTh":"air = อากาศ + condition = ปรับสภาพ → เครื่องปรับสภาพอากาศ"},{"word":"broken","ipa":"/ˈbroʊkən/","thai":"เสีย / พัง","exampleEn":"The shower is broken.","exampleTh":"ฝักบัวเสียครับ","associationHintTh":"มาจาก break = แตก/พัง; broken = ถูกทำให้พังไปแล้ว"},{"word":"noisy","ipa":"/ˈnɔɪzi/","thai":"เสียงดัง","exampleEn":"The street is very noisy at night.","exampleTh":"ถนนเสียงดังมากตอนกลางคืน","associationHintTh":"noise = เสียงรบกวน + -y → 'เต็มไปด้วยเสียง' = เสียงดัง"},{"word":"key card","ipa":"/ˈkiː kɑːrd/","thai":"คีย์การ์ด (บัตรเปิดประตูห้อง)","exampleEn":"My key card doesn't work.","exampleTh":"คีย์การ์ดของผมใช้ไม่ได้ครับ","associationHintTh":"key = กุญแจ + card = บัตร → บัตรที่ใช้แทนกุญแจ"},{"word":"work","ipa":"/wɜːrk/","thai":"ทำงาน / ใช้งานได้","exampleEn":"The TV doesn't work.","exampleTh":"ทีวีใช้ไม่ได้ครับ","associationHintTh":"work ไม่ได้แปลว่า 'ทำงาน' อย่างเดียว ของที่ใช้งานได้ก็ใช้ work เช่นกัน"}],"examples":[{"en":"The air conditioner isn't working.","th":"แอร์ไม่ทำงานครับ"},{"en":"The room is too hot.","th":"ห้องร้อนเกินไปครับ"},{"en":"The room next door is very noisy.","th":"ห้องข้างๆเสียงดังมากครับ"},{"en":"My key card doesn't work.","th":"คีย์การ์ดของผมใช้ไม่ได้ครับ"},{"en":"The TV is broken.","th":"ทีวีเสียครับ"},{"en":"Could you send someone to fix it?","th":"ช่วยส่งคนมาซ่อมหน่อยได้ไหมครับ"},{"en":"Could I change to another room?","th":"ขอย้ายไปห้องอื่นได้ไหมครับ"}],"quiz":[{"questionTh":"แอร์ในห้องเสีย จะแจ้งพนักงานว่าอย่างไร?","choices":["Breakfast is included.","I have a reservation.","The air conditioner isn't working.","Can I have the bill?"],"answerIndex":2,"explainTh":"'The air conditioner isn't working.' = แอร์ไม่ทำงาน/เสีย ตรงกับการแจ้งปัญหา ข้ออื่นเป็นเรื่องอาหารเช้า การจอง และบิล"},{"questionTh":"ห้องข้างๆเสียงดังมากจนนอนไม่ได้ ควรพูดว่าอย่างไร?","choices":["The room next door is very noisy. Could you help?","The towel is very clean.","I want to check in now.","Where is breakfast served?"],"answerIndex":0,"explainTh":"noisy = เสียงดัง จึงเลือกประโยคที่บอกว่าห้องข้างๆเสียงดังและขอความช่วยเหลือ"},{"questionTh":"คีย์การ์ดเปิดประตูห้องไม่ได้ ควรพูดว่าอย่างไร?","choices":["The Wi-Fi is very fast.","I need a receipt.","Breakfast is at seven.","My key card doesn't work."],"answerIndex":3,"explainTh":"'My key card doesn't work.' = คีย์การ์ดใช้ไม่ได้ ตรงกับปัญหาที่เกิดขึ้น"},{"questionTh":"คำว่า 'broken' หมายถึงอะไร?","choices":["สะอาด","เสีย / พัง","ใหม่","ใหญ่"],"answerIndex":1,"explainTh":"broken แปลว่า เสีย/พัง ใช้บอกว่าของในห้องใช้งานไม่ได้ เช่น The shower is broken."}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$เช็คเอาท์ จ่ายบิล และ Airbnb เช็คอินเอง$q$, $q${"listen":{"audioText":"Good morning, I'd like to check out. Room 305. (hear) Of course. Here is your bill. How would you like to pay? By credit card, please. Could I have a receipt? (hear) Certainly, here's your receipt. Thank you for staying with us.","thaiExplain":"ตอนเช็คเอาท์ ให้ขอบิลมาตรวจ จ่ายเงิน แล้วขอใบเสร็จ ส่วนที่พักแบบ Airbnb มักให้เช็คอินเอง (self check-in) โดยเจ้าของจะส่งรหัสเปิดประตู (door code) มาให้ทางข้อความ"},"vocab":[{"word":"check out","ipa":"/ˌtʃek ˈaʊt/","thai":"เช็คเอาท์ (คืนห้อง/ออกจากที่พัก)","exampleEn":"I'd like to check out now.","exampleTh":"ผมขอเช็คเอาท์ตอนนี้ครับ","associationHintTh":"check = ตรวจ + out = ออก → ตรวจออกจากห้อง (ตรงข้ามกับ check in)"},{"word":"bill","ipa":"/bɪl/","thai":"บิล / ใบเรียกเก็บเงิน","exampleEn":"Could I have the bill, please?","exampleTh":"ขอบิลหน่อยครับ","associationHintTh":"'บิล' เป็นคำที่คนไทยใช้ทับศัพท์อยู่แล้ว เหมือนตอน 'เก็บบิล' ที่ร้านอาหาร"},{"word":"receipt","ipa":"/rɪˈsiːt/","thai":"ใบเสร็จ","exampleEn":"Can I get a receipt, please?","exampleTh":"ขอใบเสร็จได้ไหมครับ","associationHintTh":"มีตัว p แต่ไม่ออกเสียง อ่านว่า 'ริ-ซีท' (ไม่ใช่ ริ-เซ็ปท์)"},{"word":"self check-in","ipa":"/ˌself ˈtʃek ɪn/","thai":"การเช็คอินด้วยตัวเอง","exampleEn":"This Airbnb has self check-in.","exampleTh":"ที่พัก Airbnb นี้เช็คอินเองได้","associationHintTh":"self = ตัวเอง → เช็คอินเองโดยไม่มีพนักงานคอยรับ"},{"word":"code","ipa":"/koʊd/","thai":"รหัส (เช่น รหัสเปิดประตู)","exampleEn":"The door code is 4521.","exampleTh":"รหัสเปิดประตูคือ 4521","associationHintTh":"'โค้ด' = รหัสลับ นึกถึงรหัสตัวเลขที่กดเปิดประตู"}],"examples":[{"en":"I'd like to check out, please.","th":"ผมขอเช็คเอาท์ครับ"},{"en":"Could I have the bill, please?","th":"ขอบิลหน่อยครับ"},{"en":"Can I pay by credit card?","th":"จ่ายด้วยบัตรเครดิตได้ไหมครับ"},{"en":"What is this charge for?","th":"ค่านี้คิดค่าอะไรครับ"},{"en":"Could I have a receipt, please?","th":"ขอใบเสร็จด้วยครับ"},{"en":"The door code isn't working.","th":"รหัสเปิดประตูใช้ไม่ได้ครับ"},{"en":"How do I check in by myself?","th":"ผมเช็คอินเองยังไงครับ"}],"quiz":[{"questionTh":"อยากเช็คเอาท์คืนห้อง ควรพูดว่าอย่างไร?","choices":["I need an extra blanket.","The air conditioner is broken.","Can I have a towel?","I'd like to check out, please."],"answerIndex":3,"explainTh":"'I'd like to check out, please.' = ผมขอเช็คเอาท์ ข้ออื่นเป็นการขอผ้าห่ม แจ้งแอร์เสีย และขอผ้าเช็ดตัว"},{"questionTh":"จ่ายเงินเสร็จแล้วอยากขอใบเสร็จ ควรพูดว่าอย่างไร?","choices":["Where is the swimming pool?","Could I have a receipt, please?","The room is very noisy.","Is breakfast included?"],"answerIndex":1,"explainTh":"receipt = ใบเสร็จ จึงใช้ 'Could I have a receipt, please?' เพื่อขอใบเสร็จอย่างสุภาพ"},{"questionTh":"เจ้าของ Airbnb ส่งข้อความว่า 'The door code is 4521.' แปลว่าอะไร?","choices":["รหัสเปิดประตูคือ 4521","ห้องอยู่ชั้น 4521","ค่าห้อง 4521 บาท","เช็คเอาท์เวลา 45:21"],"answerIndex":0,"explainTh":"door = ประตู, code = รหัส จึงแปลว่ารหัสสำหรับเปิดประตูคือ 4521 ใช้ตอน self check-in"},{"questionTh":"คำว่า 'self check-in' หมายถึงอะไร?","choices":["มีพนักงานมาเช็คอินให้","เช็คอินไม่ได้","เช็คอินด้วยตัวเอง (ไม่มีพนักงาน)","เช็คอินได้ฟรี"],"answerIndex":2,"explainTh":"self = ตัวเอง จึงแปลว่าเช็คอินด้วยตัวเองโดยไม่มีพนักงานรับ พบบ่อยในที่พักแบบ Airbnb"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$เช็คอินโรงแรมและจัดการเรื่องห้องพัก$q$, $q$You are a friendly front-desk receptionist at a mid-range hotel in London. A Thai traveler has just arrived to check in for a three-night stay. Help them confirm their reservation, answer questions about breakfast, Wi-Fi and checkout, and respond naturally if they ask for extra items or report a problem with their room.$q$, $q$Hotel front-desk receptionist$q$, $q$เช็คอินให้สำเร็จ ยืนยันการจองในชื่อของตัวเอง ถามข้อมูลที่จำเป็น และขอของใช้เพิ่มหรือแจ้งปัญหาห้องได้$q$, $q$["ยืนยันการจองและยื่นหนังสือเดินทางเป็นภาษาอังกฤษได้","ถามเรื่องอาหารเช้า ไวไฟ หรือเวลาเช็คเอาท์ ได้อย่างน้อย 2 อย่าง","ขอของใช้เพิ่ม 1 อย่าง หรือแจ้งปัญหาห้อง 1 อย่างได้สำเร็จ"]$q$::jsonb);
END IF;
END $do$;

-- Unit 11: สั่งอาหารในร้าน
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 11) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 11, $q$สั่งอาหารในร้าน$q$, $q$ขอโต๊ะ อ่านเมนู แจ้งแพ้อาหาร/ฮาลาล สั่งอาหาร และขอบิล$q$, 'A2', $q$🍽️$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$เข้าร้าน ขอโต๊ะ อ่านเมนู และขอคำแนะนำ$q$, $q${"listen":{"audioText":"Hi, do you have a table for two? (hear) Sure, please follow me. Can I see the menu, please? (hear) Here you are. Today's special is grilled salmon. What do you recommend?","thaiExplain":"บทนี้ฝึกตอนเพิ่งเข้าร้าน คุณขอโต๊ะตามจำนวนคน ขอดูเมนู แล้วถามพนักงานว่าแนะนำเมนูไหน ประโยคที่พนักงานพูด (มีคำว่า hear) ให้ฟังจับใจความ ไม่ต้องพูดตาม"},"vocab":[{"word":"table","ipa":"/ˈteɪbl/","thai":"โต๊ะ","exampleEn":"A table for two, please.","exampleTh":"ขอโต๊ะสำหรับสองคนครับ","associationHintTh":"เสียง 'เท-เบิ่ล' นึกภาพเอาของมาวาง (เท) ไว้บนโต๊ะ"},{"word":"menu","ipa":"/ˈmenjuː/","thai":"เมนู รายการอาหาร","exampleEn":"Can I see the menu, please?","exampleTh":"ขอดูเมนูหน่อยได้ไหมครับ","associationHintTh":"'เม-นู' ทับศัพท์ตรงกับคำไทยว่า เมนู เลย"},{"word":"reservation","ipa":"/ˌrezərˈveɪʃn/","thai":"การจองโต๊ะ","exampleEn":"I have a reservation under the name Nok.","exampleTh":"ฉันจองโต๊ะไว้ในชื่อ Nok ค่ะ","associationHintTh":"reserve = จอง; 'รี-เซิร์ฟ' จองโต๊ะไว้ล่วงหน้า"},{"word":"recommend","ipa":"/ˌrekəˈmend/","thai":"แนะนำ (เมนู)","exampleEn":"What do you recommend?","exampleTh":"คุณแนะนำอะไรดีคะ","associationHintTh":"re + command คล้าย 'บอกให้ลอง' = แนะนำ"},{"word":"special","ipa":"/ˈspeʃl/","thai":"เมนูพิเศษประจำวัน","exampleEn":"What is today's special?","exampleTh":"เมนูพิเศษวันนี้คืออะไรครับ","associationHintTh":"'สเปเชี่ยล' = พิเศษ เมนูเด็ดของวันนั้น"}],"examples":[{"en":"A table for two, please.","th":"ขอโต๊ะสำหรับสองคนครับ"},{"en":"Do you have a table by the window?","th":"มีโต๊ะริมหน้าต่างไหมคะ"},{"en":"I have a reservation under the name Nok.","th":"ฉันจองโต๊ะไว้ในชื่อ Nok ค่ะ"},{"en":"Can I see the menu, please?","th":"ขอดูเมนูหน่อยได้ไหมครับ"},{"en":"What do you recommend?","th":"คุณแนะนำอะไรดีคะ"},{"en":"What is today's special?","th":"เมนูพิเศษวันนี้คืออะไรครับ"},{"en":"We're not ready to order yet.","th":"เรายังไม่พร้อมสั่งครับ"}],"quiz":[{"questionTh":"อยากได้โต๊ะสำหรับ 2 คน พูดว่าอะไร?","choices":["A table for two, please.","Two tables, please.","I am two, please.","Table number two, please."],"answerIndex":0,"explainTh":"'A table for two' = ขอโต๊ะสำหรับ 2 คน ข้ออื่นแปลว่า ขอ 2 โต๊ะ / ฉันคือสอง / โต๊ะเบอร์สอง ซึ่งความหมายผิด"},{"questionTh":"พนักงานพูดว่า 'Please follow me.' หมายความว่าอะไร?","choices":["กรุณารอสักครู่","เชิญตามฉันมา","กรุณาจ่ายเงิน","ร้านเต็มแล้ว"],"answerIndex":1,"explainTh":"follow me = ตามฉันมา พนักงานกำลังจะพาไปที่โต๊ะ"},{"questionTh":"อยากขอดูเมนู ควรพูดว่าอะไร?","choices":["Can I see the bill, please?","Can I see the kitchen, please?","Can I see the menu, please?","Can I see the toilet, please?"],"answerIndex":2,"explainTh":"menu = เมนู ส่วน bill = บิล, kitchen = ครัว, toilet = ห้องน้ำ จึงไม่ใช่"},{"questionTh":"อยากถามว่าร้านแนะนำเมนูไหน พูดว่าอะไร?","choices":["Where is the menu?","How much is it?","Can I pay now?","What do you recommend?"],"answerIndex":3,"explainTh":"'What do you recommend?' = คุณแนะนำอะไร ข้ออื่นถามที่อยู่เมนู / ราคา / ขอจ่ายเงิน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$แจ้งแพ้อาหาร ฮาลาล ไม่กินหมู มังสวิรัติ และระดับความเผ็ด$q$, $q${"listen":{"audioText":"Excuse me, I am allergic to peanuts. Does this dish contain nuts? (hear) Let me check with the kitchen for you. No pork, please. Is this halal? (hear) Yes, all our chicken dishes are halal. And not too spicy, please.","thaiExplain":"บทนี้สำคัญมากด้านความปลอดภัย ถ้าคุณแพ้อาหาร (เช่น ถั่ว อาหารทะเล) การกินผิดอาจทำให้แพ้รุนแรง ช็อก หรืออันตรายถึงชีวิตได้ จึงต้องพูดให้ชัดว่า 'I am allergic to...' และถามยืนยันทุกครั้งว่า 'Does this contain...?' ส่วนเรื่องฮาลาล ไม่กินหมู หรือมังสวิรัติ ให้บอกตรงๆ และถามยืนยันก่อนสั่งเสมอ อย่าเดาเอง"},"vocab":[{"word":"allergic","ipa":"/əˈlɜːrdʒɪk/","thai":"แพ้ (อาหาร)","exampleEn":"I am allergic to peanuts.","exampleTh":"ฉันแพ้ถั่วลิสงค่ะ","associationHintTh":"'อะ-เลอ-จิก' คล้ายคำว่า 'อัลเลอร์จี' = ภูมิแพ้"},{"word":"peanut","ipa":"/ˈpiːnʌt/","thai":"ถั่วลิสง","exampleEn":"Does this sauce have peanuts?","exampleTh":"ซอสนี้มีถั่วลิสงไหมคะ","associationHintTh":"pea (เม็ดกลมๆ) + nut (ถั่ว) = ถั่วลิสง"},{"word":"halal","ipa":"/həˈlɑːl/","thai":"ฮาลาล (อาหารตามหลักอิสลาม)","exampleEn":"Is this halal?","exampleTh":"อันนี้ฮาลาลไหมครับ","associationHintTh":"'ฮา-ลาล' ทับศัพท์ตรงกับคำว่า ฮาลาล"},{"word":"vegetarian","ipa":"/ˌvedʒəˈteəriən/","thai":"มังสวิรัติ (ไม่กินเนื้อสัตว์)","exampleEn":"I am vegetarian.","exampleTh":"ฉันกินมังสวิรัติค่ะ","associationHintTh":"veggie = ผัก คนกิน veggie เป็นหลัก = มังสวิรัติ"},{"word":"shellfish","ipa":"/ˈʃelfɪʃ/","thai":"สัตว์น้ำมีเปลือก (กุ้ง หอย ปู)","exampleEn":"I can't eat shellfish.","exampleTh":"ฉันกินกุ้งหอยปูไม่ได้ค่ะ","associationHintTh":"shell (เปลือก) + fish (สัตว์น้ำ) = สัตว์น้ำมีเปลือก"}],"examples":[{"en":"I am allergic to peanuts.","th":"ฉันแพ้ถั่วลิสงค่ะ"},{"en":"I am allergic to seafood.","th":"ฉันแพ้อาหารทะเลครับ"},{"en":"No pork, please.","th":"ไม่ใส่หมูนะคะ"},{"en":"Is this halal?","th":"อันนี้ฮาลาลไหมครับ"},{"en":"I am vegetarian.","th":"ฉันกินมังสวิรัติค่ะ"},{"en":"Does this contain nuts or shellfish?","th":"อันนี้มีถั่วหรืออาหารทะเลไหมคะ"},{"en":"Not too spicy, please.","th":"ขอไม่เผ็ดมากนะครับ"}],"quiz":[{"questionTh":"จะบอกว่า 'ฉันแพ้ถั่วลิสง' พูดว่าอะไร? (สำคัญมากเรื่องความปลอดภัย)","choices":["I like peanuts.","I am allergic to peanuts.","I want peanuts.","I cook peanuts."],"answerIndex":1,"explainTh":"'I am allergic to peanuts.' = ฉันแพ้ถั่วลิสง ข้ออื่นแปลว่า ชอบ/อยากได้/ทำถั่ว ซึ่งอันตรายเพราะพนักงานจะเข้าใจผิดว่าคุณอยากกิน"},{"questionTh":"จะถามว่าอาหารนี้ฮาลาลไหม พูดว่าอะไร?","choices":["Is this halal?","Is this spicy?","Is this cheap?","Is this hot?"],"answerIndex":0,"explainTh":"halal = ฮาลาล ส่วน spicy = เผ็ด, cheap = ถูก, hot = ร้อน/เผ็ด จึงไม่ใช่"},{"questionTh":"จะบอกว่า 'ไม่ใส่หมู' พูดว่าอะไร?","choices":["More pork, please.","I love pork.","No pork, please.","Pork is good."],"answerIndex":2,"explainTh":"'No pork, please.' = ไม่ใส่หมู ข้ออื่นแปลว่า ขอหมูเพิ่ม/ชอบหมู/หมูอร่อย ซึ่งตรงข้ามกับที่ต้องการ"},{"questionTh":"จะบอกว่าขอไม่เผ็ดมาก พูดว่าอะไร?","choices":["Very spicy, please.","More chili, please.","I want it hot.","Not too spicy, please."],"answerIndex":3,"explainTh":"'Not too spicy, please.' = ขอไม่เผ็ดมาก ข้ออื่นแปลว่า เผ็ดมากๆ / ขอพริกเพิ่ม / เอาแบบเผ็ด"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$สั่งอาหาร ขอน้ำ/ของเพิ่ม$q$, $q${"listen":{"audioText":"(hear) Are you ready to order? Yes. I'll have the green curry with rice. Can I get a glass of water, please? (hear) Still or sparkling? Still water, please. And some more napkins.","thaiExplain":"บทนี้ฝึกสั่งอาหารด้วยประโยค 'I'll have...' และขอของเพิ่ม เช่น น้ำ ข้าว กระดาษเช็ดปาก เวลาขอน้ำ ฝรั่งมักถามว่าเอาน้ำเปล่าธรรมดา (still) หรือน้ำอัดลม (sparkling) ให้ตอบให้ชัด"},"vocab":[{"word":"order","ipa":"/ˈɔːrdər/","thai":"สั่ง (อาหาร)","exampleEn":"Are you ready to order?","exampleTh":"พร้อมสั่งหรือยังคะ","associationHintTh":"'ออร์เดอร์' = สั่งของ เหมือนสั่งออเดอร์สินค้า"},{"word":"water","ipa":"/ˈwɔːtər/","thai":"น้ำ","exampleEn":"Can I get a glass of water, please?","exampleTh":"ขอน้ำหนึ่งแก้วได้ไหมคะ","associationHintTh":"'วอ-เทอร์' = น้ำ คำพื้นฐานที่ต้องรู้"},{"word":"extra","ipa":"/ˈekstrə/","thai":"เพิ่ม/พิเศษ","exampleEn":"Can I get some extra napkins?","exampleTh":"ขอกระดาษเช็ดปากเพิ่มได้ไหมคะ","associationHintTh":"'เอ็กซ์ตร้า' = เพิ่มพิเศษ เหมือนไซส์ extra large"},{"word":"napkin","ipa":"/ˈnæpkɪn/","thai":"กระดาษเช็ดปาก","exampleEn":"Can we have more napkins?","exampleTh":"ขอกระดาษเช็ดปากเพิ่มหน่อยครับ","associationHintTh":"'แน็พ-คิน' กระดาษพับๆ วางข้างจานบนโต๊ะ"},{"word":"rice","ipa":"/raɪs/","thai":"ข้าว","exampleEn":"Can we have some more rice?","exampleTh":"ขอข้าวเพิ่มได้ไหมครับ","associationHintTh":"'ไรซ์' = ข้าว คำพื้นฐานสำหรับคนไทย"}],"examples":[{"en":"I'll have the green curry, please.","th":"ขอแกงเขียวหวานครับ"},{"en":"Can I get a glass of water, please?","th":"ขอน้ำหนึ่งแก้วได้ไหมคะ"},{"en":"Can we have some more rice?","th":"ขอข้าวเพิ่มได้ไหมครับ"},{"en":"Can I get some extra napkins?","th":"ขอกระดาษเช็ดปากเพิ่มได้ไหมคะ"},{"en":"I'll have the same.","th":"ฉันเอาเหมือนกันค่ะ"},{"en":"Can I have the chicken instead of beef?","th":"ขอเป็นไก่แทนเนื้อได้ไหมคะ"},{"en":"That's all, thank you.","th":"เท่านี้ครับ ขอบคุณ"}],"quiz":[{"questionTh":"พนักงานถามว่า 'Are you ready to order?' หมายความว่าอะไร?","choices":["คุณจ่ายเงินหรือยัง","คุณพร้อมสั่งอาหารหรือยัง","คุณจองโต๊ะหรือยัง","คุณอิ่มหรือยัง"],"answerIndex":1,"explainTh":"order = สั่งอาหาร 'ready to order' = พร้อมสั่งหรือยัง"},{"questionTh":"อยากขอน้ำหนึ่งแก้ว พูดว่าอะไร?","choices":["Can I get a glass of water, please?","Can I get a menu, please?","Can I get the bill, please?","Can I get a table, please?"],"answerIndex":0,"explainTh":"a glass of water = น้ำหนึ่งแก้ว ข้ออื่นคือขอเมนู/บิล/โต๊ะ"},{"questionTh":"อยากขอข้าวเพิ่ม พูดว่าอะไร?","choices":["No rice, please.","Take the rice away.","Can we have some more rice?","The rice is cold."],"answerIndex":2,"explainTh":"'some more rice' = ข้าวเพิ่ม ข้ออื่นแปลว่า ไม่เอาข้าว / เอาข้าวออกไป / ข้าวเย็นแล้ว"},{"questionTh":"จะสั่งว่า 'ขอแกงเขียวหวาน' พูดว่าอะไร?","choices":["How much is the green curry?","Where is the green curry?","Is the green curry spicy?","I'll have the green curry, please."],"answerIndex":3,"explainTh":"'I'll have...' เป็นวิธีสั่งอาหารที่สุภาพและใช้บ่อย ข้ออื่นเป็นการถามราคา/ที่อยู่/ความเผ็ด ไม่ใช่การสั่ง"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$ขอบิล จ่ายเงิน ทิป และร้องเรียนอาหารผิด/เย็น$q$, $q${"listen":{"audioText":"Excuse me, this is not what I ordered. (hear) I'm so sorry. I'll bring the right dish right away. Can we have the bill, please? (hear) Sure. Do you pay by cash or card? By card, please. Can I leave the tip on the card?","thaiExplain":"บทนี้ฝึกตอนจบมื้อ คือขอบิล จ่ายเงิน (สด/บัตร) และเรื่องทิป และฝึกร้องเรียนอย่างสุภาพเมื่ออาหารผิดหรือเย็นชืด ใช้คำนำสุภาพ 'Excuse me' แล้วบอกปัญหาตรงๆ พนักงานจะช่วยแก้ให้"},"vocab":[{"word":"bill","ipa":"/bɪl/","thai":"บิล/ใบเก็บเงิน (อเมริกาใช้ check)","exampleEn":"Can we have the bill, please?","exampleTh":"ขอบิลด้วยครับ","associationHintTh":"'บิล' ทับศัพท์ตรงตัว = ใบเรียกเก็บเงิน"},{"word":"tip","ipa":"/tɪp/","thai":"ทิป (เงินให้พนักงาน)","exampleEn":"Is the tip included?","exampleTh":"รวมค่าทิปแล้วหรือยังคะ","associationHintTh":"'ทิป' ทับศัพท์ = เงินทิปที่ให้พนักงานบริการ"},{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"Can I pay in cash?","exampleTh":"จ่ายเงินสดได้ไหมครับ","associationHintTh":"'แคช' นึกถึงแคชเชียร์ที่รับเงินสด"},{"word":"card","ipa":"/kɑːrd/","thai":"บัตร (เครดิต/เดบิต)","exampleEn":"Can I pay by card?","exampleTh":"จ่ายด้วยบัตรได้ไหมคะ","associationHintTh":"'การ์ด' = บัตร เช่น บัตรเครดิต"},{"word":"cold","ipa":"/koʊld/","thai":"เย็น (อาหารเย็นชืด)","exampleEn":"My soup is cold.","exampleTh":"ซุปของฉันเย็นแล้วค่ะ","associationHintTh":"'โคลด์' = เย็น ตรงข้ามกับ hot (ร้อน)"}],"examples":[{"en":"Can we have the bill, please?","th":"ขอบิลด้วยครับ"},{"en":"Can I pay by card?","th":"จ่ายด้วยบัตรได้ไหมคะ"},{"en":"Do you accept credit cards?","th":"รับบัตรเครดิตไหมครับ"},{"en":"Keep the change.","th":"ไม่ต้องทอนครับ (ให้เป็นทิป)"},{"en":"Excuse me, this is not what I ordered.","th":"ขอโทษครับ อันนี้ไม่ใช่ที่ผมสั่ง"},{"en":"My food is cold. Can you warm it up?","th":"อาหารเย็นแล้วค่ะ อุ่นให้หน่อยได้ไหม"},{"en":"I think there is a mistake on the bill.","th":"บิลน่าจะมีอะไรผิดนะคะ"}],"quiz":[{"questionTh":"อยากขอบิล พูดว่าอะไร?","choices":["Can we have the bill, please?","Can we have the menu, please?","Can we have a table, please?","Can we have more water, please?"],"answerIndex":0,"explainTh":"bill = บิล/ใบเก็บเงิน ข้ออื่นคือขอเมนู/โต๊ะ/น้ำเพิ่ม"},{"questionTh":"จะบอกว่า 'อาหารนี้ไม่ใช่ที่ผมสั่ง' พูดว่าอะไร?","choices":["This is delicious.","This is not what I ordered.","This is my favorite.","This is enough."],"answerIndex":1,"explainTh":"'not what I ordered' = ไม่ใช่ที่สั่ง ข้ออื่นแปลว่า อร่อย / ของโปรด / พอแล้ว"},{"questionTh":"พนักงานถามว่า 'Cash or card?' หมายความว่าอะไร?","choices":["กินที่ร้านหรือกลับบ้าน","เผ็ดหรือไม่เผ็ด","จ่ายเงินสดหรือบัตร","น้ำเปล่าหรือน้ำอัดลม"],"answerIndex":2,"explainTh":"cash = เงินสด, card = บัตร พนักงานถามวิธีจ่ายเงิน"},{"questionTh":"อาหารเย็นชืด อยากให้อุ่นให้ พูดว่าอะไร?","choices":["My food is too spicy.","My food is delicious.","My food is expensive.","My food is cold. Can you warm it up?"],"answerIndex":3,"explainTh":"cold = เย็น, warm it up = อุ่นให้ร้อน ข้ออื่นบอกว่าเผ็ดไป / อร่อย / แพง ซึ่งไม่ตรงปัญหา"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$มื้อค่ำที่ร้านอาหารต่างประเทศ$q$, $q$You are a friendly waiter at a busy restaurant abroad on a weekend evening. Greet the customer at the door, show them to a table, present the menu, and answer questions about the food, allergies, and halal options. Take their order, bring water and extras when asked, then bring the bill and handle payment and any complaints politely.$q$, $q$Restaurant waiter$q$, $q$ผู้เรียนต้องเข้าร้าน ขอโต๊ะ ขอดูเมนูและคำแนะนำ แจ้งข้อจำกัดด้านอาหาร (แพ้อาหาร/ไม่กินหมู/ฮาลาล) สั่งอาหารและขอน้ำ/ของเพิ่ม แล้วขอบิลจ่ายเงินให้สำเร็จเป็นภาษาอังกฤษ$q$, $q$["ขอโต๊ะ ขอดูเมนู และถามคำแนะนำเมนูเป็นภาษาอังกฤษได้","แจ้งอาหารที่แพ้หรือข้อจำกัด (เช่น ไม่กินหมู/ฮาลาล/ไม่เผ็ดมาก) ได้ชัดเจนและถามยืนยันได้","สั่งอาหาร ขอของเพิ่ม แล้วขอบิลและจ่ายเงิน (สด/บัตร) ได้จนจบ"]$q$::jsonb);
END IF;
END $do$;

-- Unit 12: ช้อปปิ้งและเงิน
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 12) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 12, $q$ช้อปปิ้งและเงิน$q$, $q$ถามราคา ลองไซซ์ ต่อราคา จ่ายเงิน และคืน/เปลี่ยนสินค้า$q$, 'A2', $q$🛍️$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ร้านสะดวกซื้อและซูเปอร์มาร์เก็ต$q$, $q${"listen":{"audioText":"Excuse me, where can I find the bottled water? It's in aisle three, next to the snacks. (hear) Thank you. Do you need a bag? (hear) Yes, one bag, please. That's four dollars fifty. Here's your receipt. (hear)","thaiExplain":"ในร้านสะดวกซื้อและซูเปอร์มาร์เก็ต เราต้องถามหาสินค้าและถามว่าของอยู่ทางเดิน (aisle) ไหน. ตอนจ่ายเงินพนักงานมักถามว่ารับถุงไหมและบอกราคา. ฟังคำที่พนักงานพูด (hear) ให้ทันแล้วตอบสั้นๆ ได้."},"vocab":[{"word":"aisle","ipa":"/aɪl/","thai":"ช่องทางเดินระหว่างชั้นวางของ","exampleEn":"The milk is in aisle five.","exampleTh":"นมอยู่ที่ทางเดินหมายเลขห้า","associationHintTh":"อ่านว่า 'ไอล์' (s กับ l ตัวหลังเงียบ) นึกถึงเดินตามลูกศรในทางเดินซูเปอร์"},{"word":"receipt","ipa":"/rɪˈsiːt/","thai":"ใบเสร็จ","exampleEn":"Can I have a receipt, please?","exampleTh":"ขอใบเสร็จด้วยได้ไหมครับ","associationHintTh":"อ่านว่า 'รี-ซีท' (p เงียบ) — 'รีบซีท (เก็บ) ใบเสร็จ' ไว้เคลม"},{"word":"cashier","ipa":"/kæˈʃɪr/","thai":"พนักงานเก็บเงิน / แคชเชียร์","exampleEn":"Please pay at the cashier.","exampleTh":"กรุณาจ่ายเงินที่แคชเชียร์","associationHintTh":"cash (เงินสด) + ier (คนทำ) = 'แคช-เชียร์' คนรับเงิน"},{"word":"grocery","ipa":"/ˈɡroʊsəri/","thai":"ของชำ / ของกินของใช้ในบ้าน","exampleEn":"I need to buy some groceries.","exampleTh":"ฉันต้องซื้อของกินของใช้หน่อย","associationHintTh":"'โกรเซอรี' นึกถึงถุงของชำที่ 'โกร่ง' ใส่ของกิน"},{"word":"bag","ipa":"/bæɡ/","thai":"ถุง","exampleEn":"Do you need a bag?","exampleTh":"รับถุงไหมคะ","associationHintTh":"'แบ็ก' เสียงคล้ายคำไทย 'แบก' ของใส่ถุงไว้แบก"}],"examples":[{"en":"Where can I find the milk?","th":"นมอยู่ตรงไหนครับ/คะ"},{"en":"It's in aisle five, next to the drinks.","th":"อยู่ที่ทางเดินหมายเลขห้า ข้างๆ เครื่องดื่ม"},{"en":"Do you need a bag?","th":"รับถุงไหมคะ"},{"en":"Yes, one bag, please.","th":"รับค่ะ ขอหนึ่งถุง"},{"en":"How much is this bottle of water?","th":"น้ำขวดนี้ราคาเท่าไหร่"},{"en":"Is this on sale?","th":"อันนี้ลดราคาอยู่ไหม"},{"en":"Can I have a receipt, please?","th":"ขอใบเสร็จด้วยได้ไหมครับ"}],"quiz":[{"questionTh":"ถ้าอยากถามว่านมอยู่ตรงไหนในซูเปอร์ ควรพูดว่าอะไร","choices":["How much is the milk?","Where can I find the milk?","Do you have a bag?","Can I have a receipt?"],"answerIndex":1,"explainTh":"'Where can I find...?' ใช้ถามตำแหน่งของสินค้า ส่วนข้ออื่นถามราคา ถามถุง และขอใบเสร็จ"},{"questionTh":"คำว่า 'aisle' แปลว่าอะไร","choices":["ใบเสร็จ","ถุงใส่ของ","รถเข็น","ช่องทางเดินระหว่างชั้นวางของ"],"answerIndex":3,"explainTh":"aisle (อ่านว่า 'ไอล์' ตัว s เงียบ) = ช่องทางเดินระหว่างชั้นวางสินค้าในซูเปอร์"},{"questionTh":"พนักงานพูดว่า 'That's four fifty.' ตอนจ่ายเงิน หมายความว่าอะไร","choices":["ราคา 4.50 (สี่ดอลลาร์ห้าสิบเซนต์)","เหลือของ 4 ชิ้น","รออีก 50 นาที","ทางเดินหมายเลข 4"],"answerIndex":0,"explainTh":"ในบริบทจ่ายเงิน 'four fifty' = 4.50 หน่วยเงิน เช่น สี่ดอลลาร์ห้าสิบเซนต์"},{"questionTh":"ถ้าอยากได้ใบเสร็จ ควรพูดว่าอะไร","choices":["Is this on sale?","Do you need a bag?","Can I have a receipt, please?","Where is the cashier?"],"answerIndex":2,"explainTh":"receipt (รี-ซีท) = ใบเสร็จ ขอแบบสุภาพด้วย 'Can I have..., please?'"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ถามหาสินค้า ลองเสื้อผ้า ไซซ์ และสี$q$, $q${"listen":{"audioText":"Hi, can I try this shirt on? Of course. The fitting room is over there. (hear) Do you have it in a bigger size? Yes, we have large. Here you go. (hear) Do you have it in blue? Sorry, we only have black and white. (hear)","thaiExplain":"ในร้านเสื้อผ้า เราจะขอลองเสื้อ ถามไซซ์ที่ใหญ่/เล็กกว่า และถามสีอื่น. บอกได้ว่ามันคับ (tight) หรือหลวม (loose) หรือพอดี. ฟังคำตอบของพนักงาน (hear) ว่ามีของหรือต้องเปลี่ยนไซซ์/สี."},"vocab":[{"word":"size","ipa":"/saɪz/","thai":"ขนาด / ไซซ์","exampleEn":"What size do you need?","exampleTh":"คุณต้องการไซซ์ไหน","associationHintTh":"'ไซซ์' ทับศัพท์ตรงตัว = ขนาดเสื้อผ้า S M L"},{"word":"fitting room","ipa":"/ˈfɪtɪŋ ˌruːm/","thai":"ห้องลองเสื้อผ้า","exampleEn":"Where is the fitting room?","exampleTh":"ห้องลองเสื้ออยู่ตรงไหน","associationHintTh":"fit (พอดี) + room (ห้อง) = ห้องลองว่าใส่พอดีไหม"},{"word":"try on","ipa":"/ˈtraɪ ˌɒn/","thai":"ลองสวมใส่","exampleEn":"Can I try this on?","exampleTh":"ขอลองตัวนี้ได้ไหม","associationHintTh":"try (ลอง) + on (สวม) = ลองสวมดูก่อนซื้อ"},{"word":"tight","ipa":"/taɪt/","thai":"คับ / แน่น","exampleEn":"This shirt is too tight.","exampleTh":"เสื้อตัวนี้คับเกินไป","associationHintTh":"'ไทท์' เสียงคล้าย 'ไท (มัด)' แน่นๆ = คับ"},{"word":"loose","ipa":"/luːs/","thai":"หลวม","exampleEn":"These pants are too loose.","exampleTh":"กางเกงตัวนี้หลวมเกินไป","associationHintTh":"'ลูส' เสียงคล้าย 'หลุด' — หลวมจนเกือบหลุด"}],"examples":[{"en":"Can I try this on?","th":"ขอลองตัวนี้ได้ไหมครับ/คะ"},{"en":"Do you have this in a bigger size?","th":"มีไซซ์ใหญ่กว่านี้ไหม"},{"en":"Do you have this in another color?","th":"มีสีอื่นไหม"},{"en":"Where is the fitting room?","th":"ห้องลองเสื้ออยู่ตรงไหน"},{"en":"It's too tight.","th":"มันคับไป"},{"en":"It's too loose.","th":"มันหลวมไป"},{"en":"This one fits perfectly.","th":"ตัวนี้พอดีเลย"}],"quiz":[{"questionTh":"อยากลองเสื้อตัวนี้ ควรพูดว่าอะไร","choices":["Can I try this on?","How much is this?","Do you have a bag?","Where is the receipt?"],"answerIndex":0,"explainTh":"'Can I try this on?' = ขอลองสวมได้ไหม เป็นประโยคมาตรฐานในร้านเสื้อผ้า"},{"questionTh":"คำว่า 'fitting room' คืออะไร","choices":["ห้องน้ำ","ห้องลองเสื้อผ้า","เคาน์เตอร์แคชเชียร์","คลังเก็บสินค้า"],"answerIndex":1,"explainTh":"fitting room = ห้องลองเสื้อผ้า ก่อนตัดสินใจซื้อ"},{"questionTh":"ถ้าเสื้อคับเกินไป จะบอกพนักงานว่าอะไร","choices":["It's too loose.","It fits perfectly.","It's too tight.","It's on sale."],"answerIndex":2,"explainTh":"tight = คับ/แน่น ส่วน loose = หลวม, fits perfectly = พอดี"},{"questionTh":"อยากได้ไซซ์ใหญ่กว่านี้ ควรพูดว่าอะไร","choices":["Do you have a smaller size?","Do you have this in another color?","Can I have a receipt?","Do you have this in a bigger size?"],"answerIndex":3,"explainTh":"bigger size = ไซซ์ใหญ่กว่า ส่วน smaller = เล็กกว่า, another color = สีอื่น"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$จ่ายเงิน บัตร/เงินสด และปัญหาตอนจ่าย$q$, $q${"listen":{"audioText":"Your total is twenty dollars. How would you like to pay? (hear) Can I pay by card? Sorry, your card was declined. (hear) Okay, I'll pay in cash. Here's your change and your receipt. (hear)","thaiExplain":"ตอนจ่ายเงิน พนักงานจะบอกยอดรวม (total) และถามว่าจ่ายด้วยบัตรหรือเงินสด. บางครั้งบัตรรูดไม่ผ่าน (declined) ต้องเปลี่ยนไปจ่ายเงินสด. ฟังให้ทันเรื่องยอดเงินและเงินทอน (change)."},"vocab":[{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"I'll pay in cash.","exampleTh":"ฉันจ่ายเงินสด","associationHintTh":"'แคช' = เงินสด จ่ายสดๆ ไม่ใช้บัตร"},{"word":"card","ipa":"/kɑːrd/","thai":"บัตร (เครดิต/เดบิต)","exampleEn":"Can I pay by card?","exampleTh":"จ่ายด้วยบัตรได้ไหม","associationHintTh":"'การ์ด' ทับศัพท์ตรงตัว = บัตร"},{"word":"change","ipa":"/tʃeɪndʒ/","thai":"เงินทอน","exampleEn":"Here's your change.","exampleTh":"นี่เงินทอนของคุณ","associationHintTh":"change = เปลี่ยน → เงินที่ 'เปลี่ยน' ทอนกลับมาให้เรา"},{"word":"declined","ipa":"/dɪˈklaɪnd/","thai":"(บัตร) ถูกปฏิเสธ / รูดไม่ผ่าน","exampleEn":"Sorry, your card was declined.","exampleTh":"ขอโทษค่ะ บัตรของคุณรูดไม่ผ่าน","associationHintTh":"de- (ปฏิเสธ) → บัตร 'ดีไคลน์' = โดนปฏิเสธ รูดไม่ผ่าน"},{"word":"total","ipa":"/ˈtoʊtl/","thai":"ยอดรวมทั้งหมด","exampleEn":"How much is it in total?","exampleTh":"ทั้งหมดเท่าไหร่","associationHintTh":"'โทเทิล' = ทั้งหมด → ยอดรวมสุทธิที่ต้องจ่าย"}],"examples":[{"en":"How much is it in total?","th":"ทั้งหมดเท่าไหร่ครับ/คะ"},{"en":"Can I pay by card?","th":"จ่ายด้วยบัตรได้ไหม"},{"en":"I'll pay in cash.","th":"ฉันจ่ายเงินสด"},{"en":"Do you accept credit cards?","th":"รับบัตรเครดิตไหม"},{"en":"Sorry, your card was declined.","th":"ขอโทษค่ะ บัตรของคุณรูดไม่ผ่าน"},{"en":"Here's your change.","th":"นี่เงินทอนของคุณ"},{"en":"Can I have the receipt, please?","th":"ขอใบเสร็จด้วยได้ไหม"}],"quiz":[{"questionTh":"อยากจ่ายด้วยบัตร ควรพูดว่าอะไร","choices":["Can I pay by card?","Here's your change.","Where is the fitting room?","It's too tight."],"answerIndex":0,"explainTh":"'Can I pay by card?' = ขอจ่ายด้วยบัตรได้ไหม ส่วนข้ออื่นเป็นคนละเรื่อง"},{"questionTh":"พนักงานพูดว่า 'Your card was declined.' หมายความว่าอะไร","choices":["บัตรของคุณใช้ได้","บัตรของคุณรูดไม่ผ่าน","ได้เงินทอนแล้ว","ต้องเซ็นชื่อ"],"answerIndex":1,"explainTh":"declined = ถูกปฏิเสธ แปลว่าบัตรรูดไม่ผ่าน ต้องลองใหม่หรือจ่ายเงินสด"},{"questionTh":"คำว่า 'change' ในบริบทจ่ายเงิน แปลว่าอะไร","choices":["การเปลี่ยนสินค้า","บัตร","ยอดรวม","เงินทอน"],"answerIndex":3,"explainTh":"ตอนจ่ายเงิน change = เงินทอน เช่น 'Here's your change.' นี่เงินทอนของคุณ"},{"questionTh":"อยากถามยอดรวมทั้งหมดที่ต้องจ่าย ควรพูดว่าอะไร","choices":["Do you have a bag?","Can I try this on?","How much is it in total?","Is this on sale?"],"answerIndex":2,"explainTh":"'in total' = รวมทั้งหมด ใช้ถามยอดสุทธิที่ต้องจ่าย"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$ต่อราคาตลาดนัด และคืน/เปลี่ยนสินค้า$q$, $q${"listen":{"audioText":"How much is this bag? It's five hundred baht. (hear) That's too expensive. Can you give me a discount? Okay, four hundred for you. (hear) Great, I'll take it. Can I return it if there's a problem? Yes, just keep the receipt. (hear)","thaiExplain":"ที่ตลาดนัดเราต่อราคาได้ ใช้ประโยคว่าแพงไป (too expensive) แล้วขอส่วนลด (discount). ถ้าซื้อของแล้วมีปัญหา เราขอคืน (return) หรือเปลี่ยน (exchange) ได้ แต่ควรเก็บใบเสร็จไว้."},"vocab":[{"word":"discount","ipa":"/ˈdɪskaʊnt/","thai":"ส่วนลด","exampleEn":"Can you give me a discount?","exampleTh":"ลดราคาให้หน่อยได้ไหม","associationHintTh":"'ดิสเคาน์ต์' — count (นับ) ลดลง = ส่วนลด"},{"word":"expensive","ipa":"/ɪkˈspɛnsɪv/","thai":"แพง","exampleEn":"That's too expensive.","exampleTh":"แพงเกินไป","associationHintTh":"มีคำว่า expense (ค่าใช้จ่าย) อยู่ = ราคาแพง"},{"word":"cheap","ipa":"/tʃiːp/","thai":"ถูก (ราคา)","exampleEn":"Can you make it cheaper?","exampleTh":"ลดให้ถูกกว่านี้ได้ไหม","associationHintTh":"'ชีพ' เสียงคล้าย 'ชิพ' เล็กๆ ราคาถูก"},{"word":"return","ipa":"/rɪˈtɜːrn/","thai":"คืน (สินค้า)","exampleEn":"I'd like to return this.","exampleTh":"ฉันอยากคืนสินค้าชิ้นนี้","associationHintTh":"re- (กลับ) + turn (หัน) = เอาของหันกลับไปคืน"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","thai":"เปลี่ยน (สินค้า)","exampleEn":"Can I exchange this for a bigger size?","exampleTh":"ขอเปลี่ยนเป็นไซซ์ใหญ่กว่าได้ไหม","associationHintTh":"ex- (ออก) + change (เปลี่ยน) = เอาของออกไปเปลี่ยนอันใหม่"}],"examples":[{"en":"That's too expensive.","th":"แพงเกินไป"},{"en":"Can you give me a discount?","th":"ลดราคาให้หน่อยได้ไหม"},{"en":"Can you make it cheaper?","th":"ลดให้ถูกกว่านี้ได้ไหม"},{"en":"I'd like to return this.","th":"ฉันอยากคืนสินค้าชิ้นนี้"},{"en":"Can I exchange this for a bigger size?","th":"ขอเปลี่ยนเป็นไซซ์ใหญ่กว่าได้ไหม"},{"en":"It doesn't fit.","th":"มันใส่ไม่พอดี"},{"en":"Can I get a refund?","th":"ขอเงินคืนได้ไหม"}],"quiz":[{"questionTh":"อยากขอส่วนลดจากแม่ค้า ควรพูดว่าอะไร","choices":["Can you give me a discount?","Here's your change.","I'll pay in cash.","Where is the milk?"],"answerIndex":0,"explainTh":"'Can you give me a discount?' = ขอส่วนลดได้ไหม เป็นประโยคต่อราคามาตรฐาน"},{"questionTh":"ประโยค 'It's too expensive.' แปลว่าอะไร","choices":["มันถูกมาก","มันแพงเกินไป","มันพอดี","มันหมดแล้ว"],"answerIndex":1,"explainTh":"expensive = แพง, too expensive = แพงเกินไป ใช้เปิดการต่อราคา"},{"questionTh":"อยากเปลี่ยนสินค้าเป็นไซซ์ใหญ่กว่า ควรพูดว่าอะไร","choices":["Can I get a refund?","That's too cheap.","Can I exchange this for a bigger size?","Can I pay by card?"],"answerIndex":2,"explainTh":"exchange = เปลี่ยนสินค้า ส่วน refund = ขอเงินคืน คนละความหมายกัน"},{"questionTh":"อยากคืนสินค้าและขอเงินคืน ควรพูดว่าอะไร","choices":["Can you make it cheaper?","Do you have this in blue?","It fits perfectly.","I'd like to return this and get a refund."],"answerIndex":3,"explainTh":"return = คืนสินค้า, refund = เงินคืน รวมกันคือขอคืนของและรับเงินคืน"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$ซื้อเสื้อผ้าและต่อราคาที่ตลาดต่างประเทศ$q$, $q$You are a friendly clothing vendor at a busy street market abroad. A Thai tourist walks up to your stall to shop for clothes and souvenirs. Help them find items, answer questions about size, color, and price, let them bargain a little, and take their payment.$q$, $q$Market clothing vendor$q$, $q$ถามราคา ลองเสื้อผ้า ขอไซซ์และสีที่ต้องการ ต่อราคาให้ได้ส่วนลด แล้วจ่ายเงินปิดการซื้อให้สำเร็จ$q$, $q$["ถามราคาและถามหาไซซ์/สีที่ต้องการเป็นภาษาอังกฤษได้","ต่อราคาจนได้ส่วนลดอย่างน้อยหนึ่งครั้ง","เลือกวิธีจ่ายเงิน (เงินสดหรือบัตร) และปิดการซื้อได้สำเร็จ"]$q$::jsonb);
END IF;
END $do$;

-- Unit 13: เที่ยวชมและกิจกรรม
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 13) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 13, $q$เที่ยวชมและกิจกรรม$q$, $q$ซื้อตั๋วเข้าชม ขอถ่ายรูป จองทัวร์ และมารยาทในสถานที่$q$, 'A2', $q$🎟️$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ซื้อตั๋วเข้าชมและถามเวลาเปิด-ปิด$q$, $q${"listen":{"audioText":"Hi, two adult tickets, please. How much is it? (hear) That's twenty dollars for two. Here are your tickets. What time do you close today? (hear) We close at six p.m., and the last entry is at five thirty. Great, thank you!","thaiExplain":"สถานการณ์นี้คือการซื้อตั๋วที่ช่องขายตั๋วก่อนเข้าชม บอกจำนวนตั๋วและประเภท (ผู้ใหญ่/เด็ก) ถามราคา แล้วถามเวลาเปิด-ปิด ประโยคที่มี (hear) คือคำพูดของพนักงานที่คุณจะได้ยิน"},"vocab":[{"word":"ticket","ipa":"/ˈtɪkɪt/","thai":"ตั๋ว, บัตรเข้าชม","exampleEn":"Two adult tickets, please.","exampleTh":"ขอตั๋วผู้ใหญ่สองใบครับ/ค่ะ","associationHintTh":"\"ทิก-เก็ต\" นึกถึงเสียง \"ติ๊ก\" ตอนฉีกตั๋วเข้างาน"},{"word":"admission","ipa":"/ədˈmɪʃən/","thai":"ค่าเข้าชม, การเข้าชม","exampleEn":"How much is the admission?","exampleTh":"ค่าเข้าชมเท่าไหร่ครับ/คะ","associationHintTh":"มาจาก \"admit\" = ยอมให้เข้า จึงได้ admission = ค่าที่จ่ายเพื่อเข้า"},{"word":"adult","ipa":"/ˈædʌlt/","thai":"ผู้ใหญ่","exampleEn":"One adult and one child, please.","exampleTh":"ขอผู้ใหญ่หนึ่ง เด็กหนึ่งครับ/ค่ะ","associationHintTh":"\"แอ-ดั้ลท์\" ตรงข้ามกับ child (เด็ก) ราคาตั๋วมักต่างกัน"},{"word":"entrance","ipa":"/ˈentrəns/","thai":"ทางเข้า","exampleEn":"Where is the entrance?","exampleTh":"ทางเข้าอยู่ที่ไหนครับ/คะ","associationHintTh":"มี \"enter\" (เข้า) อยู่ในคำ จึงได้ entrance = ทางเข้า"},{"word":"discount","ipa":"/ˈdɪskaʊnt/","thai":"ส่วนลด","exampleEn":"Is there a discount for students?","exampleTh":"มีส่วนลดสำหรับนักเรียนไหมครับ/คะ","associationHintTh":"\"ดิส-เคาน์ท์\" นึกถึงป้าย SALE ลดราคา"}],"examples":[{"en":"Two adult tickets, please.","th":"ขอตั๋วผู้ใหญ่สองใบครับ/ค่ะ"},{"en":"How much is the admission?","th":"ค่าเข้าชมเท่าไหร่ครับ/คะ"},{"en":"What time do you open?","th":"เปิดกี่โมงครับ/คะ"},{"en":"What time do you close?","th":"ปิดกี่โมงครับ/คะ"},{"en":"Is there a discount for students?","th":"มีส่วนลดสำหรับนักเรียนไหมครับ/คะ"},{"en":"One adult and one child, please.","th":"ขอผู้ใหญ่หนึ่งคน เด็กหนึ่งคนครับ/ค่ะ"},{"en":"Where is the entrance?","th":"ทางเข้าอยู่ที่ไหนครับ/คะ"}],"quiz":[{"questionTh":"พนักงานพูดว่า \"We close at six p.m.\" หมายความว่าอย่างไร?","choices":["ที่นี่เปิดหกโมงเช้า","ที่นี่ปิดหกโมงเย็น","ค่าเข้าหกดอลลาร์","มีที่นั่งหกที่"],"answerIndex":1,"explainTh":"close = ปิด และ six p.m. = หกโมงเย็น ดังนั้นประโยคนี้บอกว่าสถานที่ปิดตอนหกโมงเย็น"},{"questionTh":"ถ้าอยากถามราคาค่าเข้าชม ควรพูดว่าอะไร?","choices":["How much is the admission?","What time is it?","Where is the toilet?","Can you help me?"],"answerIndex":0,"explainTh":"\"How much...?\" ใช้ถามราคา และ admission = ค่าเข้าชม จึงเป็นประโยคถามราคาค่าเข้าที่ถูกต้อง"},{"questionTh":"อยากซื้อตั๋วผู้ใหญ่ 2 ใบ ควรพูดว่าอะไร?","choices":["Two child tickets, please.","I want to close.","Two adult tickets, please.","The entrance is here."],"answerIndex":2,"explainTh":"adult = ผู้ใหญ่, tickets = ตั๋ว จึง \"Two adult tickets, please.\" แปลว่า ขอตั๋วผู้ใหญ่สองใบ ส่วน child คือเด็ก"},{"questionTh":"ถ้าอยากรู้ว่าที่นี่เปิดกี่โมง ควรถามว่าอะไร?","choices":["How much is it?","What is your name?","How many people?","What time do you open?"],"answerIndex":3,"explainTh":"\"What time do you open?\" = เปิดกี่โมง เป็นการถามเวลาเปิดโดยตรง ส่วนตัวเลือกอื่นถามราคา ชื่อ และจำนวนคน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ขอให้ช่วยถ่ายรูป และมารยาทในวัด/กฎ-ข้อห้าม$q$, $q${"listen":{"audioText":"Excuse me, could you take a photo of us, please? (hear) Sure! Say cheese. Thank you! One more, please. (hear) No problem. Here you go. By the way, can I take photos inside the temple? (hear) Yes, but please don't use flash, and please take off your shoes.","thaiExplain":"สถานการณ์นี้คือการขอให้คนแปลกหน้าช่วยถ่ายรูปให้ และถามกฎก่อนเข้าสถานที่ศักดิ์สิทธิ์ เช่น วัดหรือโบสถ์ ควรพูดสุภาพและทำตามกฎ เช่น ห้ามใช้แฟลช ถอดรองเท้า และอยู่เงียบ ๆ ประโยคที่มี (hear) คือสิ่งที่อีกฝ่ายพูดกับคุณ"},"vocab":[{"word":"photo","ipa":"/ˈfoʊtoʊ/","thai":"รูปถ่าย","exampleEn":"Could you take a photo of us?","exampleTh":"ช่วยถ่ายรูปให้เราหน่อยได้ไหมครับ/คะ","associationHintTh":"\"โฟ-โต้\" ทับศัพท์ตรงตัวกับคำไทย \"โฟโต้\""},{"word":"flash","ipa":"/flæʃ/","thai":"แฟลช (แสงวาบจากกล้อง)","exampleEn":"Please don't use flash.","exampleTh":"กรุณาอย่าใช้แฟลชครับ/คะ","associationHintTh":"\"แฟลช\" คือแสงวาบ เหมือนคำไทยที่ยืมมาใช้เลย"},{"word":"shoes","ipa":"/ʃuːz/","thai":"รองเท้า","exampleEn":"Please take off your shoes.","exampleTh":"กรุณาถอดรองเท้าครับ/คะ","associationHintTh":"\"ชูส์\" ลงท้ายเสียง /z/ เพราะรองเท้ามีคู่ (สองข้าง) จึงเป็นพหูพจน์เสมอ"},{"word":"allowed","ipa":"/əˈlaʊd/","thai":"ได้รับอนุญาต, ทำได้","exampleEn":"Photography is not allowed here.","exampleTh":"ที่นี่ห้ามถ่ายรูปครับ/คะ","associationHintTh":"มาจาก \"allow\" (อนุญาต) จึงได้ allowed = ที่อนุญาตให้ทำได้"},{"word":"quiet","ipa":"/ˈkwaɪət/","thai":"เงียบ","exampleEn":"Please be quiet inside the temple.","exampleTh":"กรุณาเงียบขณะอยู่ในวัดครับ/คะ","associationHintTh":"\"ไคว-เอิท\" แปลว่าเงียบ ระวังสับสนกับ quite (/kwaɪt/ = ค่อนข้าง)"}],"examples":[{"en":"Could you take a photo of us, please?","th":"ช่วยถ่ายรูปให้เราหน่อยได้ไหมครับ/คะ"},{"en":"Can I take a photo here?","th":"ถ่ายรูปตรงนี้ได้ไหมครับ/คะ"},{"en":"One more, please.","th":"ขออีกรูปนะครับ/คะ"},{"en":"Please don't use flash.","th":"กรุณาอย่าใช้แฟลชครับ/คะ"},{"en":"Please take off your shoes.","th":"กรุณาถอดรองเท้าครับ/คะ"},{"en":"Is photography allowed inside?","th":"ข้างในถ่ายรูปได้ไหมครับ/คะ"},{"en":"Please be quiet.","th":"กรุณาเงียบครับ/คะ"}],"quiz":[{"questionTh":"ถ้าอยากขอให้คนช่วยถ่ายรูปให้ ควรพูดว่าอะไร?","choices":["Could you take a photo of us, please?","How much is it?","Where is the exit?","I am hungry."],"answerIndex":0,"explainTh":"\"Could you...?\" เป็นการขอร้องอย่างสุภาพ + take a photo of us = ถ่ายรูปให้พวกเรา จึงเป็นประโยคที่ถูกต้อง"},{"questionTh":"ป้ายเขียนว่า \"No flash.\" หมายความว่าอะไร?","choices":["ห้ามถ่ายรูป","ห้ามใช้แฟลช","ห้ามเข้า","ห้ามส่งเสียงดัง"],"answerIndex":1,"explainTh":"flash = แฟลช (แสงวาบจากกล้อง) ดังนั้น No flash = ห้ามใช้แฟลช แต่ยังถ่ายรูปแบบไม่เปิดแฟลชได้"},{"questionTh":"คำว่า \"quiet\" มีความหมายว่าอะไร?","choices":["เสียงดัง","เร็ว","เงียบ","แพง"],"answerIndex":2,"explainTh":"quiet = เงียบ ในวัดหรือสถานที่ศักดิ์สิทธิ์มักมีป้าย \"Please be quiet\" ขอให้อยู่เงียบ ๆ"},{"questionTh":"ถ้าเจ้าหน้าที่พูดว่า \"Please take off your shoes.\" คุณควรทำอะไร?","choices":["ใส่รองเท้าเพิ่มอีกคู่","เปิดแฟลชถ่ายรูป","ส่งเสียงดัง","ถอดรองเท้า"],"answerIndex":3,"explainTh":"take off = ถอด และ shoes = รองเท้า จึงหมายความว่าให้ถอดรองเท้าก่อนเข้าไปข้างใน"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$จองทัวร์รายวันและพูดคุยกับไกด์$q$, $q${"listen":{"audioText":"Hi, I'd like to book a day tour for tomorrow. (hear) Sure. We have a city tour that leaves at nine a.m. Does that work for you? Yes. How long is the tour? (hear) About six hours, and lunch is included. (hear) Please meet the guide in the hotel lobby at eight forty-five. Great, thank you!","thaiExplain":"สถานการณ์นี้คือการจองทัวร์รายวันที่เคาน์เตอร์ทัวร์หรือโรงแรม บอกว่าอยากจองทัวร์วันไหน แล้วถามรายละเอียด เช่น ออกกี่โมง ใช้เวลานานเท่าไหร่ รวมอาหารไหม และนัดเจอไกด์ที่ไหน ประโยคที่มี (hear) คือคำตอบของพนักงาน/ไกด์"},"vocab":[{"word":"book","ipa":"/bʊk/","thai":"จอง (เป็นคำกริยา)","exampleEn":"I'd like to book a day tour.","exampleTh":"ฉันอยากจองทัวร์รายวันครับ/ค่ะ","associationHintTh":"book ไม่ได้แปลแค่ \"หนังสือ\" แต่ยังแปลว่า \"จอง\" ได้ด้วย เช่น จองโรงแรม จองทัวร์"},{"word":"tour","ipa":"/tʊr/","thai":"ทัวร์, การท่องเที่ยวเป็นรอบ","exampleEn":"What time does the tour start?","exampleTh":"ทัวร์เริ่มกี่โมงครับ/คะ","associationHintTh":"\"ทัวร์\" ทับศัพท์ตรงกับคำไทยที่เราใช้กันอยู่แล้ว"},{"word":"guide","ipa":"/ɡaɪd/","thai":"ไกด์, มัคคุเทศก์","exampleEn":"The guide will meet us in the lobby.","exampleTh":"ไกด์จะมาเจอเราที่ล็อบบี้ครับ/คะ","associationHintTh":"\"ไกด์\" ทับศัพท์ตรงตัว = คนนำเที่ยว"},{"word":"included","ipa":"/ɪnˈkluːdɪd/","thai":"รวมอยู่ด้วยแล้ว","exampleEn":"Is lunch included?","exampleTh":"รวมอาหารกลางวันด้วยไหมครับ/คะ","associationHintTh":"มาจาก \"include\" (รวม) จึงได้ included = รวมอยู่ในราคาแล้ว ไม่ต้องจ่ายเพิ่ม"},{"word":"pick up","ipa":"/ˌpɪk ˈʌp/","thai":"ไปรับ (คน)","exampleEn":"What time will you pick us up?","exampleTh":"จะมารับเรากี่โมงครับ/คะ","associationHintTh":"pick = หยิบ, pick up คน = ไปรับคน เช่น รถทัวร์มารับที่โรงแรม"}],"examples":[{"en":"I'd like to book a day tour.","th":"ฉันอยากจองทัวร์รายวันครับ/ค่ะ"},{"en":"What time does the tour start?","th":"ทัวร์เริ่มกี่โมงครับ/คะ"},{"en":"How long is the tour?","th":"ทัวร์ใช้เวลานานเท่าไหร่ครับ/คะ"},{"en":"Is lunch included?","th":"รวมอาหารกลางวันด้วยไหมครับ/คะ"},{"en":"Where do we meet?","th":"เรานัดเจอกันที่ไหนครับ/คะ"},{"en":"What time will you pick us up?","th":"จะมารับเรากี่โมงครับ/คะ"},{"en":"Can we take photos during the tour?","th":"ถ่ายรูประหว่างทัวร์ได้ไหมครับ/คะ"}],"quiz":[{"questionTh":"ถ้าอยากจองทัวร์รายวัน ควรพูดว่าอะไร?","choices":["I'd like to book a day tour.","I'd like to close the door.","Where is my passport?","How much are these shoes?"],"answerIndex":0,"explainTh":"book = จอง และ day tour = ทัวร์รายวัน ดังนั้น \"I'd like to book a day tour.\" คือการขอจองทัวร์รายวัน"},{"questionTh":"ประโยค \"Is lunch included?\" เป็นการถามอะไร?","choices":["อาหารกลางวันอร่อยไหม","รวมอาหารกลางวันไว้ในราคาแล้วไหม","อาหารกลางวันเสิร์ฟกี่โมง","ร้านอาหารอยู่ที่ไหน"],"answerIndex":1,"explainTh":"included = รวมอยู่แล้ว ดังนั้นเป็นการถามว่าราคาทัวร์รวมค่าอาหารกลางวันด้วยหรือไม่"},{"questionTh":"ไกด์พูดว่า \"The tour is about six hours.\" แปลว่าอะไร?","choices":["ทัวร์ราคาหกดอลลาร์","ทัวร์มีคนหกคน","ทัวร์ใช้เวลาประมาณหกชั่วโมง","ทัวร์ออกตอนหกโมง"],"answerIndex":2,"explainTh":"about = ประมาณ และ six hours = หกชั่วโมง จึงหมายถึงทัวร์ใช้เวลาราวหกชั่วโมง (ไม่ใช่ราคาหรือจำนวนคน)"},{"questionTh":"ถ้าอยากรู้ว่าไกด์หรือรถทัวร์จะมารับกี่โมง ควรถามว่าอะไร?","choices":["How much is it?","What is your name?","Is it far?","What time will you pick us up?"],"answerIndex":3,"explainTh":"pick up = ไปรับ (คน) ดังนั้น \"What time will you pick us up?\" คือถามว่าจะมารับเรากี่โมง"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$ซื้อตั๋ว ถ่ายรูป และจองทัวร์ที่จุดบริการนักท่องเที่ยว$q$, $q$You are a friendly ticket and tour desk agent at a popular tourist attraction. A traveler walks up to your counter to buy admission tickets, ask about opening and closing times, ask for help taking a photo, and book a day tour for tomorrow. Answer politely and clearly, and remind them of simple rules such as no flash photography and taking off shoes inside the temple.$q$, $q$Ticket and tour desk agent$q$, $q$ซื้อตั๋วเข้าชม ถามเวลาเปิด-ปิด ขอถ่ายรูป และจองทัวร์รายวันให้สำเร็จเป็นภาษาอังกฤษ$q$, $q$["ซื้อตั๋วเข้าชมและถามราคาเป็นภาษาอังกฤษได้","ถามเวลาเปิด-ปิด หรือขอให้ช่วยถ่ายรูป และถามกฎของสถานที่ได้","จองทัวร์รายวันและถามรายละเอียด (เวลาออก จุดนัดพบ อาหาร) ได้"]$q$::jsonb);
END IF;
END $do$;

-- Unit 14: เข้าสังคมและคุยเล่น
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 14) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 14, $q$เข้าสังคมและคุยเล่น$q$, $q$คุยเล่นกับคนท้องถิ่น ตอบรับ/ปฏิเสธคำชวน และมารยาทสากล$q$, 'A2', $q$💬$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$คุยเล่นกับคนท้องถิ่นและนักท่องเที่ยว$q$, $q${"listen":{"audioText":"Hi, is this seat taken? (hear) No, go ahead. So, where are you from? (hear) I'm from Thailand. This is my first time in London. Oh, nice! How long are you staying? (hear)","thaiExplain":"สถานการณ์: คุยเล่นเปิดเรื่องกับคนแปลกหน้าระหว่างเดินทาง เช่น ในโฮสเทลหรือบนทัวร์ เริ่มจากถามที่นั่งว่าง แล้วถามว่ามาจากไหนและมาเที่ยวนานแค่ไหน ให้ตอบสั้นๆ เป็นมิตร แล้วถามกลับเพื่อให้บทสนทนาไหลต่อ"},"vocab":[{"word":"alone","ipa":"/əˈloʊn/","thai":"คนเดียว, ลำพัง","exampleEn":"Are you traveling alone?","exampleTh":"คุณเดินทางคนเดียวเหรอ","associationHintTh":"อะ-โลน เสียงคล้าย 'อะ โล่น' นึกภาพยืนโล่งๆ อยู่คนเดียว"},{"word":"first time","ipa":"/ˌfɜːrst ˈtaɪm/","thai":"ครั้งแรก","exampleEn":"This is my first time here.","exampleTh":"นี่เป็นครั้งแรกของฉันที่นี่","associationHintTh":"first = ที่หนึ่ง + time = ครั้ง รวมกันเป็น 'ครั้งแรก'"},{"word":"weather","ipa":"/ˈweðər/","thai":"สภาพอากาศ","exampleEn":"The weather is lovely today.","exampleTh":"วันนี้อากาศดีจังเลย","associationHintTh":"เว-เธอร์ นึกถึงฟ้าฝนที่เปลี่ยนไปเรื่อยๆ"},{"word":"holiday","ipa":"/ˈhɒlədeɪ/","thai":"วันหยุด, มาเที่ยวพักผ่อน","exampleEn":"Are you here on holiday?","exampleTh":"คุณมาเที่ยวพักผ่อนเหรอ","associationHintTh":"ฮอลิเดย์ คนไทยคุ้นคำนี้อยู่แล้ว = วันหยุดเที่ยว"},{"word":"local","ipa":"/ˈloʊkl/","thai":"คนท้องถิ่น, ของท้องถิ่น","exampleEn":"Can you recommend a good local restaurant?","exampleTh":"แนะนำร้านอาหารท้องถิ่นอร่อยๆ ให้หน่อยได้ไหม","associationHintTh":"โลคอล = ร้าน 'โลคอล' ของท้องถิ่นที่คนแถวนั้นกิน"}],"examples":[{"en":"Where are you from?","th":"คุณมาจากไหน"},{"en":"I'm from Thailand.","th":"ฉันมาจากประเทศไทย"},{"en":"Is this your first time here?","th":"นี่เป็นครั้งแรกของคุณที่นี่ไหม"},{"en":"The weather is lovely today.","th":"วันนี้อากาศดีจังเลย"},{"en":"Are you here on holiday?","th":"คุณมาเที่ยวพักผ่อนเหรอ"},{"en":"How long are you staying?","th":"คุณจะอยู่ที่นี่นานแค่ไหน"},{"en":"Nice to meet you.","th":"ยินดีที่ได้รู้จัก"}],"quiz":[{"questionTh":"มีคนถามว่า \"Where are you from?\" ควรตอบว่าอะไร","choices":["I'm from Thailand.","Yes, please.","It's five o'clock.","No, thank you."],"answerIndex":0,"explainTh":"\"Where are you from?\" แปลว่า 'คุณมาจากไหน' จึงตอบด้วยประเทศ/บ้านเกิดว่า I'm from Thailand."},{"questionTh":"อยากถามว่าคนอื่นมาที่นี่ครั้งแรกไหม พูดว่าอะไร","choices":["How much is it?","Is this your first time here?","Where is the toilet?","What time is it?"],"answerIndex":1,"explainTh":"first time = ครั้งแรก ประโยค Is this your first time here? จึงแปลว่า 'นี่เป็นครั้งแรกของคุณที่นี่ไหม'"},{"questionTh":"คำว่า \"weather\" หมายถึงอะไร","choices":["เวลา","อาหาร","สภาพอากาศ","ที่นั่ง"],"answerIndex":2,"explainTh":"weather แปลว่า 'สภาพอากาศ' เช่น The weather is nice = อากาศดี"},{"questionTh":"เพื่อนใหม่พูดว่า \"Nice to meet you.\" ควรตอบว่าอะไร","choices":["Goodbye forever.","You're welcome.","I'm sorry.","Nice to meet you too."],"answerIndex":3,"explainTh":"เมื่อมีคนบอก 'ยินดีที่ได้รู้จัก' เราตอบกลับด้วย Nice to meet you too. = 'ยินดีที่ได้รู้จักเช่นกัน'"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ตอบรับ/ปฏิเสธคำชวน และแลกช่องทางติดต่อ$q$, $q${"listen":{"audioText":"We're going for dinner tonight. Would you like to join us? (hear) That sounds great! I'd love to. Awesome! Can I get your number? (hear) Sure. Let's add each other on WhatsApp.","thaiExplain":"สถานการณ์: เพื่อนใหม่ชวนไปทำกิจกรรมด้วยกัน ถ้าอยากไปให้ตอบรับด้วย \"I'd love to\" ถ้าไปไม่ได้ให้ปฏิเสธอย่างสุภาพว่า \"Maybe next time.\" จากนั้นแลกเบอร์หรือโซเชียลเพื่อติดต่อกันต่อ"},"vocab":[{"word":"join","ipa":"/dʒɔɪn/","thai":"เข้าร่วม, ไปด้วย","exampleEn":"Would you like to join us?","exampleTh":"อยากไปกับเราไหม","associationHintTh":"จอย = 'จอย' สนุก มา 'จอย' กับเราไหม = มาร่วมสนุก"},{"word":"love to","ipa":"/ˈlʌv tuː/","thai":"อยากทำมาก (ใช้ตอบรับ)","exampleEn":"I'd love to!","exampleTh":"อยากไปมากเลย!","associationHintTh":"เลิฟ-ทู = รักที่จะทำ แปลว่าอยากทำมากๆ"},{"word":"maybe","ipa":"/ˈmeɪbi/","thai":"บางที, อาจจะ","exampleEn":"Sorry, maybe next time.","exampleTh":"ขอโทษนะ ไว้คราวหน้าแล้วกัน","associationHintTh":"เม-บี = 'เม' อาจจะ 'บี' เป็นได้ = อาจจะ"},{"word":"contact","ipa":"/ˈkɒntækt/","thai":"ติดต่อ, ช่องทางติดต่อ","exampleEn":"Let's stay in contact.","exampleTh":"ติดต่อกันไว้นะ","associationHintTh":"คอนแทค คนไทยพูดทับศัพท์อยู่แล้ว = ติดต่อ"},{"word":"tonight","ipa":"/təˈnaɪt/","thai":"คืนนี้, เย็นนี้","exampleEn":"Are you free tonight?","exampleTh":"คืนนี้คุณว่างไหม","associationHintTh":"ทู-ไนท์ = to + night (กลางคืน) = คืนนี้"}],"examples":[{"en":"Would you like to join us?","th":"อยากไปกับเราไหม"},{"en":"I'd love to!","th":"อยากไปมากเลย!"},{"en":"Sorry, maybe next time.","th":"ขอโทษนะ ไว้คราวหน้าแล้วกัน"},{"en":"Can I get your number?","th":"ขอเบอร์คุณได้ไหม"},{"en":"Let's add each other on Instagram.","th":"มาแอดกันในอินสตาแกรมเถอะ"},{"en":"What's your WhatsApp?","th":"วอทส์แอปคุณเบอร์อะไร"},{"en":"I'll text you later.","th":"เดี๋ยวฉันจะทักไปทีหลังนะ"}],"quiz":[{"questionTh":"เพื่อนชวน \"Would you like to join us for dinner?\" ถ้าอยากไป ตอบว่าอะไร","choices":["I'd love to!","No idea.","It's too far.","Goodbye."],"answerIndex":0,"explainTh":"I'd love to! = 'อยากไปมากเลย' เป็นการตอบรับคำชวนอย่างเต็มใจและสุภาพ"},{"questionTh":"ถ้าอยากปฏิเสธคำชวนอย่างสุภาพ ควรพูดว่าอะไร","choices":["I hate you.","Sorry, maybe next time.","Yes, of course.","You're wrong."],"answerIndex":1,"explainTh":"Sorry, maybe next time. = 'ขอโทษนะ ไว้คราวหน้า' เป็นการปฏิเสธที่นุ่มนวลและรักษาน้ำใจ"},{"questionTh":"อยากขอเบอร์โทรของเพื่อนใหม่ พูดว่าอะไร","choices":["What's the time?","How old are you?","Can I get your number?","Where do you live?"],"answerIndex":2,"explainTh":"Can I get your number? = 'ขอเบอร์คุณได้ไหม' เป็นวิธีขอเบอร์โทรที่สุภาพและใช้บ่อย"},{"questionTh":"ประโยค \"I'll text you later.\" แปลว่าอะไร","choices":["ฉันจะโทรหาคุณเดี๋ยวนี้","ฉันไม่อยากคุยกับคุณ","ฉันจะไปหาคุณพรุ่งนี้","เดี๋ยวฉันจะทักหาคุณทีหลัง"],"answerIndex":3,"explainTh":"text = ส่งข้อความ, later = ทีหลัง จึงแปลว่า 'เดี๋ยวฉันจะทักหาคุณทีหลัง'"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$ชมและรับคำชม มารยาทสากล และนามบัตรธุรกิจ$q$, $q${"listen":{"audioText":"I love your jacket! Where did you get it? (hear) Thank you! I got it in Bangkok. By the way, here's my business card. (hear) Thanks! Here's mine. It was really nice talking to you.","thaiExplain":"สถานการณ์: การชมคนอื่นช่วยสร้างมิตรภาพ เมื่อถูกชมให้ตอบ \"Thank you\" อย่างมั่นใจ ไม่ต้องปฏิเสธหรือถ่อมตัวเกินไป และในบริบทธุรกิจ ให้ยื่นและรับนามบัตรด้วยความสุภาพ"},"vocab":[{"word":"compliment","ipa":"/ˈkɒmplɪmənt/","thai":"คำชม","exampleEn":"Thank you for the compliment.","exampleTh":"ขอบคุณสำหรับคำชมนะ","associationHintTh":"คอมพลิเมนต์ คล้าย complete = คำพูดดีๆ ที่ทำให้ใจเต็ม"},{"word":"thank","ipa":"/θæŋk/","thai":"ขอบคุณ","exampleEn":"Thank you, that's very kind.","exampleTh":"ขอบคุณค่ะ ใจดีจังเลย","associationHintTh":"แธ็งก์ เสียงคล้าย 'แต๊งกิ้ว' ที่เราพูดกันติดปากอยู่แล้ว = ขอบคุณ"},{"word":"business card","ipa":"/ˈbɪznəs kɑːrd/","thai":"นามบัตร","exampleEn":"Here's my business card.","exampleTh":"นี่นามบัตรของผมครับ","associationHintTh":"business = ธุรกิจ + card = การ์ด รวมเป็น 'การ์ดธุรกิจ' = นามบัตร"},{"word":"polite","ipa":"/pəˈlaɪt/","thai":"สุภาพ, มีมารยาท","exampleEn":"It's polite to say thank you.","exampleTh":"การพูดขอบคุณเป็นมารยาทที่ดี","associationHintTh":"โพ-ไลท์ นึกถึงคนสุภาพที่ดูสว่างสดใสน่าคบ"},{"word":"handshake","ipa":"/ˈhændʃeɪk/","thai":"การจับมือ","exampleEn":"A firm handshake makes a good impression.","exampleTh":"การจับมือแน่นๆ สร้างความประทับใจที่ดี","associationHintTh":"hand = มือ + shake = เขย่า รวมเป็น 'จับมือเขย่า'"}],"examples":[{"en":"I love your shoes!","th":"ฉันชอบรองเท้าคุณจังเลย"},{"en":"That's a beautiful dress.","th":"ชุดนั้นสวยจังเลย"},{"en":"Thank you, that's very kind.","th":"ขอบคุณค่ะ ใจดีจังเลย"},{"en":"You speak English very well.","th":"คุณพูดภาษาอังกฤษเก่งมากเลย"},{"en":"Here's my business card.","th":"นี่นามบัตรของผมครับ"},{"en":"It's nice to shake hands when you meet someone.","th":"การจับมือตอนเจอกันเป็นมารยาทที่ดี"},{"en":"Thank you! Here's mine.","th":"ขอบคุณครับ นี่ของผมครับ"}],"quiz":[{"questionTh":"มีคนชมว่า \"I love your jacket!\" ควรตอบว่าอะไรให้เหมาะสม","choices":["No, it's ugly.","Thank you!","Why do you ask?","It's none of your business."],"answerIndex":1,"explainTh":"เมื่อถูกชม มารยาทสากลคือตอบรับด้วย Thank you! อย่างมั่นใจ ไม่ต้องปฏิเสธหรือถ่อมตัวว่าไม่จริง"},{"questionTh":"คำว่า \"business card\" หมายถึงอะไร","choices":["นามบัตร","บัตรเครดิต","บัตรโดยสาร","ตั๋วเครื่องบิน"],"answerIndex":0,"explainTh":"business card คือ 'นามบัตร' การ์ดใบเล็กที่มีชื่อ ตำแหน่ง และช่องทางติดต่อ ใช้แลกกันในการทำงาน"},{"questionTh":"อยากชมว่าอีกฝ่ายพูดภาษาอังกฤษเก่ง พูดว่าอะไร","choices":["Your English is terrible.","Do you speak English?","You speak English very well.","I don't understand you."],"answerIndex":2,"explainTh":"You speak English very well. = 'คุณพูดภาษาอังกฤษเก่งมาก' เป็นคำชมที่สุภาพและให้กำลังใจ"},{"questionTh":"มารยาทสากลตอนพบคนใหม่ในบริบทธุรกิจ มักทำสิ่งใด","choices":["หันหลังเดินหนี","ตะโกนใส่","เล่นโทรศัพท์ไปด้วย","จับมือทักทาย (shake hands)"],"answerIndex":3,"explainTh":"การจับมือ (handshake) พร้อมสบตาและยิ้ม เป็นมารยาทสากลที่ใช้ทักทายเมื่อพบคนใหม่ในบริบทธุรกิจ"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$คุยเล่นกับเพื่อนร่วมทริปที่งานเลี้ยงต้อนรับของโรงแรม$q$, $q$You are Emma, a friendly Canadian traveler staying at the same hotel as the learner. You meet them at the hotel's evening welcome reception with drinks and snacks. Start with small talk, invite the learner to join a group dinner tonight, exchange contact details, give a genuine compliment, and offer your business card. Keep your English simple, warm, and slow, and always ask a follow-up question so the learner keeps talking.$q$, $q$Emma, a friendly fellow traveler at the hotel welcome reception$q$, $q$เริ่มคุยเล่นกับเพื่อนใหม่ ตอบรับหรือปฏิเสธคำชวนไปกินข้าวอย่างสุภาพ แลกช่องทางติดต่อ และชม/รับคำชมได้อย่างมั่นใจ$q$, $q$["เปิดบทสนทนาและแนะนำตัว บอกได้ว่ามาจากไหน แล้วถามกลับอีกฝ่ายอย่างน้อย 1 คำถาม","ตอบรับหรือปฏิเสธคำชวนไปกินข้าวอย่างสุภาพ แล้วขอหรือให้ช่องทางติดต่อ (เบอร์หรือโซเชียล)","ชมอีกฝ่ายอย่างน้อย 1 ครั้ง และเมื่อถูกชมกลับ ให้ตอบรับด้วย \"Thank you\" อย่างเหมาะสม"]$q$::jsonb);
END IF;
END $do$;

-- Unit 15: สุขภาพและเหตุฉุกเฉิน
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 15) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 15, $q$สุขภาพและเหตุฉุกเฉิน$q$, $q$ร้านยา หาหมอ แจ้งความ พาสปอร์ตหาย และโทรสายฉุกเฉิน$q$, 'A2', $q$🚑$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$ร้านขายยา: บอกอาการและซื้อยา$q$, $q${"listen":{"audioText":"Hi, I have a headache and a sore throat. (hear) How long have you had these symptoms? Since yesterday. Do you have any medicine for it? (hear) Yes. Take one tablet after meals, twice a day. Thank you.","thaiExplain":"ที่ร้านขายยา ให้บอกอาการของคุณสั้นๆ ชัดๆ ก่อน แล้วถามว่ามียาไหม สุดท้ายฟังวิธีกินยาให้ดี (กินกี่เม็ด กี่ครั้ง ก่อนหรือหลังอาหาร)"},"vocab":[{"word":"medicine","ipa":"/ˈmedɪsɪn/","thai":"ยา","exampleEn":"Do you have medicine for a cough?","exampleTh":"คุณมียาแก้ไอไหม","associationHintTh":"เมด-ดิ-ซิน เสียงคล้าย 'เมดิเคชั่น' = ยา"},{"word":"headache","ipa":"/ˈhedeɪk/","thai":"อาการปวดหัว","exampleEn":"I have a bad headache.","exampleTh":"ฉันปวดหัวมาก","associationHintTh":"head (หัว) + ache (ปวด) = ปวดหัว"},{"word":"fever","ipa":"/ˈfiːvər/","thai":"ไข้ / ตัวร้อน","exampleEn":"I think I have a fever.","exampleTh":"ฉันคิดว่าฉันมีไข้","associationHintTh":"ฟี-เวอร์ เสียงคล้าย 'ฟีเวอร์' ตอนตัวร้อน"},{"word":"pharmacy","ipa":"/ˈfɑːrməsi/","thai":"ร้านขายยา","exampleEn":"Where is the nearest pharmacy?","exampleTh":"ร้านขายยาที่ใกล้ที่สุดอยู่ที่ไหน","associationHintTh":"ฟาร์-มะ-ซี จำคู่กับคำว่า 'เภสัช'"},{"word":"painkiller","ipa":"/ˈpeɪnkɪlər/","thai":"ยาแก้ปวด","exampleEn":"Can I get a painkiller, please?","exampleTh":"ขอยาแก้ปวดหน่อยได้ไหม","associationHintTh":"pain (ปวด) + killer (ฆ่า) = ฆ่าความปวด = ยาแก้ปวด"}],"examples":[{"en":"I have a stomachache.","th":"ฉันปวดท้อง"},{"en":"Do you have medicine for a cold?","th":"คุณมียาแก้หวัดไหม"},{"en":"How many times a day should I take it?","th":"ฉันควรกินวันละกี่ครั้ง"},{"en":"I need something for a cough.","th":"ฉันอยากได้ยาแก้ไอ"},{"en":"Should I take this before or after meals?","th":"ฉันควรกินยานี้ก่อนหรือหลังอาหาร"},{"en":"I'm allergic to aspirin.","th":"ฉันแพ้ยาแอสไพริน"}],"quiz":[{"questionTh":"เภสัชกรถามว่า 'How long have you had these symptoms?' หมายความว่าอะไร","choices":["คุณมีอาการนี้มานานแค่ไหน","คุณกำลังกินยาอะไรอยู่","คุณอายุเท่าไร","คุณชื่ออะไร"],"answerIndex":0,"explainTh":"How long ... symptoms = ถามว่ามีอาการมานานเท่าไร ควรตอบเป็นช่วงเวลา เช่น 'Since yesterday'"},{"questionTh":"ถ้าปวดหัว ควรพูดว่าอะไร","choices":["I have a stomachache.","I have a sore throat.","I have a headache.","I have a toothache."],"answerIndex":2,"explainTh":"headache = ปวดหัว ส่วน stomachache = ปวดท้อง, sore throat = เจ็บคอ, toothache = ปวดฟัน"},{"questionTh":"อยากบอกว่า 'ขอยาแก้ปวด' พูดว่าอะไร","choices":["Can I get a bandage?","Can I get a painkiller?","Can I get a receipt?","Can I get a menu?"],"answerIndex":1,"explainTh":"painkiller = ยาแก้ปวด ส่วน bandage = ผ้าพันแผล, receipt = ใบเสร็จ, menu = เมนู"},{"questionTh":"เภสัชกรบอกว่า 'Take one tablet after meals.' หมายความว่าอะไร","choices":["กินยา 3 เม็ดก่อนนอน","กินยาตอนท้องว่าง","หยุดกินยา","กินยา 1 เม็ดหลังอาหาร"],"answerIndex":3,"explainTh":"one tablet = 1 เม็ด, after meals = หลังอาหาร"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$หาหมอที่คลินิก/โรงพยาบาล และแจ้งแพ้ยา/โรคประจำตัว$q$, $q${"listen":{"audioText":"I don't feel well. I'd like to see a doctor. (hear) What's the problem? I have a high fever and I feel dizzy. (hear) Are you allergic to any medicine? Yes, I'm allergic to penicillin. I also have asthma.","thaiExplain":"ที่คลินิกหรือโรงพยาบาล ให้บอกหมอว่าไม่สบายตรงไหน และต้องแจ้ง 'ยาที่แพ้' กับ 'โรคประจำตัว' ทุกครั้ง เพราะสำคัญต่อความปลอดภัยของคุณมาก"},"vocab":[{"word":"doctor","ipa":"/ˈdɒktər/","thai":"หมอ / แพทย์","exampleEn":"I need to see a doctor.","exampleTh":"ฉันต้องไปหาหมอ","associationHintTh":"ด็อก-เตอร์ = คุณหมอ คำที่ได้ยินบ่อย"},{"word":"allergic","ipa":"/əˈlɜːrdʒɪk/","thai":"แพ้ (ยา/อาหาร)","exampleEn":"I'm allergic to seafood.","exampleTh":"ฉันแพ้อาหารทะเล","associationHintTh":"อะ-เลอร์-จิก เสียงคล้าย 'อัลเลอร์จี้' = ภูมิแพ้"},{"word":"dizzy","ipa":"/ˈdɪzi/","thai":"เวียนหัว / มึนหัว","exampleEn":"I feel dizzy when I stand up.","exampleTh":"ฉันรู้สึกเวียนหัวเวลาลุกขึ้นยืน","associationHintTh":"ดิซ-ซี่ นึกถึงหัวหมุนติ้วๆ เวียนหัว"},{"word":"symptom","ipa":"/ˈsɪmptəm/","thai":"อาการ","exampleEn":"My symptoms started this morning.","exampleTh":"อาการของฉันเริ่มเมื่อเช้านี้","associationHintTh":"ซิมพ-เทิ่ม = อาการต่างๆ ที่ร่างกายเป็น"},{"word":"prescription","ipa":"/prɪˈskrɪpʃən/","thai":"ใบสั่งยา","exampleEn":"The doctor gave me a prescription.","exampleTh":"หมอให้ใบสั่งยาฉันมา","associationHintTh":"พรี-สคริพ-ชั่น = ใบที่หมอเขียนสั่งยาให้ไปซื้อ"}],"examples":[{"en":"I don't feel well.","th":"ฉันรู้สึกไม่สบาย"},{"en":"I have a high fever.","th":"ฉันมีไข้สูง"},{"en":"I'm allergic to penicillin.","th":"ฉันแพ้ยาเพนิซิลลิน"},{"en":"I have diabetes.","th":"ฉันเป็นโรคเบาหวาน"},{"en":"How often should I take this medicine?","th":"ฉันควรกินยานี้บ่อยแค่ไหน"},{"en":"Do I need to come back?","th":"ฉันต้องกลับมาอีกไหม"}],"quiz":[{"questionTh":"หมอถามว่า 'Are you allergic to any medicine?' ถ้าคุณแพ้เพนิซิลลิน ควรตอบว่าอะไร","choices":["No, I'm fine.","Yes, I'm allergic to penicillin.","I have a headache.","I need a taxi."],"answerIndex":1,"explainTh":"คำถามถามว่าแพ้ยาไหม ต้องตอบ Yes แล้วบอกชื่อยาที่แพ้ เพื่อความปลอดภัย"},{"questionTh":"'I feel dizzy.' แปลว่าอะไร","choices":["ฉันหิว","ฉันง่วงนอน","ฉันเจ็บคอ","ฉันเวียนหัว"],"answerIndex":3,"explainTh":"dizzy = เวียนหัว / มึนหัว"},{"questionTh":"อยากบอกโรคประจำตัวว่าเป็นเบาหวาน พูดว่าอะไร","choices":["I have diabetes.","I have a cold.","I have a map.","I have a ticket."],"answerIndex":0,"explainTh":"diabetes = เบาหวาน เป็นโรคประจำตัวที่ต้องแจ้งหมอ"},{"questionTh":"'prescription' คืออะไร","choices":["ใบเสร็จ","ตั๋วเครื่องบิน","ใบสั่งยา","หนังสือเดินทาง"],"answerIndex":2,"explainTh":"prescription = ใบสั่งยาที่หมอเขียนให้เอาไปซื้อยา"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$แจ้งตำรวจของถูกขโมย พาสปอร์ตหาย/สถานทูต$q$, $q${"listen":{"audioText":"Excuse me, I need help. My bag was stolen. (hear) Where did it happen? Near the train station, about an hour ago. My passport was in the bag. (hear) Please fill out this report. I also need to contact my embassy.","thaiExplain":"ถ้าของถูกขโมยหรือพาสปอร์ตหาย ให้แจ้งตำรวจเพื่อขอ 'ใบแจ้งความ' (police report) แล้วติดต่อ 'สถานทูต' เพื่อทำพาสปอร์ตใหม่ พูดสั้นๆ ว่าเกิดอะไร ที่ไหน เมื่อไร"},"vocab":[{"word":"passport","ipa":"/ˈpæspɔːrt/","thai":"หนังสือเดินทาง","exampleEn":"I lost my passport.","exampleTh":"ฉันทำหนังสือเดินทางหาย","associationHintTh":"pass (ผ่าน) + port (ท่า/ด่าน) = เอกสารผ่านด่าน"},{"word":"stolen","ipa":"/ˈstoʊlən/","thai":"ถูกขโมย","exampleEn":"My phone was stolen.","exampleTh":"โทรศัพท์ของฉันถูกขโมย","associationHintTh":"สโต-เลิ่น มาจาก steal (ขโมย) = ถูกขโมยไปแล้ว"},{"word":"police","ipa":"/pəˈliːs/","thai":"ตำรวจ","exampleEn":"I want to call the police.","exampleTh":"ฉันอยากโทรเรียกตำรวจ","associationHintTh":"พะ-ลีส = ตำรวจ เน้นเสียงพยางค์หลัง"},{"word":"embassy","ipa":"/ˈembəsi/","thai":"สถานทูต","exampleEn":"Where is the Thai embassy?","exampleTh":"สถานทูตไทยอยู่ที่ไหน","associationHintTh":"เอ็ม-บะ-ซี่ = สถานทูตของประเทศเรา ที่ช่วยคนไทยในต่างแดน"},{"word":"report","ipa":"/rɪˈpɔːrt/","thai":"ใบแจ้งความ / รายงาน","exampleEn":"I need to file a police report.","exampleTh":"ฉันต้องไปแจ้งความ","associationHintTh":"รี-พอร์ท = เอกสารแจ้งเรื่องกับตำรวจ"}],"examples":[{"en":"My bag was stolen.","th":"กระเป๋าของฉันถูกขโมย"},{"en":"I lost my passport.","th":"ฉันทำหนังสือเดินทางหาย"},{"en":"I need to file a police report.","th":"ฉันต้องไปแจ้งความ"},{"en":"Can you help me contact my embassy?","th":"ช่วยติดต่อสถานทูตให้ฉันได้ไหม"},{"en":"It happened near the hotel.","th":"มันเกิดขึ้นใกล้ๆ โรงแรม"},{"en":"Someone took my wallet.","th":"มีคนเอากระเป๋าเงินของฉันไป"}],"quiz":[{"questionTh":"จะบอกว่า 'ฉันทำหนังสือเดินทางหาย' พูดว่าอะไร","choices":["I found my passport.","I have my passport.","I lost my passport.","I bought a passport."],"answerIndex":2,"explainTh":"lost = ทำหาย, passport = หนังสือเดินทาง ส่วน found = เจอแล้ว, bought = ซื้อ"},{"questionTh":"ตำรวจถามว่า 'Where did it happen?' หมายความว่าอะไร","choices":["มันเกิดขึ้นที่ไหน","มันเกิดขึ้นเมื่อไร","คุณชื่ออะไร","ของอะไรหาย"],"answerIndex":0,"explainTh":"Where = ที่ไหน, did it happen = เกิดขึ้น รวมกันคือถามสถานที่เกิดเหตุ"},{"questionTh":"ถ้าพาสปอร์ตหาย ควรติดต่อที่ไหนเพื่อทำเล่มใหม่","choices":["ร้านขายยา (pharmacy)","ร้านอาหาร (restaurant)","ร้านค้าในสนามบิน (airport shop)","สถานทูต (embassy)"],"answerIndex":3,"explainTh":"embassy = สถานทูต ทำหน้าที่ช่วยคนชาติตัวเองเรื่องพาสปอร์ตหาย"},{"questionTh":"'My phone was stolen.' แปลว่าอะไร","choices":["ฉันซื้อโทรศัพท์ใหม่","โทรศัพท์ของฉันถูกขโมย","ฉันทำโทรศัพท์ตก","โทรศัพท์ของฉันเสีย"],"answerIndex":1,"explainTh":"was stolen = ถูกขโมย"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 4, 'communication', $q$โทรสายฉุกเฉินและหลงทาง/พลัดหลง$q$, $q${"listen":{"audioText":"(hear) Emergency services. What's your emergency? Please help! There's been an accident and someone is hurt. (hear) What is your location? I'm near the beach entrance. Please send an ambulance quickly.","thaiExplain":"เมื่อเกิดเหตุฉุกเฉินให้โทรสายฉุกเฉิน (เช่น 911 ในสหรัฐฯ, 112 ในยุโรป) บอกให้ชัดว่า 'เกิดอะไร' และ 'อยู่ที่ไหน' ถ้าพลัดหลงกับคนในกลุ่ม ให้อยู่กับที่แล้วขอความช่วยเหลือ"},"vocab":[{"word":"emergency","ipa":"/ɪˈmɜːrdʒənsi/","thai":"เหตุฉุกเฉิน","exampleEn":"This is an emergency!","exampleTh":"นี่คือเหตุฉุกเฉิน","associationHintTh":"อี-เมอร์-เจิน-ซี่ = เรื่องด่วนคอขาดบาดตาย"},{"word":"ambulance","ipa":"/ˈæmbjələns/","thai":"รถพยาบาล","exampleEn":"Please call an ambulance.","exampleTh":"ช่วยเรียกรถพยาบาลด้วย","associationHintTh":"แอม-บิว-เลินซ์ = รถพยาบาลเสียงหวอ"},{"word":"accident","ipa":"/ˈæksɪdənt/","thai":"อุบัติเหตุ","exampleEn":"There's been a car accident.","exampleTh":"มีอุบัติเหตุรถชนเกิดขึ้น","associationHintTh":"แอค-ซิ-เดินท์ = อุบัติเหตุที่ไม่ได้ตั้งใจ"},{"word":"lost","ipa":"/lɒst/","thai":"หลงทาง / หาย","exampleEn":"I'm lost. Can you help me?","exampleTh":"ฉันหลงทาง ช่วยฉันได้ไหม","associationHintTh":"ลอสท์ = หลง/หาย นึกถึงหนังเรื่อง Lost"},{"word":"help","ipa":"/help/","thai":"ช่วยเหลือ / ช่วยด้วย","exampleEn":"Help! I need help.","exampleTh":"ช่วยด้วย! ฉันต้องการความช่วยเหลือ","associationHintTh":"เฮลพ์ = คำสั้นที่สุดที่ตะโกนได้ทันทีตอนฉุกเฉิน"}],"examples":[{"en":"Help! Please help me.","th":"ช่วยด้วย! ช่วยฉันด้วย"},{"en":"Please call an ambulance.","th":"ช่วยเรียกรถพยาบาลด้วย"},{"en":"There's been an accident.","th":"มีอุบัติเหตุเกิดขึ้น"},{"en":"I'm lost. Can you help me?","th":"ฉันหลงทาง ช่วยฉันได้ไหม"},{"en":"I can't find my child.","th":"ฉันหาลูกไม่เจอ"},{"en":"My location is near the train station.","th":"ตำแหน่งของฉันอยู่ใกล้สถานีรถไฟ"}],"quiz":[{"questionTh":"เมื่อโทรสายฉุกเฉิน เจ้าหน้าที่ถาม 'What is your location?' ควรตอบว่าอะไร","choices":["My name is John.","I'm near the beach entrance.","I'm fine, thank you.","I like the beach."],"answerIndex":1,"explainTh":"location = ตำแหน่ง/สถานที่ ต้องตอบว่าอยู่ที่ไหน เพื่อให้ความช่วยเหลือไปถึง"},{"questionTh":"'I'm lost.' แปลว่าอะไร","choices":["ฉันหิว","ฉันเหนื่อย","ฉันสบายดี","ฉันหลงทาง"],"answerIndex":3,"explainTh":"lost = หลงทาง"},{"questionTh":"อยากเรียกรถพยาบาล พูดว่าอะไร","choices":["Please call an ambulance.","Please call a taxi.","Please call a waiter.","Please call the hotel."],"answerIndex":0,"explainTh":"ambulance = รถพยาบาล ส่วน taxi = แท็กซี่, waiter = พนักงานเสิร์ฟ, hotel = โรงแรม"},{"questionTh":"ถ้าพลัดหลงกับลูก จะบอกเจ้าหน้าที่ว่าอะไร","choices":["I found my child.","I have two children.","I can't find my child.","My child is sleeping."],"answerIndex":2,"explainTh":"can't find = หาไม่เจอ ใช้บอกว่าพลัดหลงกับลูก"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$ที่ร้านขายยาต่างประเทศ$q$, $q$You are a friendly pharmacist at a pharmacy abroad. A Thai traveler walks in feeling unwell and needs medicine. Ask about their symptoms, how long they have had them, and whether they are allergic to any medicine, then recommend a medicine and clearly explain how to take it.$q$, $q$Pharmacist$q$, $q$บอกอาการของตัวเองเป็นภาษาอังกฤษ ถามซื้อยาที่ต้องการ และเข้าใจวิธีกินยาที่เภสัชกรบอก$q$, $q$["บอกอาการอย่างน้อย 1 อย่างเป็นภาษาอังกฤษได้ (เช่น ปวดหัว มีไข้ ปวดท้อง)","แจ้งยาที่แพ้ได้ หรือตอบได้ว่าไม่แพ้ยาอะไร","เข้าใจและถามย้ำวิธีกินยา (กินกี่เม็ด กี่ครั้งต่อวัน ก่อนหรือหลังอาหาร)"]$q$::jsonb);
END IF;
END $do$;

-- Unit 16: ขากลับบ้าน
DO $do$
DECLARE u uuid;
BEGIN
IF NOT EXISTS (SELECT 1 FROM units WHERE order_index = 16) THEN
  u := gen_random_uuid();
  INSERT INTO units (id, order_index, title_th, description_th, cefr_level, milestone_badge)
  VALUES (u, 16, $q$ขากลับบ้าน$q$, $q$เช็คอินขากลับ ดิวตี้ฟรี คืนภาษี และรับมือไฟลต์ดีเลย์$q$, 'A2', $q$🧳$q$);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 1, 'communication', $q$เช็คอินขากลับ (ตู้คีออสก์) และหย่อนกระเป๋า$q$, $q${"listen":{"audioText":"Hi, I'd like to check in for my flight to Bangkok. Please scan your passport at the kiosk and take your boarding pass. (hear) I've got my boarding pass. Where do I drop my bag? Put your suitcase on the scale, please. It's two kilos overweight. (hear)","thaiExplain":"ขากลับส่วนใหญ่จะเช็คอินเองที่ตู้คีออสก์ (kiosk) โดยสแกนพาสปอร์ตแล้วพิมพ์บัตรขึ้นเครื่องออกมา จากนั้นนำกระเป๋าไปหย่อนที่จุด bag drop และวางบนเครื่องชั่ง ระวังน้ำหนักเกินเพราะอาจต้องจ่ายเพิ่ม"},"vocab":[{"word":"kiosk","ipa":"/ˈkiːɒsk/","thai":"ตู้เช็คอินอัตโนมัติ","exampleEn":"You can check in yourself at the kiosk.","exampleTh":"คุณเช็คอินเองได้ที่ตู้คีออสก์","associationHintTh":"ทับศัพท์ว่า 'คีออสก์' เป็นตู้ตั้งเดี่ยวๆ ให้กดเอง นึกถึงตู้ ATM"},{"word":"boarding pass","ipa":"/ˈbɔːrdɪŋ pæs/","thai":"บัตรขึ้นเครื่อง","exampleEn":"Please show your boarding pass at the gate.","exampleTh":"กรุณาแสดงบัตรขึ้นเครื่องที่ประตูทางออก","associationHintTh":"board = ขึ้น(เครื่อง) + pass = บัตรผ่าน → บัตรผ่านขึ้นเครื่อง"},{"word":"bag drop","ipa":"/ˈbæɡ drɑːp/","thai":"จุดหย่อนกระเป๋า","exampleEn":"Take your suitcase to the bag drop counter.","exampleTh":"นำกระเป๋าเดินทางไปที่เคาน์เตอร์หย่อนกระเป๋า","associationHintTh":"bag = กระเป๋า + drop = หย่อน/วาง → จุดวางกระเป๋าลงสายพาน"},{"word":"overweight","ipa":"/ˌoʊvərˈweɪt/","thai":"น้ำหนักเกิน","exampleEn":"Your bag is overweight, so there is an extra charge.","exampleTh":"กระเป๋าของคุณน้ำหนักเกิน จึงมีค่าใช้จ่ายเพิ่ม","associationHintTh":"over = เกิน + weight = น้ำหนัก → น้ำหนักเกินกำหนด"},{"word":"scale","ipa":"/skeɪl/","thai":"เครื่องชั่งน้ำหนัก","exampleEn":"Put your suitcase on the scale.","exampleTh":"วางกระเป๋าของคุณบนเครื่องชั่ง","associationHintTh":"นึกถึงเครื่องชั่งที่มี 'สเกล' ตัวเลขบอกน้ำหนัก"}],"examples":[{"en":"I'd like to check in for my flight to Bangkok.","th":"ฉันต้องการเช็คอินสำหรับเที่ยวบินไปกรุงเทพฯ"},{"en":"Where can I find the check-in kiosk?","th":"ตู้เช็คอินอัตโนมัติอยู่ที่ไหน"},{"en":"Please scan your passport here. (hear)","th":"กรุณาสแกนพาสปอร์ตตรงนี้"},{"en":"Can I choose a window seat?","th":"ฉันขอเลือกที่นั่งริมหน้าต่างได้ไหม"},{"en":"Your bag is a little overweight. (hear)","th":"กระเป๋าของคุณน้ำหนักเกินนิดหน่อย"},{"en":"Is this the right counter for the bag drop?","th":"นี่คือเคาน์เตอร์หย่อนกระเป๋าที่ถูกต้องไหม"}],"quiz":[{"questionTh":"ตู้เช็คอินอัตโนมัติที่ให้เรากดเองเรียกว่าอะไร?","choices":["kiosk","trolley","gate","belt"],"answerIndex":0,"explainTh":"kiosk คือตู้เช็คอินอัตโนมัติที่ให้ผู้โดยสารสแกนพาสปอร์ตและพิมพ์บัตรขึ้นเครื่องเอง"},{"questionTh":"เจ้าหน้าที่พูดว่า \"Your bag is overweight.\" หมายความว่าอะไร?","choices":["กระเป๋าเบาเกินไป","กระเป๋าหนักเกินกำหนด","กระเป๋าหาย","กระเป๋าเปียก"],"answerIndex":1,"explainTh":"overweight = น้ำหนักเกินที่สายการบินกำหนด อาจต้องจ่ายค่าน้ำหนักเพิ่ม"},{"questionTh":"บัตรขึ้นเครื่องภาษาอังกฤษเรียกว่าอะไร?","choices":["passport","visa","boarding pass","receipt"],"answerIndex":2,"explainTh":"boarding pass คือบัตรขึ้นเครื่อง ต้องใช้แสดงที่ประตูทางออก"},{"questionTh":"อยากถามว่า \"ฉันหย่อนกระเป๋าตรงนี้ใช่ไหม\" ต้องพูดว่าอย่างไร?","choices":["What time is it?","How much is it?","Where is the toilet?","Do I drop my bag here?"],"answerIndex":3,"explainTh":"\"Do I drop my bag here?\" = ฉันหย่อนกระเป๋าตรงนี้ใช่ไหม ตัวเลือกอื่นเป็นคนละความหมาย"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 2, 'communication', $q$ช้อปดิวตี้ฟรีและคืนภาษี VAT ที่สนามบิน$q$, $q${"listen":{"audioText":"I bought this perfume, and I'd like to claim my VAT refund. May I see your receipts and passport, please? (hear) Here you are. Can I get the refund in cash? You can take cash here, or we can refund it to your credit card. (hear)","thaiExplain":"ในสนามบินมีร้านปลอดภาษี (duty-free) และเคาน์เตอร์คืนภาษี VAT สำหรับของที่ซื้อในประเทศ ให้เตรียมใบเสร็จ พาสปอร์ต และแบบฟอร์มคืนภาษี แล้วเลือกรับเงินคืนเป็นเงินสดหรือเข้าบัตรเครดิตก็ได้"},"vocab":[{"word":"duty-free","ipa":"/ˌduːti ˈfriː/","thai":"สินค้าปลอดภาษี","exampleEn":"I bought some chocolate at the duty-free shop.","exampleTh":"ฉันซื้อช็อกโกแลตที่ร้านปลอดภาษี","associationHintTh":"duty = ภาษีศุลกากร + free = ฟรี → ของที่ไม่ต้องเสียภาษี"},{"word":"tax refund","ipa":"/ˈtæks ˌriːfʌnd/","thai":"การคืนภาษี","exampleEn":"Tourists can get a tax refund at the airport.","exampleTh":"นักท่องเที่ยวขอคืนภาษีได้ที่สนามบิน","associationHintTh":"tax = ภาษี + refund (re=คืน, fund=เงิน) → คืนเงินภาษี"},{"word":"receipt","ipa":"/rɪˈsiːt/","thai":"ใบเสร็จ","exampleEn":"Keep your receipt for the tax refund.","exampleTh":"เก็บใบเสร็จไว้สำหรับขอคืนภาษี","associationHintTh":"อ่านว่า 'รีซีท' ตัว p ไม่ออกเสียง คือกระดาษที่ได้หลังจ่ายเงิน"},{"word":"VAT","ipa":"/væt/","thai":"ภาษีมูลค่าเพิ่ม","exampleEn":"You can claim the VAT back before you leave.","exampleTh":"คุณขอคืนภาษีมูลค่าเพิ่มได้ก่อนออกจากประเทศ","associationHintTh":"VAT ย่อจาก Value Added Tax เหมือน 'แวต' 7% ที่เราจ่ายในไทย"},{"word":"cash","ipa":"/kæʃ/","thai":"เงินสด","exampleEn":"Can I get the refund in cash?","exampleTh":"ขอรับเงินคืนเป็นเงินสดได้ไหม","associationHintTh":"'แคช' นึกถึง cashier แคชเชียร์ที่รับเงินสด"}],"examples":[{"en":"Where is the tax refund counter?","th":"เคาน์เตอร์คืนภาษีอยู่ที่ไหน"},{"en":"I'd like to claim a VAT refund.","th":"ฉันต้องการขอคืนภาษีมูลค่าเพิ่ม"},{"en":"Here are my receipts and passport.","th":"นี่คือใบเสร็จและพาสปอร์ตของฉัน"},{"en":"Is this item duty-free?","th":"สินค้าชิ้นนี้ปลอดภาษีไหม"},{"en":"Can I get the refund in cash?","th":"ขอรับเงินคืนเป็นเงินสดได้ไหม"},{"en":"Please keep the items in your hand luggage. (hear)","th":"กรุณาเก็บสินค้าไว้ในกระเป๋าถือขึ้นเครื่อง"}],"quiz":[{"questionTh":"\"duty-free\" หมายถึงอะไร?","choices":["สินค้าปลอดภาษี","สินค้าราคาแพง","สินค้าหมดอายุ","สินค้ามือสอง"],"answerIndex":0,"explainTh":"duty-free = สินค้าปลอดภาษีที่ขายในสนามบิน ราคามักถูกกว่าเพราะไม่มีภาษี"},{"questionTh":"ต้องใช้เอกสารอะไรในการขอคืนภาษี VAT?","choices":["ตั๋วหนัง","ใบเสร็จและพาสปอร์ต","รูปถ่าย","ใบขับขี่"],"answerIndex":1,"explainTh":"ต้องใช้ใบเสร็จ (receipt) และพาสปอร์ตเพื่อยืนยันการซื้อและตัวตนก่อนขอคืนภาษี"},{"questionTh":"อยากถามว่าเคาน์เตอร์คืนภาษีอยู่ที่ไหน ต้องพูดว่าอย่างไร?","choices":["What is your name?","How are you?","Where is the tax refund counter?","Can I have a bag?"],"answerIndex":2,"explainTh":"\"Where is the tax refund counter?\" = เคาน์เตอร์คืนภาษีอยู่ที่ไหน"},{"questionTh":"\"Can I get the refund in cash?\" หมายความว่าอะไร?","choices":["ขอส่วนลดได้ไหม","จ่ายด้วยบัตรได้ไหม","ขอใบเสร็จได้ไหม","ขอรับเงินคืนเป็นเงินสดได้ไหม"],"answerIndex":3,"explainTh":"refund in cash = รับเงินคืนเป็นเงินสด (แทนที่จะคืนเข้าบัตรเครดิต)"}]}$q$::jsonb);
  INSERT INTO lessons (id, unit_id, order_index, type, title_th, content_json)
  VALUES (gen_random_uuid(), u, 3, 'communication', $q$ไฟลต์ดีเลย์/ยกเลิก และจองเที่ยวบิน/ที่พักใหม่$q$, $q${"listen":{"audioText":"We're sorry. Flight TG917 to Bangkok has been delayed by three hours. (hear) My connecting flight has been cancelled. Can you rebook me on the next one? I can put you on tomorrow morning's flight and arrange a hotel for tonight. (hear) Thank you. How do I get to the hotel?","thaiExplain":"ถ้าไฟลต์ล่าช้า (delayed) หรือถูกยกเลิก (cancelled) ให้ไปที่เคาน์เตอร์สายการบินเพื่อขอจองเที่ยวบินใหม่ (rebook) และสอบถามเรื่องที่พักหรืออาหารที่สายการบินจัดให้ โดยเฉพาะเมื่อตกเที่ยวบินต่อเครื่อง"},"vocab":[{"word":"delayed","ipa":"/dɪˈleɪd/","thai":"ล่าช้า","exampleEn":"My flight has been delayed by two hours.","exampleTh":"เที่ยวบินของฉันล่าช้าไปสองชั่วโมง","associationHintTh":"ทับศัพท์ว่า 'ดีเลย์' คนไทยพูดกันอยู่แล้ว = ล่าช้า"},{"word":"cancelled","ipa":"/ˈkænsəld/","thai":"ถูกยกเลิก","exampleEn":"The flight was cancelled because of the storm.","exampleTh":"เที่ยวบินถูกยกเลิกเพราะพายุ","associationHintTh":"ทับศัพท์ว่า 'แคนเซิล' = ยกเลิก ใช้บ่อยในชีวิตประจำวัน"},{"word":"rebook","ipa":"/ˌriːˈbʊk/","thai":"จองใหม่","exampleEn":"Can you rebook me on the next flight?","exampleTh":"ช่วยจองเที่ยวบินถัดไปให้ฉันได้ไหม","associationHintTh":"re = ใหม่/อีกครั้ง + book = จอง → จองใหม่"},{"word":"connecting flight","ipa":"/kəˈnektɪŋ flaɪt/","thai":"เที่ยวบินต่อเครื่อง","exampleEn":"I missed my connecting flight in Dubai.","exampleTh":"ฉันตกเที่ยวบินต่อเครื่องที่ดูไบ","associationHintTh":"connect = เชื่อมต่อ → เที่ยวบินที่ต้องต่อเครื่องไปอีกทอด"},{"word":"accommodation","ipa":"/əˌkɒməˈdeɪʃən/","thai":"ที่พัก","exampleEn":"Will the airline provide accommodation tonight?","exampleTh":"สายการบินจะจัดที่พักให้คืนนี้ไหม","associationHintTh":"คำยาว แต่แปลว่าที่พัก นึกถึงโรงแรมที่ 'รองรับ' (accommodate) ผู้เข้าพัก"}],"examples":[{"en":"My flight has been delayed.","th":"เที่ยวบินของฉันล่าช้า"},{"en":"Has my flight been cancelled?","th":"เที่ยวบินของฉันถูกยกเลิกหรือเปล่า"},{"en":"Can you rebook me on the next flight?","th":"ช่วยจองเที่ยวบินถัดไปให้ฉันได้ไหม"},{"en":"I missed my connecting flight.","th":"ฉันตกเที่ยวบินต่อเครื่อง"},{"en":"Will the airline provide a hotel tonight?","th":"สายการบินจะจัดโรงแรมให้คืนนี้ไหม"},{"en":"How long is the delay?","th":"ล่าช้านานแค่ไหน"}],"quiz":[{"questionTh":"\"delayed\" แปลว่าอะไร?","choices":["ยกเลิก","ล่าช้า","ตรงเวลา","เต็ม"],"answerIndex":1,"explainTh":"delayed = ล่าช้า เที่ยวบินยังบินอยู่แต่ออกช้ากว่ากำหนด (ต่างจาก cancelled ที่ยกเลิก)"},{"questionTh":"อยากให้เจ้าหน้าที่จองเที่ยวบินถัดไปให้ ต้องพูดว่าอย่างไร?","choices":["Can you rebook me on the next flight?","Can I have a menu?","Where is my seat?","How much is the ticket?"],"answerIndex":0,"explainTh":"rebook = จองใหม่ ประโยคนี้ขอให้เจ้าหน้าที่จองเที่ยวบินถัดไปให้"},{"questionTh":"\"เที่ยวบินต่อเครื่อง\" ภาษาอังกฤษคือคำใด?","choices":["direct flight","return flight","connecting flight","domestic flight"],"answerIndex":2,"explainTh":"connecting flight = เที่ยวบินต่อเครื่อง ส่วน direct flight คือบินตรง"},{"questionTh":"ประกาศบอกว่า \"The flight has been cancelled.\" หมายความว่าอะไร?","choices":["เที่ยวบินออกตรงเวลา","เที่ยวบินล่าช้า","เที่ยวบินเปลี่ยนประตู","เที่ยวบินถูกยกเลิก"],"answerIndex":3,"explainTh":"cancelled = ถูกยกเลิก ต้องไปที่เคาน์เตอร์เพื่อขอจองเที่ยวบินใหม่"}]}$q$::jsonb);
  INSERT INTO scenarios (id, unit_id, title_th, setting_en, ai_role, user_goal_th, success_criteria_json)
  VALUES (gen_random_uuid(), u, $q$บทบาทสมมติ: จัดการขากลับบ้านที่สนามบิน (เช็คอิน คืนภาษี และไฟลต์ดีเลย์)$q$, $q$You are a friendly airline service desk agent at a busy international airport. The traveler is flying home to Bangkok, but their flight has just been delayed and their connecting flight may be affected. Help them check in and drop their bag, answer questions about duty-free and the VAT refund counter, and rebook their flight or arrange a hotel if needed. Speak in simple, clear English and be patient.$q$, $q$Airline Service Desk Agent$q$, $q$ผู้เรียนต้องเช็คอินขากลับและหย่อนกระเป๋าให้เรียบร้อย สอบถามเรื่องการคืนภาษี VAT และจัดการเมื่อไฟลต์ล่าช้า/ถูกยกเลิก โดยสื่อสารเป็นภาษาอังกฤษทั้งหมด$q$, $q$["เช็คอินและหย่อนกระเป๋าได้สำเร็จ พร้อมถามหรือตอบเรื่องน้ำหนักกระเป๋าได้","ถามเรื่องขั้นตอนการคืนภาษี VAT อย่างน้อย 1 คำถาม และเข้าใจคำตอบ","ขอจองเที่ยวบินใหม่ (rebook) หรือขอที่พักได้เมื่อไฟลต์ล่าช้า/ยกเลิก"]$q$::jsonb);
END IF;
END $do$;